INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C1','math',3,2,'u1',2,'(세 자리 수) × (한 자리 수) 올림 없음 — 세 자리 수를 백·십·일로 갈라 자리마다 곱해 자기 자리에 놓고, 0이 있는 자리는 0으로 쓰기',ARRAY['4수01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C2','math',3,2,'u1',3,'올림이 한 번 있는 (세 자리 수) × (한 자리 수) — 일의 자리나 십의 자리 곱이 10을 넘으면 윗자리로 올려 그 자리를 곱한 다음에 더하기',ARRAY['4수01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C3','math',3,2,'u1',3,'곱셈 어림하기 — 곱해지는 수·곱하는 수를 몇백·몇십으로 어림해 곱의 크기와 곱이 놓일 사이를 미리 가늠하고, 계산한 답과 견주어 확인하기',ARRAY['4수01-08']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C4','math',3,2,'u1',4,'올림이 여러 번 있는 (세 자리 수) × (한 자리 수) — 올림이 이어져 네 자리 곱이 되는 계산, 수 카드로 곱이 가장 큰·작은 곱셈식 만들기',ARRAY['4수01-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C5','math',3,2,'u1',5,'(몇십) × (몇십), (몇십몇) × (몇십) — 곱하는 수가 몇십이면 (몇)을 곱한 곱의 10배임을 알고 계산하기',ARRAY['4수01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C6','math',3,2,'u1',6,'(몇) × (몇십몇) — 곱하는 수를 몇십과 몇으로 갈라 각각 곱해 더하고, 두 수의 순서를 바꾸어 곱해도 곱이 같음을 알기',ARRAY['4수01-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C7','math',3,2,'u1',7,'(몇십몇) × (몇십몇) — 모눈을 네 덩이나 두 덩이로 갈라 곱해 더하고, 세로셈에서 십의 자리를 곱한 값을 한 자리 밀어 쓰기',ARRAY['4수01-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C8','math',3,2,'u1',8,'올림이 여러 번 있는 (몇십몇) × (몇십몇) — 두 줄 세로셈으로 네 자리 곱을 구하고, 앞 줄의 올림을 다음 줄에 섞지 않으며 어림한 사이에 드는지 확인하기',ARRAY['4수01-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u1-C9','math',3,2,'u1',9,'곱셈으로 문제 해결하기 — 「몇 배가 필요하다」를 곱셈식으로 세우고, 두 가지를 더하거나 견주는 두 단계 문제 해결하기',ARRAY['4수01-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X01','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2','M3-2-u1-C4']::text[],'한 자리만 곱하고 다른 자리 숫자는 그대로 내려 쓴다(213 × 3 = 219)','자리마다 모두 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X02','math',3,'u1',ARRAY['M3-2-u1-C2','M3-2-u1-C4','M3-2-u1-C8']::text[],'올림한 수를 윗자리에 더하지 않는다(217 × 2 = 424)','작게 적은 수에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X03','math',3,'u1',ARRAY['M3-2-u1-C2','M3-2-u1-C4']::text[],'올림한 수를 윗자리 숫자에 먼저 더한 뒤 곱한다(217 × 2 → (1 + 1) × 2)','곱한 다음에 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X04','math',3,'u1',ARRAY['M3-2-u1-C4']::text[],'자리별 곱을 올림하지 않고 그대로 이어 붙여 쓴다(274 × 7 → 144928)','10이 넘으면 윗자리로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X05','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2']::text[],'0이 있는 자리에 곱하는 수를 그대로 쓴다(0 × 3 = 3, 307 × 3 = 931)','0에 곱하면 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X06','math',3,'u1',ARRAY['M3-2-u1-C5','M3-2-u1-C9']::text[],'몇십을 곱할 때 10배를 빠뜨리거나 0을 더 붙인다(30 × 30 = 90·9000)','0을 떼고 곱한 뒤 10배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X07','math',3,'u1',ARRAY['M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8']::text[],'곱하는 수의 십의 자리를 곱한 값을 한 자리 밀어 쓰지 않는다(7 × 16 = 7 + 42 = 49)','십의 자리 곱은 몇십 곱') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X08','math',3,'u1',ARRAY['M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8']::text[],'갈라 곱한 두 곱 가운데 하나만 답으로 쓰고 더하지 않는다(24 × 13 = 72)','두 덩이를 모두 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X09','math',3,'u1',ARRAY['M3-2-u1-C7','M3-2-u1-C8']::text[],'일의 자리끼리, 십의 자리끼리만 곱한다(24 × 13 = 200 + 12 = 212)','네 덩이를 모두 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X10','math',3,'u1',ARRAY['M3-2-u1-C8']::text[],'앞 줄에서 올림한 수를 다음 줄 곱에 다시 더한다(39 × 26의 둘째 줄 39 × 2에 5를 더함)','줄마다 올림은 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X11','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2','M3-2-u1-C4','M3-2-u1-C5','M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8','M3-2-u1-C9']::text[],'곱셈구구나 더하는 계산에서 실수해 곱이 조금 크거나 작다','어림한 값과 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X12','math',3,'u1',ARRAY['M3-2-u1-C3']::text[],'어림할 때 가까운 몇백·몇십이 아닌 쪽으로 어림하거나 어림한 수끼리 곱하지 않는다','가까운 쪽으로 어림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X13','math',3,'u1',ARRAY['M3-2-u1-C9']::text[],'「몇 배」·「몇씩 몇 묶음」 상황에서 곱셈 대신 두 수를 더하거나 식을 잘못 세운다(31장의 20배 → 31 + 20)','「몇 배」는 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X14','math',3,'u1',ARRAY['M3-2-u1-C4']::text[],'곱을 가장 크게 만들 때 가장 큰 수를 곱해지는 수 맨 앞(백의 자리)에 놓는다','가장 큰 수는 곱하는 수 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X15','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2','M3-2-u1-C3','M3-2-u1-C4','M3-2-u1-C5','M3-2-u1-C6','M3-2-u1-C7','M3-2-u1-C8','M3-2-u1-C9']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 아닌↔맞는, 큰↔작은','물음의 「틀린·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X16','math',3,'u1',ARRAY['M3-2-u1-C6']::text[],'곱하는 두 수의 순서를 바꾸면 곱이 달라진다고 생각한다','순서를 바꾸어도 곱은 같다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X17','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2']::text[],'자리마다 곱한 값을 자릿값 없이 쓰거나 더한다(143 × 2 → 6 + 8 + 2 = 16, 142 × 4 → 8 + 16 + 400 = 424)','40 × 4는 16이 아니라 160 — 곱한 값을 그 자리에 맞춰 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X18','math',3,'u1',ARRAY['M3-2-u1-C1','M3-2-u1-C2','M3-2-u1-C4']::text[],'0이 있는 자리를 빼고 남은 숫자만 붙여 곱한다(206 × 6 → 26 × 6 = 156)','0도 자리를 지켜요 — 206은 2백 0십 6') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X20','math',3,'u1',ARRAY['M3-2-u1-C3']::text[],'어림한 값이 계산 결과와 똑같아야 하거나, 어림하는 방법은 한 가지뿐이라고 여긴다(29 × 13 어림 390·290·300 가운데 하나만 맞다고 함)','어림은 「약」 — 계산 결과와 비슷하면 알맞고, 어림하는 방법은 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u1-X21','math',3,'u1',ARRAY['M3-2-u1-C6']::text[],'곱이 같으면 두 곱셈식이 나타내는 상황도 같다고 여긴다(6 × 12와 12 × 6 — 6자루씩 12묶음과 12자루씩 6묶음을 같은 상황으로 봄)','곱은 같아도 「몇씩 몇 묶음」은 달라요 — × 앞은 한 묶음의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#1','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C9',1,'mc','auto','어린이 식품 안전 체험관에서 고구마를 캤어요. 「우리 반은 고구마를 한 상자에 6개씩 담았더니 38상자가 되었어.」 고구마의 수를 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13']::text[],true,'{"seq":1,"concept":"M3-2-u1-C9","difficulty":1,"kind":"mc","stem":"어린이 식품 안전 체험관에서 고구마를 캤어요. 「우리 반은 고구마를 한 상자에 6개씩 담았더니 38상자가 되었어.」 고구마의 수를 구하는 식은 어느 것인가요?","options":[{"t":"6 × 38","correct":true},{"t":"6 + 38","mis":"M3-2-u1-X13"},{"t":"38 − 6","mis":"M3-2-u1-X13"}],"explanation":["한 상자에 6개씩, 38상자예요.","6개씩 38묶음은 곱셈식 6 × 38로 나타내요.","두 수를 더하거나 빼면 상자 수만큼 묶음이 생기지 않아요."],"variant_rule":{"alt":[{"stem":"「우리 반은 고구마를 한 상자에 12개씩 담았더니 모두 19상자가 되었어.」 고구마의 수를 구하는 식은 어느 것인가요?","options":[{"t":"12 × 19","correct":true},{"t":"12 + 19","mis":"M3-2-u1-X13"},{"t":"19 − 12","mis":"M3-2-u1-X13"}],"explanation":["한 상자에 12개씩, 19상자예요.","12개씩 19묶음은 곱셈식 12 × 19로 나타내요.","이 단원에서는 곱해지는 수나 곱하는 수가 큰 곱셈을 배워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#2','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',1,'mc','auto','「준비하기」 — 76 × 5를 계산하면 얼마인가요?',ARRAY['M3-2-u1-X02','M3-2-u1-X04']::text[],true,'{"seq":2,"concept":"M3-2-u1-C1","difficulty":1,"kind":"mc","stem":"「준비하기」 — 76 × 5를 계산하면 얼마인가요?","options":[{"t":"380","correct":true},{"t":"350","mis":"M3-2-u1-X02"},{"t":"3530","mis":"M3-2-u1-X04"}],"explanation":["76을 70과 6으로 갈라요.","6 × 5 = 30에서 3을 십의 자리로 올리고, 7 × 5 = 35에 3을 더해 38이에요.","그래서 76 × 5 = 380이에요 — 3학년 1학기에 배운 곱셈이에요."],"variant_rule":{"alt":[{"stem":"「준비하기」 — 69 × 6을 계산하면 얼마인가요?","options":[{"t":"414","correct":true},{"t":"364","mis":"M3-2-u1-X02"},{"t":"3654","mis":"M3-2-u1-X04"}],"explanation":["69를 60과 9로 갈라요.","9 × 6 = 54에서 5를 십의 자리로 올리고, 6 × 6 = 36에 5를 더해 41이에요.","그래서 69 × 6 = 414예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#3','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',1,'sa','auto','천연 비료를 사용하여 키운 고구마를 한 자루에 143개씩 담았어요. 2자루에 담은 고구마는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"천연 비료를 사용하여 키운 고구마를 한 자루에 143개씩 담았어요. 2자루에 담은 고구마는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["286"],"explanation":["143개씩 2자루 — 143 × 2예요.","100 × 2 = 200, 40 × 2 = 80, 3 × 2 = 6이에요.","200 + 80 + 6 = 286 — 고구마는 286개예요."],"asset":{"type":"expr_grid","rows":[["100 × 2","=","200"],["40 × 2","=","80"],["3 × 2","=","6"],["200 + 80 + 6","=",null]]},"variant_rule":{"alt":[{"stem":"천연 비료를 사용하여 키운 고구마를 한 자루에 213개씩 3자루에 담았어요. 고구마는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["639"],"explanation":["213개씩 3자루 — 213 × 3이에요.","200 × 3 = 600, 10 × 3 = 30, 3 × 3 = 9예요.","600 + 30 + 9 = 639 — 고구마는 639개예요."],"asset":{"type":"expr_grid","rows":[["200 × 3","=","600"],["10 × 3","=","30"],["3 × 3","=","9"],["600 + 30 + 9","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#4','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',1,'mc','auto','143 × 2를 수 모형으로 나타냈어요. 143을 두 묶음 놓으면 백 모형, 십 모형, 일 모형은 각각 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X01']::text[],true,'{"seq":4,"concept":"M3-2-u1-C1","difficulty":1,"kind":"mc","stem":"143 × 2를 수 모형으로 나타냈어요. 143을 두 묶음 놓으면 백 모형, 십 모형, 일 모형은 각각 몇 개인가요?","options":[{"t":"백 모형 2개, 십 모형 8개, 일 모형 6개","correct":true},{"t":"백 모형 1개, 십 모형 4개, 일 모형 3개","mis":"M3-2-u1-X13"},{"t":"백 모형 2개, 십 모형 4개, 일 모형 3개","mis":"M3-2-u1-X01"}],"explanation":["백 모형은 1개씩 2묶음 — 100 × 2 = 200이에요.","십 모형은 4개씩 2묶음 — 40 × 2 = 80, 일 모형은 3개씩 2묶음 — 3 × 2 = 6이에요.","그래서 백 모형 2개, 십 모형 8개, 일 모형 6개 — 286이에요."],"variant_rule":{"alt":[{"stem":"314 × 2를 수 카드로 나타냈어요. 314를 두 줄 놓으면 백 카드, 십 카드, 일 카드는 각각 몇 개인가요?","options":[{"t":"백 카드 6개, 십 카드 2개, 일 카드 8개","correct":true},{"t":"백 카드 3개, 십 카드 1개, 일 카드 4개","mis":"M3-2-u1-X13"},{"t":"백 카드 6개, 십 카드 1개, 일 카드 4개","mis":"M3-2-u1-X01"}],"explanation":["백 카드 3개씩 2줄 — 300 × 2 = 600이에요.","십 카드 1개씩 2줄 — 10 × 2 = 20, 일 카드 4개씩 2줄 — 4 × 2 = 8이에요.","600 + 20 + 8 = 628 — 314 × 2 = 628이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#5','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'sa','auto','421 × 2를 세로셈으로 계산했어요. 곱은 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C1","difficulty":2,"kind":"sa","stem":"421 × 2를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["842"],"explanation":["421을 400, 20, 1로 갈라 2를 곱해요: 400 × 2 = 800, 20 × 2 = 40, 1 × 2 = 2.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","800 + 40 + 2 = 842예요."],"asset":{"type":"expr_grid","rows":[["","","4","2","1"],["×","","","","2"],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"320 × 3을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["960"],"explanation":["320을 300, 20, 0으로 갈라 3을 곱해요: 300 × 3 = 900, 20 × 3 = 60, 0 × 3 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","900 + 60 + 0 = 960이에요."],"asset":{"type":"expr_grid","rows":[["","","3","2","0"],["×","","","","3"],["","",null,null,null]]}},{"stem":"134 × 2를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["268"],"explanation":["134를 100, 30, 4로 갈라 2를 곱해요: 100 × 2 = 200, 30 × 2 = 60, 4 × 2 = 8.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","200 + 60 + 8 = 268이에요."],"asset":{"type":"expr_grid","rows":[["","","1","3","4"],["×","","","","2"],["","",null,null,null]]}},{"stem":"321 × 3을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["963"],"explanation":["321을 300, 20, 1로 갈라 3을 곱해요: 300 × 3 = 900, 20 × 3 = 60, 1 × 3 = 3.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","900 + 60 + 3 = 963이에요."],"asset":{"type":"expr_grid","rows":[["","","3","2","1"],["×","","","","3"],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#6','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'mc','auto','320 × 3은 얼마인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X18']::text[],true,'{"seq":6,"concept":"M3-2-u1-C1","difficulty":2,"kind":"mc","stem":"320 × 3은 얼마인가요?","options":[{"t":"960","correct":true},{"t":"963","mis":"M3-2-u1-X05"},{"t":"96","mis":"M3-2-u1-X18"}],"explanation":["320을 300, 20, 0으로 갈라 3을 곱해요: 300 × 3 = 900, 20 × 3 = 60, 0 × 3 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","900 + 60 + 0 = 960이에요 — 0 × 3 = 0이라 일의 자리는 0이에요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 103 × 3은 얼마인가요?","options":[{"t":"309","correct":true},{"t":"339","mis":"M3-2-u1-X05"},{"t":"39","mis":"M3-2-u1-X18"}],"explanation":["103을 100, 0, 3으로 갈라 3을 곱해요: 100 × 3 = 300, 0 × 3 = 0, 3 × 3 = 9.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","300 + 0 + 9 = 309예요 — 십의 자리 0 × 3 = 0이에요."]},{"stem":"「확인 문제」 — 420 × 2는 얼마인가요?","options":[{"t":"840","correct":true},{"t":"842","mis":"M3-2-u1-X05"},{"t":"84","mis":"M3-2-u1-X18"}],"explanation":["420을 400, 20, 0으로 갈라 2를 곱해요: 400 × 2 = 800, 20 × 2 = 40, 0 × 2 = 0.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","800 + 40 + 0 = 840이에요 — 0 × 2 = 0이라 일의 자리는 0이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#7','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'sa','auto','314 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u1-C1","difficulty":2,"kind":"sa","stem":"314 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["314를 300, 10, 4로 갈라요.","□는 10 × 2 = 20이에요.","600 + 20 + 8 = 628 — 314 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["300 × 2","=","600"],["10 × 2","=",null],["4 × 2","=","8"],["600 + □ + 8","=","628"]]},"variant_rule":{"alt":[{"stem":"143 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["200"],"explanation":["143을 100, 40, 3으로 갈라요.","□는 100 × 2 = 200이에요.","200 + 80 + 6 = 286 — 143 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 2","=",null],["40 × 2","=","80"],["3 × 2","=","6"],["□ + 80 + 6","=","286"]]}},{"stem":"213 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["213을 200, 10, 3으로 갈라요.","□는 3 × 3 = 9예요.","600 + 30 + 9 = 639 — 213 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["200 × 3","=","600"],["10 × 3","=","30"],["3 × 3","=",null],["600 + 30 + □","=","639"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#8','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'mc','auto','강낭콩이 한 봉지에 120개씩 들어 있습니다. 4봉지에 들어 있는 강낭콩은 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X05']::text[],true,'{"seq":8,"concept":"M3-2-u1-C1","difficulty":2,"kind":"mc","stem":"강낭콩이 한 봉지에 120개씩 들어 있습니다. 4봉지에 들어 있는 강낭콩은 모두 몇 개인가요?","options":[{"t":"480개","correct":true},{"t":"124개","mis":"M3-2-u1-X13"},{"t":"484개","mis":"M3-2-u1-X05"}],"explanation":["120개씩 4번 — 곱셈식 120 × 4로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","120 × 4 = 480 — 480개예요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 우표가 한 장에 430원입니다. 우표 2장은 모두 얼마인가요?","options":[{"t":"860원","correct":true},{"t":"432원","mis":"M3-2-u1-X13"},{"t":"862원","mis":"M3-2-u1-X05"}],"explanation":["430원씩 2번 — 곱셈식 430 × 2로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","430 × 2 = 860 — 860원이에요."]},{"stem":"어린이 도서관에는 책을 121권 꽂을 수 있는 책장이 4개 있습니다. 어린이 도서관에 꽂을 수 있는 책은 모두 몇 권인가요?","options":[{"t":"484권","correct":true},{"t":"125권","mis":"M3-2-u1-X13"},{"t":"16권","mis":"M3-2-u1-X17"}],"explanation":["121권씩 4번 — 곱셈식 121 × 4로 세워요.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","121 × 4 = 484 — 484권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#9','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C1","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"200 × 4","r":"800"},{"l":"223 × 2","r":"446"},{"l":"223 × 3","r":"669"}],"mis":"M3-2-u1-X01","explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","200 × 4 = 800, 223 × 2 = 446, 223 × 3 = 669.","곱이 비슷해 보여도 끝자리까지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"300 × 2","r":"600"},{"l":"213 × 3","r":"639"},{"l":"100 × 9","r":"900"}],"explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","300 × 2 = 600, 213 × 3 = 639, 100 × 9 = 900.","곱이 비슷해 보여도 끝자리까지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_basic#10','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_basic','lesson_basic','M3-2-u1-C1',3,'error','auto','143 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X17','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"143 × 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「143 × 2 = 16」","correct":true,"mis_target":"M3-2-u1-X17"},{"t":"건우 — 「3 × 2 = 6, 40 × 2 = 80, 100 × 2 = 200을 더하면 286」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「백 카드 2개, 십 카드 8개, 일 카드 6개라서 286」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","143 × 2 = 286이에요.","서준은 16으로 잘못 구했어요 — 곱한 값은 자릿값대로 써요."],"variant_rule":{"alt":[{"stem":"213 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「213 × 3 = 18」","correct":true,"mis_target":"M3-2-u1-X17"},{"t":"채원 — 「9 + 30 + 600 = 639」","mis":"M3-2-u1-X15"},{"t":"서준 — 「백 카드 6개, 십 카드 3개, 일 카드 9개라서 639」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","213 × 3 = 639예요.","지유는 18로 잘못 구했어요 — 곱한 값은 자릿값대로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#1','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',2,'mc','auto','계산 결과가 더 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],true,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":2,"kind":"mc","stem":"계산 결과가 더 큰 것은 어느 것인가요?","options":[{"t":"342 × 2","correct":true},{"t":"201 × 3","mis":"M3-2-u1-X11"},{"t":"두 곱이 같아요","mis":"M3-2-u1-X11"}],"explanation":["342 × 2 = 684예요.","201 × 3 = 603이에요.","684 > 603 — 342 × 2가 더 커요."],"variant_rule":{"alt":[{"stem":"어린이 도서관에는 121권을 꽂는 책장이 4개, 가족 도서관에는 214권을 꽂는 책장이 2개 있어요. 책을 더 많이 꽂을 수 있는 도서관은 어디인가요?","options":[{"t":"어린이 도서관","correct":true},{"t":"가족 도서관","mis":"M3-2-u1-X11"},{"t":"두 도서관이 같아요","mis":"M3-2-u1-X11"}],"explanation":["어린이 도서관: 121 × 4 = 484(권)이에요.","가족 도서관: 214 × 2 = 428(권)이에요.","484 > 428 — 어린이 도서관이에요. 한 책장에 꽂는 수가 많다고 더 많은 것은 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#2','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',2,'ox','auto','320 × 3을 계산할 때 일의 자리 0에 3을 곱하면 3이에요.',ARRAY['M3-2-u1-X05']::text[],true,'{"seq":2,"concept":"M3-2-u1-C1","difficulty":2,"kind":"ox","stem":"320 × 3을 계산할 때 일의 자리 0에 3을 곱하면 3이에요.","answer":"X","reason_options":[{"t":"0에 어떤 수를 곱해도 0이니까","correct":true},{"t":"곱하는 수를 그대로 내려 쓰면 되니까","mis":"M3-2-u1-X05"}],"mis":"M3-2-u1-X05","explanation":["0 × 3 = 0이에요.","300 × 3 = 900, 20 × 3 = 60, 0 × 3 = 0이에요.","그래서 320 × 3 = 960 — 일의 자리는 0이에요."],"variant_rule":{"alt":[{"stem":"103 × 3 = 309예요.","answer":"O","reason_options":[{"t":"100 × 3 = 300, 0 × 3 = 0, 3 × 3 = 9를 더하면 309니까","correct":true},{"t":"0이 있는 자리를 빼고 13 × 3을 하면 되니까","mis":"M3-2-u1-X18"}],"explanation":["103을 100, 0, 3으로 갈라요.","십의 자리 0 × 3 = 0이에요.","300 + 0 + 9 = 309 — 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#3','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'mc','auto','수 카드 0, 1, 2, 3을 한 번씩만 사용하여 계산 결과가 가장 큰 (세 자리 수) × (한 자리 수)를 만들려고 해요. 곱하는 수(한 자리 수)에는 어떤 카드를 놓아야 하나요?',ARRAY['M3-2-u1-X14','M3-2-u1-X15']::text[],false,'{"seq":3,"concept":"M3-2-u1-C1","difficulty":3,"kind":"mc","stem":"수 카드 0, 1, 2, 3을 한 번씩만 사용하여 계산 결과가 가장 큰 (세 자리 수) × (한 자리 수)를 만들려고 해요. 곱하는 수(한 자리 수)에는 어떤 카드를 놓아야 하나요?","options":[{"t":"3","correct":true},{"t":"1","mis":"M3-2-u1-X14"},{"t":"0","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수는 곱해지는 수의 모든 자리에 곱해져요.","그래서 가장 큰 수 3을 곱하는 수에 놓고, 남은 2, 1, 0으로 가장 큰 세 자리 수 210을 만들어요.","210 × 3 = 630 — 320 × 1 = 320보다 훨씬 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#4','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'sa','auto','223 × □ = 669에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C1","difficulty":3,"kind":"sa","stem":"223 × □ = 669에서 □ 안에 알맞은 수는 얼마인가요?","answer":["3"],"explanation":["223에 몇을 곱해야 669가 되는지 찾아요.","일의 자리 3 × □ = 9이니 □는 3이에요.","223 × 3 = 669 — 확인하면 맞아요."],"variant_rule":{"alt":[{"stem":"223 × □ = 446에서 □ 안에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["223에 몇을 곱해야 446이 되는지 찾아요.","일의 자리 3 × □ = 6이니 □는 2예요.","223 × 2 = 446 — 확인하면 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#5','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'mc','auto','314 × 2를 세로셈으로 계산하면 둘째 줄에 20을 써요. 20은 어떤 곱셈의 값인가요?',ARRAY['M3-2-u1-X17','M3-2-u1-X08']::text[],true,'{"seq":5,"concept":"M3-2-u1-C1","difficulty":3,"kind":"mc","stem":"314 × 2를 세로셈으로 계산하면 둘째 줄에 20을 써요. 20은 어떤 곱셈의 값인가요?","options":[{"t":"10 × 2","correct":true},{"t":"1 × 2","mis":"M3-2-u1-X17"},{"t":"314 × 2","mis":"M3-2-u1-X08"}],"explanation":["314의 십의 자리 숫자 1은 10을 나타내요.","그래서 둘째 줄은 10 × 2 = 20이에요.","8 + 20 + 600 = 628 — 314 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["","","3","1","4"],["×","","","","2"],["","","","","8"],["","","","2","0"],["","","6","0","0"],["","","6","2","8"]]},"variant_rule":{"alt":[{"stem":"314 × 2를 세로셈으로 계산하면 셋째 줄에 600을 써요. 600은 어떤 곱셈의 값인가요?","options":[{"t":"300 × 2","correct":true},{"t":"3 × 2","mis":"M3-2-u1-X17"},{"t":"300 + 2","mis":"M3-2-u1-X13"}],"explanation":["314의 백의 자리 숫자 3은 300을 나타내요.","그래서 셋째 줄은 300 × 2 = 600이에요.","8 + 20 + 600 = 628 — 314 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["","","3","1","4"],["×","","","","2"],["","","","","8"],["","","","2","0"],["","","6","0","0"],["","","6","2","8"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#6','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'ox','auto','143 × 2는 143개씩 2묶음이니까 계산 결과가 200보다 커야 해요.',ARRAY['M3-2-u1-X17']::text[],true,'{"seq":6,"concept":"M3-2-u1-C1","difficulty":3,"kind":"ox","stem":"143 × 2는 143개씩 2묶음이니까 계산 결과가 200보다 커야 해요.","answer":"O","reason_options":[{"t":"백 모형만 2개여도 200이니까","correct":true},{"t":"자리마다 곱한 6, 8, 2를 더하면 16이니까","mis":"M3-2-u1-X17"}],"mis":"M3-2-u1-X17","explanation":["143 × 2는 143을 두 번 더한 것과 같아요.","백 모형 2개만으로도 200이에요.","그래서 곱은 286 — 16처럼 작을 수 없어요."],"variant_rule":{"alt":[{"stem":"213 × 3은 213개씩 3묶음이니까 계산 결과가 600보다 커야 해요.","answer":"O","reason_options":[{"t":"백 모형만 6개여도 600이니까","correct":true},{"t":"자리마다 곱한 9, 3, 6을 더하면 18이니까","mis":"M3-2-u1-X17"}],"explanation":["213 × 3은 213을 세 번 더한 것과 같아요.","백 모형 6개만으로도 600이에요.","그래서 곱은 639예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#7','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',3,'sa','auto','어린이 도서관에는 책을 121권 꽂을 수 있는 책장이 4개, 가족 도서관에는 214권 꽂을 수 있는 책장이 2개 있어요. 어린이 도서관에 책을 몇 권 더 꽂을 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u1-C1","difficulty":3,"kind":"sa","stem":"어린이 도서관에는 책을 121권 꽂을 수 있는 책장이 4개, 가족 도서관에는 214권 꽂을 수 있는 책장이 2개 있어요. 어린이 도서관에 책을 몇 권 더 꽂을 수 있나요? 숫자로 쓰세요.","answer":["56"],"explanation":["어린이 도서관: 121 × 4 = 484(권)이에요.","가족 도서관: 214 × 2 = 428(권)이에요.","484 − 428 = 56 — 56권 더 꽂을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#8','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',4,'essay','teacher','고구마를 한 자루에 143개씩 2자루에 담았어요. 143 × 2를 수 카드로 계산하는 방법과 세로셈으로 계산하는 방법을 각각 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C1","difficulty":4,"kind":"essay","stem":"고구마를 한 자루에 143개씩 2자루에 담았어요. 143 × 2를 수 카드로 계산하는 방법과 세로셈으로 계산하는 방법을 각각 설명해 보세요.","answer_guide":{"answer":"예: 수 카드 — 143을 두 줄 놓으면 백 카드 2개, 십 카드 8개, 일 카드 6개라서 286이다. 세로셈 — 일의 자리 3 × 2 = 6, 십의 자리 40 × 2 = 80, 백의 자리 100 × 2 = 200을 더해 286이다.","scoring_points":["수 카드의 백·십·일 카드 수를 세어 286을 구했는가","자리마다 곱해 6, 80, 200을 구했는가","고구마 286개라고 답했는가"]},"explanation":["백 카드 2개, 십 카드 8개, 일 카드 6개 = 286.","3 × 2 = 6, 40 × 2 = 80, 100 × 2 = 200.","143 × 2 = 286 — 고구마는 286개."],"asset":{"type":"expr_grid","rows":[["100 × 2","=","200"],["40 × 2","=","80"],["3 × 2","=","6"],["200 + 80 + 6","=","286"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#9','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',4,'essay','teacher','건우는 143 × 2를 6, 8, 2로 구한 뒤 더해서 16이라고 했어요. 건우의 답이 맞는지 판단하고, 무엇을 잘못했는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C1","difficulty":4,"kind":"essay","stem":"건우는 143 × 2를 6, 8, 2로 구한 뒤 더해서 16이라고 했어요. 건우의 답이 맞는지 판단하고, 무엇을 잘못했는지 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 143개씩 2묶음은 200보다 커야 한다. 40 × 2 = 80, 100 × 2 = 200인데 건우는 8, 2로 써서 자릿값을 무시했다. 6 + 80 + 200 = 286이 바른 답이다.","scoring_points":["틀렸다고 판단했는가","자릿값(80, 200)을 무시했다고 설명했는가","바른 답 286을 구했는가"]},"explanation":["143개씩 2묶음은 200보다 커요.","십의 자리 곱은 80, 백의 자리 곱은 200이에요.","6 + 80 + 200 = 286 — 16은 자릿값을 빼먹은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L02_challenge#10','math',3,2,'u1','L02','tb_g3_2_math_u1_L02_challenge','lesson_challenge','M3-2-u1-C1',4,'sa','auto','수 카드 0, 1, 2, 3을 한 번씩만 사용하여 계산 결과가 가장 큰 (세 자리 수) × (한 자리 수)를 만들었어요. 그 곱은 얼마인가요?','{}'::text[],false,'{"seq":10,"concept":"M3-2-u1-C1","difficulty":4,"kind":"sa","stem":"수 카드 0, 1, 2, 3을 한 번씩만 사용하여 계산 결과가 가장 큰 (세 자리 수) × (한 자리 수)를 만들었어요. 그 곱은 얼마인가요?","answer":["630"],"explanation":["가장 큰 수 3을 곱하는 수에 놓아요.","남은 2, 1, 0으로 가장 큰 세 자리 수 210을 만들어요.","210 × 3 = 630 — 가장 큰 곱이에요."],"asset":{"type":"expr_grid","rows":[["0","1","2","3"],["□","□","□","× □"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#1','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',1,'mc','auto','채원이는 주말농장에서 블루베리를 수확해 한 바구니에 217개씩 2바구니에 담았어요. 블루베리의 수를 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13']::text[],true,'{"seq":1,"concept":"M3-2-u1-C2","difficulty":1,"kind":"mc","stem":"채원이는 주말농장에서 블루베리를 수확해 한 바구니에 217개씩 2바구니에 담았어요. 블루베리의 수를 구하는 식은 어느 것인가요?","options":[{"t":"217 × 2","correct":true},{"t":"217 + 2","mis":"M3-2-u1-X13"},{"t":"217 + 217 + 217","mis":"M3-2-u1-X13"}],"explanation":["한 바구니에 217개씩, 2바구니예요.","217개씩 2묶음은 217 × 2예요.","217을 두 번 더한 것과 같아요 — 세 번이 아니에요."],"variant_rule":{"alt":[{"stem":"주말농장에서 수확한 블루베리를 바구니 한 개에 241개씩 바구니 3개에 담았어요. 블루베리의 수를 구하는 식은 어느 것인가요?","options":[{"t":"241 × 3","correct":true},{"t":"241 + 3","mis":"M3-2-u1-X13"},{"t":"241 + 241","mis":"M3-2-u1-X13"}],"explanation":["한 바구니에 241개씩, 3바구니예요.","241개씩 3묶음은 241 × 3이에요.","241을 세 번 더한 것과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#2','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','블루베리 217개씩 2바구니 — 217을 200으로 생각하면 블루베리는 약 몇 개인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],true,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"블루베리 217개씩 2바구니 — 217을 200으로 생각하면 블루베리는 약 몇 개인가요?","options":[{"t":"약 400개","correct":true},{"t":"약 200개","mis":"M3-2-u1-X12"},{"t":"약 4000개","mis":"M3-2-u1-X06"}],"explanation":["217은 200에 가까워요.","200 × 2 = 400이에요.","그래서 약 400개 — 계산 결과 434와 비슷해요."],"variant_rule":{"alt":[{"stem":"비행기 한 대에 328명씩 탈 수 있어요. 328을 300으로 생각하면 비행기 3대에 탈 수 있는 사람은 몇 명보다 많을까요?","options":[{"t":"900명","correct":true},{"t":"300명","mis":"M3-2-u1-X12"},{"t":"9000명","mis":"M3-2-u1-X06"}],"explanation":["328은 300보다 커요.","300 × 3 = 900이에요.","그래서 328 × 3은 900보다 커요 — 계산하면 984명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#3','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',1,'sa','auto','217 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"217 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["14"],"explanation":["217을 200, 10, 7로 갈라요.","□는 7 × 2 = 14예요.","400 + 20 + 14 = 434 — 217 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["200 × 2","=","400"],["10 × 2","=","20"],["7 × 2","=",null],["400 + 20 + □","=","434"]]},"variant_rule":{"alt":[{"stem":"132 × 4를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["120"],"explanation":["132를 100, 30, 2로 갈라요.","□는 30 × 4 = 120이에요.","400 + 120 + 8 = 528 — 132 × 4의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 4","=","400"],["30 × 4","=",null],["2 × 4","=","8"],["400 + □ + 8","=","528"]]}},{"stem":"136 × 2를 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["12"],"explanation":["136을 100, 30, 6으로 갈라요.","□는 6 × 2 = 12예요.","200 + 60 + 12 = 272 — 136 × 2의 곱이에요."],"asset":{"type":"expr_grid","rows":[["100 × 2","=","200"],["30 × 2","=","60"],["6 × 2","=",null],["200 + 60 + □","=","272"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#4','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',1,'sa','auto','217 × 2를 세로셈으로 계산했어요. 곱은 얼마인가요?','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"217 × 2를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["434"],"explanation":["217을 200, 10, 7로 갈라 2를 곱해요: 200 × 2 = 400, 10 × 2 = 20, 7 × 2 = 14.","일의 자리 7 × 2 = 14에서 1을 십의 자리로 올림해요.","400 + 20 + 14 = 434예요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","1","7"],["×","","","","2"],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"132 × 4를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["528"],"explanation":["132를 100, 30, 2로 갈라 4를 곱해요: 100 × 4 = 400, 30 × 4 = 120, 2 × 4 = 8.","십의 자리 3 × 4 = 12에서 1을 백의 자리로 올림해요.","400 + 120 + 8 = 528이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","3","2"],["×","","","","4"],["","",null,null,null]]}},{"stem":"114 × 6을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["684"],"explanation":["114를 100, 10, 4로 갈라 6을 곱해요: 100 × 6 = 600, 10 × 6 = 60, 4 × 6 = 24.","일의 자리 4 × 6 = 24에서 2를 십의 자리로 올림해요.","600 + 60 + 24 = 684예요."],"asset":{"type":"expr_grid","rows":[["올림","","","2",""],["","","1","1","4"],["×","","","","6"],["","",null,null,null]]}},{"stem":"106 × 8을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["848"],"explanation":["106을 100, 0, 6으로 갈라 8을 곱해요: 100 × 8 = 800, 0 × 8 = 0, 6 × 8 = 48.","일의 자리 6 × 8 = 48에서 4를 십의 자리로 올림해요.","800 + 0 + 48 = 848이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","4",""],["","","1","0","6"],["×","","","","8"],["","",null,null,null]]}},{"stem":"282 × 2를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["564"],"explanation":["282를 200, 80, 2로 갈라 2를 곱해요: 200 × 2 = 400, 80 × 2 = 160, 2 × 2 = 4.","십의 자리 8 × 2 = 16에서 1을 백의 자리로 올림해요.","400 + 160 + 4 = 564예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","2","8","2"],["×","","","","2"],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#5','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'mc','auto','217 × 2를 세로셈으로 계산할 때, 7 × 2 = 14에서 십의 자리 위에 작게 쓴 1은 얼마를 나타내나요?',ARRAY['M3-2-u1-X17']::text[],true,'{"seq":5,"concept":"M3-2-u1-C2","difficulty":2,"kind":"mc","stem":"217 × 2를 세로셈으로 계산할 때, 7 × 2 = 14에서 십의 자리 위에 작게 쓴 1은 얼마를 나타내나요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M3-2-u1-X17"},{"t":"100","mis":"M3-2-u1-X17"}],"explanation":["14는 10이 1개, 1이 4개예요.","일의 자리에는 4를 쓰고 10은 십의 자리로 올려 1로 작게 써요.","그래서 작게 쓴 1은 10을 나타내요 — 십의 자리 곱 20에 더해 30이에요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","1","7"],["×","","","","2"],["","","4","3","4"]]},"variant_rule":{"alt":[{"stem":"132 × 4를 세로셈으로 계산할 때, 십의 자리 3 × 4 = 12에서 백의 자리 위에 작게 쓴 1은 얼마를 나타내나요?","options":[{"t":"100","correct":true},{"t":"1","mis":"M3-2-u1-X17"},{"t":"10","mis":"M3-2-u1-X17"}],"explanation":["십의 자리 3 × 4 = 12는 30 × 4 = 120이에요.","120의 100은 백의 자리로 올려 1로 작게 써요.","그래서 작게 쓴 1은 100을 나타내요 — 400에 더해 500이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","1","3","2"],["×","","","","4"],["","","5","2","8"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#6','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'mc','auto','한 대에 328명씩 탈 수 있는 비행기가 있습니다. 이 비행기 3대에 탈 수 있는 사람은 모두 몇 명인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02']::text[],true,'{"seq":6,"concept":"M3-2-u1-C2","difficulty":2,"kind":"mc","stem":"한 대에 328명씩 탈 수 있는 비행기가 있습니다. 이 비행기 3대에 탈 수 있는 사람은 모두 몇 명인가요?","options":[{"t":"984명","correct":true},{"t":"331명","mis":"M3-2-u1-X13"},{"t":"964명","mis":"M3-2-u1-X02"}],"explanation":["328명씩 3번 — 곱셈식 328 × 3으로 세워요.","일의 자리 8 × 3 = 24에서 2를 십의 자리로 올림해요.","328 × 3 = 984 — 984명이에요."],"variant_rule":{"alt":[{"stem":"퍼즐 한 상자에 퍼즐 조각이 150개씩 들어 있습니다. 퍼즐 6상자에 들어 있는 퍼즐 조각은 모두 몇 개인가요?","options":[{"t":"900개","correct":true},{"t":"156개","mis":"M3-2-u1-X13"},{"t":"600개","mis":"M3-2-u1-X02"}],"explanation":["150개씩 6번 — 곱셈식 150 × 6으로 세워요.","십의 자리 5 × 6 = 30에서 3을 백의 자리로 올림해요.","150 × 6 = 900 — 900개예요."]},{"stem":"「확인 문제」 — 벽돌이 한 묶음에 153장씩 묶여 있습니다. 3묶음의 벽돌은 모두 몇 장인가요?","options":[{"t":"459장","correct":true},{"t":"156장","mis":"M3-2-u1-X13"},{"t":"359장","mis":"M3-2-u1-X02"}],"explanation":["153장씩 3번 — 곱셈식 153 × 3으로 세워요.","십의 자리 5 × 3 = 15에서 1을 백의 자리로 올림해요.","153 × 3 = 459 — 459장이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#7','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'mc','auto','계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  218 × 4 ○ 121 × 7',ARRAY['M3-2-u1-X11','M3-2-u1-X12']::text[],false,'{"seq":7,"concept":"M3-2-u1-C2","difficulty":2,"kind":"mc","stem":"계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  218 × 4 ○ 121 × 7","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X12"}],"explanation":["218 × 4 = 872예요.","121 × 7 = 847이에요.","872 > 847이므로 218 × 4 > 121 × 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#8','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'sa','auto','117에 3을 곱한 수에 다시 2를 곱하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C2","difficulty":2,"kind":"sa","stem":"117에 3을 곱한 수에 다시 2를 곱하면 얼마인가요? 숫자로 쓰세요.","answer":["702"],"explanation":["117 × 3 = 351이에요.","351 × 2를 해요: 1 × 2 = 2, 5 × 2 = 10에서 1을 백의 자리로 올림, 3 × 2 + 1 = 7.","351 × 2 = 702 — 십의 자리는 0이에요."],"asset":{"type":"expr_grid","rows":[["117 × 3","=","351"],["351 × 2","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#9','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"114 × 6","r":"684"},{"l":"106 × 8","r":"848"},{"l":"282 × 2","r":"564"}],"mis":"M3-2-u1-X02","explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","114 × 6 = 684, 106 × 8 = 848, 282 × 2 = 564.","곱이 비슷해 보여도 끝자리까지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"416 × 2","r":"832"},{"l":"271 × 3","r":"813"},{"l":"232 × 4","r":"928"}],"explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","416 × 2 = 832, 271 × 3 = 813, 232 × 4 = 928.","곱이 비슷해 보여도 끝자리까지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_basic#10','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_basic','lesson_basic','M3-2-u1-C2',3,'mc','auto','서준이는 줄넘기를 매일 142회씩 합니다. 친구가 4일 동안 한 줄넘기 횟수 142 × 4를 오른쪽처럼 계산했어요. 잘못 계산한 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],true,'{"seq":10,"concept":"M3-2-u1-C2","difficulty":3,"kind":"mc","stem":"서준이는 줄넘기를 매일 142회씩 합니다. 친구가 4일 동안 한 줄넘기 횟수 142 × 4를 오른쪽처럼 계산했어요. 잘못 계산한 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"40 × 4 = 160인데 16으로 썼어요","correct":true},{"t":"2 × 4 = 8이 틀렸어요","mis":"M3-2-u1-X11"},{"t":"100 × 4 = 400이 틀렸어요","mis":"M3-2-u1-X11"}],"explanation":["142의 4는 십의 자리 숫자라 40을 나타내요.","40 × 4 = 160이라 둘째 줄은 160이에요.","8 + 160 + 400 = 568 — 서준이는 4일 동안 568회 했어요."],"asset":{"type":"expr_grid","rows":[["","","1","4","2"],["×","","","","4"],["","","","","8"],["","","","1","6"],["","","4","0","0"],["","","4","2","4"]]},"variant_rule":{"alt":[{"stem":"친구가 217 × 2를 오른쪽처럼 계산해 424라고 했어요. 잘못 계산한 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"7 × 2 = 14에서 올림한 1을 십의 자리에 더하지 않았어요","correct":true},{"t":"200 × 2 = 400이 틀렸어요","mis":"M3-2-u1-X11"},{"t":"일의 자리에 14를 모두 썼어요","mis":"M3-2-u1-X04"}],"explanation":["7 × 2 = 14 — 4를 쓰고 1을 십의 자리로 올려요.","십의 자리는 1 × 2 = 2에 올림한 1을 더해 3이에요.","그래서 217 × 2 = 434예요."],"asset":{"type":"expr_grid","rows":[["","","2","1","7"],["×","","","","2"],["","","4","2","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#1','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',2,'ox','auto','132 × 4 = 428이에요.',ARRAY['M3-2-u1-X02']::text[],true,'{"seq":1,"concept":"M3-2-u1-C2","difficulty":2,"kind":"ox","stem":"132 × 4 = 428이에요.","answer":"X","reason_options":[{"t":"3 × 4 = 12에서 올림한 1을 백의 자리에 더하면 528이니까","correct":true},{"t":"자리마다 곱한 수만 차례로 쓰면 되니까","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["2 × 4 = 8, 3 × 4 = 12에서 2를 쓰고 1을 백의 자리로 올려요.","백의 자리는 1 × 4 = 4에 올림한 1을 더해 5예요.","그래서 132 × 4 = 528이에요."],"variant_rule":{"alt":[{"stem":"282 × 2 = 564예요.","answer":"O","reason_options":[{"t":"8 × 2 = 16에서 올림한 1을 백의 자리 2 × 2에 더하면 5니까","correct":true},{"t":"올림한 수는 버리고 464라고 써야 하니까","mis":"M3-2-u1-X02"}],"explanation":["2 × 2 = 4예요.","8 × 2 = 16에서 6을 쓰고 1을 백의 자리로 올려요.","2 × 2 + 1 = 5 — 282 × 2 = 564예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#2','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C3',2,'mc','auto','217 × 2를 어림한 값과 계산 결과를 비교한 말로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u1-X20']::text[],true,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"217 × 2를 어림한 값과 계산 결과를 비교한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"어림한 값 약 400과 계산 결과 434가 비슷하니 계산 결과가 적절해요","correct":true},{"t":"어림한 값 400과 계산 결과 434가 똑같지 않으니 계산이 틀렸어요","mis":"M3-2-u1-X20"},{"t":"어림한 값이 400이니 217 × 2는 400이에요","mis":"M3-2-u1-X20"}],"explanation":["217을 200으로 생각하면 약 400이에요.","계산 결과는 434예요.","어림한 값은 「약」이라 계산 결과와 비슷하면 적절해요."],"variant_rule":{"alt":[{"stem":"비행기 3대에 탈 수 있는 사람 수 328 × 3을 어림한 값과 계산 결과를 비교한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"어림한 값 약 900과 계산 결과 984가 비슷하니 계산 결과가 적절해요","correct":true},{"t":"어림한 값 900과 계산 결과 984가 다르니 계산이 틀렸어요","mis":"M3-2-u1-X20"},{"t":"어림한 값이 900이니 328 × 3은 900이에요","mis":"M3-2-u1-X20"}],"explanation":["328을 300으로 생각하면 약 900이에요.","계산 결과는 984예요.","어림한 값과 비슷하니 계산 결과가 적절해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#3','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'sa','auto','329 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":3,"kind":"sa","stem":"329 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["987"],"explanation":["329를 300, 20, 9로 갈라 3을 곱해요: 300 × 3 = 900, 20 × 3 = 60, 9 × 3 = 27.","일의 자리 9 × 3 = 27에서 2를 십의 자리로 올림해요.","900 + 60 + 27 = 987이에요."],"variant_rule":{"alt":[{"stem":"416 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["832"],"explanation":["416을 400, 10, 6으로 갈라 2를 곱해요: 400 × 2 = 800, 10 × 2 = 20, 6 × 2 = 12.","일의 자리 6 × 2 = 12에서 1을 십의 자리로 올림해요.","800 + 20 + 12 = 832예요."]},{"stem":"271 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["813"],"explanation":["271을 200, 70, 1로 갈라 3을 곱해요: 200 × 3 = 600, 70 × 3 = 210, 1 × 3 = 3.","십의 자리 7 × 3 = 21에서 2를 백의 자리로 올림해요.","600 + 210 + 3 = 813이에요."]},{"stem":"232 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["928"],"explanation":["232를 200, 30, 2로 갈라 4를 곱해요: 200 × 4 = 800, 30 × 4 = 120, 2 × 4 = 8.","십의 자리 3 × 4 = 12에서 1을 백의 자리로 올림해요.","800 + 120 + 8 = 928이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#4','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'error','auto','132 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X02','M3-2-u1-X15']::text[],true,'{"seq":4,"concept":"M3-2-u1-C2","difficulty":3,"kind":"error","stem":"132 × 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「132 × 4 = 428」","correct":true,"mis_target":"M3-2-u1-X02"},{"t":"건우 — 「400 + 120 + 8 = 528」","mis":"M3-2-u1-X15"},{"t":"지유 — 「백 카드 5개, 십 카드 2개, 일 카드 8개라서 528」","mis":"M3-2-u1-X15"}],"explanation":["십의 자리 3 × 4 = 12에서 1을 백의 자리로 올림해요.","132 × 4 = 528이에요.","채원은 428로 잘못 구했어요 — 올림한 수를 윗자리 곱에 더해요."],"variant_rule":{"alt":[{"stem":"106 × 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「106 × 8 = 928」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"서준 — 「6 × 8 = 48의 4를 십의 자리로 올려 848」","mis":"M3-2-u1-X15"},{"t":"채원 — 「800 + 0 + 48 = 848」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 6 × 8 = 48에서 4를 십의 자리로 올림해요.","106 × 8 = 848이에요.","도윤은 928로 잘못 구했어요 — 0에 어떤 수를 곱해도 0이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#5','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'mc','auto','114 × 6을 계산할 때 4 × 6 = 24에서 올림한 2는 어떻게 하나요?',ARRAY['M3-2-u1-X03','M3-2-u1-X02']::text[],true,'{"seq":5,"concept":"M3-2-u1-C2","difficulty":3,"kind":"mc","stem":"114 × 6을 계산할 때 4 × 6 = 24에서 올림한 2는 어떻게 하나요?","options":[{"t":"십의 자리 1 × 6을 곱한 다음 2를 더해요","correct":true},{"t":"십의 자리 1에 2를 먼저 더한 뒤 6을 곱해요","mis":"M3-2-u1-X03"},{"t":"올림한 2는 버려요","mis":"M3-2-u1-X02"}],"explanation":["4 × 6 = 24 — 4를 쓰고 2를 십의 자리로 올려요.","십의 자리 1 × 6 = 6을 곱한 다음 올림한 2를 더해 8이에요.","114 × 6 = 684 — 먼저 더하면 (1 + 2) × 6 = 18이 되어 틀려요."],"variant_rule":{"alt":[{"stem":"328 × 3을 계산할 때 8 × 3 = 24에서 올림한 2는 어떻게 하나요?","options":[{"t":"십의 자리 2 × 3을 곱한 다음 2를 더해요","correct":true},{"t":"십의 자리 2에 2를 먼저 더한 뒤 3을 곱해요","mis":"M3-2-u1-X03"},{"t":"올림한 2는 버려요","mis":"M3-2-u1-X02"}],"explanation":["8 × 3 = 24 — 4를 쓰고 2를 십의 자리로 올려요.","십의 자리 2 × 3 = 6을 곱한 다음 올림한 2를 더해 8이에요.","328 × 3 = 984예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#6','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C3',3,'mc','auto','200 × 2 = 400처럼 어림한 값이 약 400인 곱셈이 아닌 것은 어느 것인가요?',ARRAY['M3-2-u1-X15']::text[],false,'{"seq":6,"concept":"M3-2-u1-C3","difficulty":3,"kind":"mc","stem":"200 × 2 = 400처럼 어림한 값이 약 400인 곱셈이 아닌 것은 어느 것인가요?","options":[{"t":"241 × 3","correct":true},{"t":"217 × 2","mis":"M3-2-u1-X15"},{"t":"132 × 4","mis":"M3-2-u1-X15"}],"explanation":["217 × 2는 217을 200으로 보면 약 400이에요.","132 × 4는 132를 100으로 보면 약 400이에요.","241 × 3은 241을 200으로 보면 약 600 — 400이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#7','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',3,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":7,"concept":"M3-2-u1-C2","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"106 × 8","correct":true},{"t":"114 × 6","mis":"M3-2-u1-X12"},{"t":"282 × 2","mis":"M3-2-u1-X12"}],"explanation":["114 × 6 = 684, 106 × 8 = 848, 282 × 2 = 564예요.","곱해지는 수가 크다고 곱이 큰 것은 아니에요.","곱하는 수 8이 커서 106 × 8이 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#8','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',4,'essay','teacher','217 × 2를 어림하고 계산한 뒤, 어림한 값과 계산 결과를 비교해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C2","difficulty":4,"kind":"essay","stem":"217 × 2를 어림하고 계산한 뒤, 어림한 값과 계산 결과를 비교해 보세요.","answer_guide":{"answer":"예: 217을 200으로 생각하면 약 400이다. 7 × 2 = 14에서 4를 쓰고 1을 올리고, 1 × 2 + 1 = 3, 2 × 2 = 4이므로 434이다. 어림한 값 400과 434가 비슷하므로 계산 결과가 적절하다.","scoring_points":["약 400으로 어림했는가","올림을 바르게 하여 434를 구했는가","어림한 값과 견주어 적절하다고 썼는가"]},"explanation":["어림: 200 × 2 = 400.","계산: 217 × 2 = 434.","400과 434가 비슷 — 계산 결과가 적절해요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","2","1","7"],["×","","","","2"],["","","4","3","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#9','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',4,'essay','teacher','서준이는 줄넘기를 매일 142회씩 4일 동안 했어요. 친구는 142 × 4를 8 + 16 + 400 = 424라고 했어요. 잘못 계산한 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":4,"kind":"essay","stem":"서준이는 줄넘기를 매일 142회씩 4일 동안 했어요. 친구는 142 × 4를 8 + 16 + 400 = 424라고 했어요. 잘못 계산한 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 40 × 4 = 160인데 16으로 써서 틀렸다. 142의 4는 40을 나타내기 때문이다. 바르게 계산하면 8 + 160 + 400 = 568이므로 568회이다.","scoring_points":["16이 잘못되었다고 찾았는가","4가 40을 나타내 160이라고 설명했는가","568회를 구했는가"]},"explanation":["142의 4는 40이에요.","40 × 4 = 160이에요.","8 + 160 + 400 = 568 — 568회예요."],"asset":{"type":"expr_grid","rows":[["","","1","4","2"],["×","","","","4"],["","","","","8"],["","","","1","6"],["","","4","0","0"],["","","4","2","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L03_challenge#10','math',3,2,'u1','L03','tb_g3_2_math_u1_L03_challenge','lesson_challenge','M3-2-u1-C2',4,'sa','auto','2□6 × 3 = 678에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],false,'{"seq":10,"concept":"M3-2-u1-C2","difficulty":4,"kind":"sa","stem":"2□6 × 3 = 678에서 □ 안에 알맞은 수는 얼마인가요?","answer":["2"],"explanation":["일의 자리 6 × 3 = 18 — 8을 쓰고 1을 십의 자리로 올려요.","십의 자리는 □ × 3에 1을 더해 7이므로 □ × 3 = 6이에요.","그래서 □ = 2 — 226 × 3 = 678이에요."],"asset":{"type":"expr_grid","rows":[["","2","□","6"],["×","","","3"],["","6","7","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#1','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','방울토마토가 한 상자에 426개씩 들어 있어요. 3상자에 들어 있는 방울토마토는 약 몇 개인지 426을 400으로 생각하여 어림해 보세요.',ARRAY['M3-2-u1-X06']::text[],true,'{"seq":1,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"방울토마토가 한 상자에 426개씩 들어 있어요. 3상자에 들어 있는 방울토마토는 약 몇 개인지 426을 400으로 생각하여 어림해 보세요.","options":[{"t":"약 1200개","correct":true},{"t":"약 120개","mis":"M3-2-u1-X06"},{"t":"약 12000개","mis":"M3-2-u1-X06"}],"explanation":["426은 400에 가까워요.","400 × 3 = 1200이에요.","그래서 약 1200개 — 계산 결과 1278과 비슷해요."],"variant_rule":{"alt":[{"stem":"바둑돌이 한 통에 189개 들어 있어요. 2통에 들어 있는 바둑돌의 수를 189를 200으로 생각하여 어림해 보세요.","options":[{"t":"약 400개","correct":true},{"t":"약 200개","mis":"M3-2-u1-X12"},{"t":"약 4000개","mis":"M3-2-u1-X06"}],"explanation":["189는 200에 가까워요.","200 × 2 = 400이에요.","그래서 약 400개 — 계산하면 378개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#2','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',1,'sa','auto','426 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"426 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["18"],"explanation":["426을 400, 20, 6으로 갈라요.","□는 6 × 3 = 18이에요.","1200 + 60 + 18 = 1278 — 426 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["400 × 3","=","1200"],["20 × 3","=","60"],["6 × 3","=",null],["1200 + 60 + □","=","1278"]]},"variant_rule":{"alt":[{"stem":"534 × 3을 자리마다 곱해 더했어요. □에 알맞은 수를 쓰세요.","answer":["90"],"explanation":["534를 500, 30, 4로 갈라요.","□는 30 × 3 = 90이에요.","1500 + 90 + 12 = 1602 — 534 × 3의 곱이에요."],"asset":{"type":"expr_grid","rows":[["500 × 3","=","1500"],["30 × 3","=",null],["4 × 3","=","12"],["1500 + □ + 12","=","1602"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#3','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',1,'sa','auto','274 × 7을 세로셈으로 계산했어요. 곱은 얼마인가요?','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"274 × 7을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["1918"],"explanation":["274를 200, 70, 4로 갈라 7을 곱해요: 200 × 7 = 1400, 70 × 7 = 490, 4 × 7 = 28.","일의 자리 4 × 7 = 28에서 2를 십의 자리로 올림, 십의 자리 7 × 7 + 2 = 51에서 5를 백의 자리로 올림, 백의 자리 2 × 7 + 5 = 19예요.","1400 + 490 + 28 = 1918이에요."],"asset":{"type":"expr_grid","rows":[["올림","","5","2",""],["","","2","7","4"],["×","","","","7"],["",null,null,null,null]]},"variant_rule":{"alt":[{"stem":"136 × 4를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["544"],"explanation":["136을 100, 30, 6으로 갈라 4를 곱해요: 100 × 4 = 400, 30 × 4 = 120, 6 × 4 = 24.","일의 자리 6 × 4 = 24에서 2를 십의 자리로 올림, 십의 자리 3 × 4 + 2 = 14에서 1을 백의 자리로 올림해요.","400 + 120 + 24 = 544예요."],"asset":{"type":"expr_grid","rows":[["올림","","1","2",""],["","","1","3","6"],["×","","","","4"],["","",null,null,null]]}},{"stem":"417 × 5를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["2085"],"explanation":["417을 400, 10, 7로 갈라 5를 곱해요: 400 × 5 = 2000, 10 × 5 = 50, 7 × 5 = 35.","일의 자리 7 × 5 = 35에서 3을 십의 자리로 올림, 백의 자리 4 × 5 = 20이에요.","2000 + 50 + 35 = 2085예요."],"asset":{"type":"expr_grid","rows":[["올림","","","3",""],["","","4","1","7"],["×","","","","5"],["",null,null,null,null]]}},{"stem":"359 × 7을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["2513"],"explanation":["359를 300, 50, 9로 갈라 7을 곱해요: 300 × 7 = 2100, 50 × 7 = 350, 9 × 7 = 63.","일의 자리 9 × 7 = 63에서 6을 십의 자리로 올림, 십의 자리 5 × 7 + 6 = 41에서 4를 백의 자리로 올림, 백의 자리 3 × 7 + 4 = 25예요.","2100 + 350 + 63 = 2513이에요."],"asset":{"type":"expr_grid","rows":[["올림","","4","6",""],["","","3","5","9"],["×","","","","7"],["",null,null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#4','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',1,'sa','auto','좌석이 274개인 영화관이 있습니다. 이 영화관에서 영화를 하루에 6번 상영한다면 영화를 관람할 수 있는 사람은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"좌석이 274개인 영화관이 있습니다. 이 영화관에서 영화를 하루에 6번 상영한다면 영화를 관람할 수 있는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["1644"],"explanation":["274명씩 6번 — 곱셈식 274 × 6으로 세워요.","일의 자리 4 × 6 = 24에서 2를 십의 자리로 올림, 십의 자리 7 × 6 + 2 = 44에서 4를 백의 자리로 올림, 백의 자리 2 × 6 + 4 = 16이에요.","274 × 6 = 1644 — 1644명이에요."],"variant_rule":{"alt":[{"stem":"무 씨앗이 한 봉지에 390개씩 들어 있습니다. 5봉지에 들어 있는 무 씨앗은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1950"],"explanation":["390개씩 5번 — 곱셈식 390 × 5로 세워요.","십의 자리 9 × 5 = 45에서 4를 백의 자리로 올림, 백의 자리 3 × 5 + 4 = 19예요.","390 × 5 = 1950 — 1950개예요."]},{"stem":"클립이 한 상자에 129개씩 들어 있습니다. 6상자에 들어 있는 클립은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["774"],"explanation":["129개씩 6번 — 곱셈식 129 × 6으로 세워요.","일의 자리 9 × 6 = 54에서 5를 십의 자리로 올림, 십의 자리 2 × 6 + 5 = 17에서 1을 백의 자리로 올림해요.","129 × 6 = 774 — 774개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#5','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'mc','auto','274 × 7을 세로셈으로 계산할 때 백의 자리 위에 작게 쓴 5는 어떻게 나온 수인가요?',ARRAY['M3-2-u1-X02','M3-2-u1-X11']::text[],false,'{"seq":5,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"274 × 7을 세로셈으로 계산할 때 백의 자리 위에 작게 쓴 5는 어떻게 나온 수인가요?","options":[{"t":"7 × 7 = 49에 올림한 2를 더한 51의 5예요","correct":true},{"t":"7 × 7 = 49의 4예요","mis":"M3-2-u1-X02"},{"t":"2 × 7 = 14의 1과 4를 더한 5예요","mis":"M3-2-u1-X11"}],"explanation":["4 × 7 = 28 — 8을 쓰고 2를 십의 자리로 올려요.","7 × 7 = 49에 2를 더해 51 — 1을 쓰고 5를 백의 자리로 올려요(28 + 490 = 518의 5).","2 × 7 = 14에 5를 더해 19 — 274 × 7 = 1918이에요."],"asset":{"type":"expr_grid","rows":[["올림","","5","2",""],["","","2","7","4"],["×","","","","7"],["","1","9","1","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#6','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?  ㉠ 242 × 6  ㉡ 461 × 3  ㉢ 637 × 2  ㉣ 391 × 4',ARRAY['M3-2-u1-X14','M3-2-u1-X12']::text[],false,'{"seq":6,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?  ㉠ 242 × 6  ㉡ 461 × 3  ㉢ 637 × 2  ㉣ 391 × 4","options":[{"t":"㉣","correct":true},{"t":"㉢","mis":"M3-2-u1-X14"},{"t":"㉡","mis":"M3-2-u1-X12"}],"explanation":["㉠ 242 × 6 = 1452, ㉡ 461 × 3 = 1383이에요.","㉢ 637 × 2 = 1274, ㉣ 391 × 4 = 1564예요.","곱해지는 수가 가장 큰 ㉢이 아니라 ㉣이 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#7','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'mc','auto','390 × 5는 얼마인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X18']::text[],false,'{"seq":7,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"390 × 5는 얼마인가요?","options":[{"t":"1950","correct":true},{"t":"1955","mis":"M3-2-u1-X05"},{"t":"195","mis":"M3-2-u1-X18"}],"explanation":["390을 300, 90, 0으로 갈라 5를 곱해요: 300 × 5 = 1500, 90 × 5 = 450, 0 × 5 = 0.","십의 자리 9 × 5 = 45에서 4를 백의 자리로 올림, 백의 자리 3 × 5 + 4 = 19예요.","1500 + 450 + 0 = 1950이에요 — 일의 자리 0 × 5 = 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#8','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'mc','auto','「교과서 한 번 더」 — 방울토마토가 한 상자에 617개씩 5상자 있어요. 방울토마토는 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02']::text[],true,'{"seq":8,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"「교과서 한 번 더」 — 방울토마토가 한 상자에 617개씩 5상자 있어요. 방울토마토는 모두 몇 개인가요?","options":[{"t":"3085개","correct":true},{"t":"622개","mis":"M3-2-u1-X13"},{"t":"3055개","mis":"M3-2-u1-X02"}],"explanation":["617개씩 5번 — 곱셈식 617 × 5로 세워요.","일의 자리 7 × 5 = 35에서 3을 십의 자리로 올림, 백의 자리 6 × 5 = 30이에요.","617 × 5 = 3085 — 3085개예요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 종이봉투가 한 묶음에 326장씩 묶여 있습니다. 4묶음의 종이봉투는 모두 몇 장인가요?","options":[{"t":"1304장","correct":true},{"t":"330장","mis":"M3-2-u1-X13"},{"t":"1284장","mis":"M3-2-u1-X02"}],"explanation":["326장씩 4번 — 곱셈식 326 × 4로 세워요.","일의 자리 6 × 4 = 24에서 2를 십의 자리로 올림, 십의 자리 2 × 4 + 2 = 10에서 1을 백의 자리로 올림, 백의 자리 3 × 4 + 1 = 13이에요.","326 × 4 = 1304 — 1304장이에요."]},{"stem":"여러 영양소가 풍부한 방울토마토가 한 상자에 426개씩 들어 있어요. 3상자에 들어 있는 방울토마토는 모두 몇 개인가요?","options":[{"t":"1278개","correct":true},{"t":"429개","mis":"M3-2-u1-X13"},{"t":"1268개","mis":"M3-2-u1-X02"}],"explanation":["426개씩 3번 — 곱셈식 426 × 3으로 세워요.","일의 자리 6 × 3 = 18에서 1을 십의 자리로 올림, 백의 자리 4 × 3 = 12예요.","426 × 3 = 1278 — 1278개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#9','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C4',2,'match','auto','반찬 3접시의 열량을 구했어요. 반찬과 3접시의 열량을 이으세요. (1접시 열량 — 잡채 256킬로칼로리, 소불고기 266킬로칼로리, 고등어구이 552킬로칼로리)','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C4","difficulty":2,"kind":"match","stem":"반찬 3접시의 열량을 구했어요. 반찬과 3접시의 열량을 이으세요. (1접시 열량 — 잡채 256킬로칼로리, 소불고기 266킬로칼로리, 고등어구이 552킬로칼로리)","pairs":[{"l":"잡채 3접시","r":"768킬로칼로리"},{"l":"소불고기 3접시","r":"798킬로칼로리"},{"l":"고등어구이 3접시","r":"1656킬로칼로리"}],"mis":"M3-2-u1-X02","explanation":["잡채 256 × 3 = 768, 소불고기 266 × 3 = 798이에요.","고등어구이 552 × 3 = 1656이에요.","반찬마다 1접시의 열량에 3을 곱해요."],"variant_rule":{"alt":[{"stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"253 × 7","r":"1771"},{"l":"861 × 3","r":"2583"},{"l":"421 × 5","r":"2105"}],"explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","253 × 7 = 1771, 861 × 3 = 2583, 421 × 5 = 2105.","곱이 비슷해 보여도 끝자리까지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_basic#10','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_basic','lesson_basic','M3-2-u1-C3',3,'mc','auto','바둑돌이 한 통에 189개씩 2통 있어요. 어림하면 약 400개, 계산하면 378개예요. 어림한 값과 계산 결과를 비교한 말로 알맞은 것은 어느 것인가요?',ARRAY['M3-2-u1-X20']::text[],false,'{"seq":10,"concept":"M3-2-u1-C3","difficulty":3,"kind":"mc","stem":"바둑돌이 한 통에 189개씩 2통 있어요. 어림하면 약 400개, 계산하면 378개예요. 어림한 값과 계산 결과를 비교한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"알맞아요 — 400과 378이 비슷해요","correct":true},{"t":"알맞지 않아요 — 400과 378이 똑같지 않아요","mis":"M3-2-u1-X20"},{"t":"알맞지 않아요 — 계산 결과가 어림한 값보다 작으면 틀려요","mis":"M3-2-u1-X20"}],"explanation":["189를 200으로 생각하면 약 400이에요.","189 × 2 = 378이에요.","어림한 값과 계산 결과가 비슷하면 계산 결과가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#1','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',2,'ox','auto','426 × 3을 어림하면 약 1200이고, 계산 결과 1278은 어림한 값과 비슷해요.',ARRAY['M3-2-u1-X20']::text[],true,'{"seq":1,"concept":"M3-2-u1-C4","difficulty":2,"kind":"ox","stem":"426 × 3을 어림하면 약 1200이고, 계산 결과 1278은 어림한 값과 비슷해요.","answer":"O","reason_options":[{"t":"426을 400으로 보면 400 × 3 = 1200이고 1278과 비슷하니까","correct":true},{"t":"어림한 값과 계산 결과는 똑같아야 하니까","mis":"M3-2-u1-X20"}],"mis":"M3-2-u1-X20","explanation":["426을 400으로 생각하면 약 1200이에요.","426 × 3 = 1278이에요.","1200과 1278이 비슷 — 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"617 × 5 = 3085예요.","answer":"O","reason_options":[{"t":"7 × 5 = 35의 3을 올리고, 1 × 5 + 3 = 8, 6 × 5 = 30이라 3085니까","correct":true},{"t":"올림한 수는 다음 자리에 더하지 않으니까 3055니까","mis":"M3-2-u1-X02"}],"explanation":["7 × 5 = 35 — 5를 쓰고 3을 올려요.","1 × 5 = 5에 3을 더해 8, 6 × 5 = 30이에요.","그래서 617 × 5 = 3085 — 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#2','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',2,'mc','auto','「재미있는 수학」 곱셈판 놀이 — 주사위를 4번 던져 나온 수로 계산 결과가 가장 크게 되도록 (세 자리 수) × (한 자리 수)를 만들어요. 나온 수 가운데 가장 큰 수는 어디에 써야 하나요?',ARRAY['M3-2-u1-X14']::text[],false,'{"seq":2,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"「재미있는 수학」 곱셈판 놀이 — 주사위를 4번 던져 나온 수로 계산 결과가 가장 크게 되도록 (세 자리 수) × (한 자리 수)를 만들어요. 나온 수 가운데 가장 큰 수는 어디에 써야 하나요?","options":[{"t":"곱하는 수(한 자리 수) 자리","correct":true},{"t":"곱해지는 수의 백의 자리","mis":"M3-2-u1-X14"},{"t":"곱해지는 수의 일의 자리","mis":"M3-2-u1-X14"}],"explanation":["곱하는 수는 곱해지는 수의 백·십·일의 자리에 모두 곱해져요.","그래서 가장 큰 수를 곱하는 수에 쓰고, 나머지로 가장 큰 세 자리 수를 만들어요.","계산기로 확인하고, 계산 결과가 더 큰 사람이 1점을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#3','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'sa','auto','629 × 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C4","difficulty":3,"kind":"sa","stem":"629 × 8은 얼마인가요? 숫자로 쓰세요.","answer":["5032"],"explanation":["629를 600, 20, 9로 갈라 8을 곱해요: 600 × 8 = 4800, 20 × 8 = 160, 9 × 8 = 72.","일의 자리 9 × 8 = 72에서 7을 십의 자리로 올림, 십의 자리 2 × 8 + 7 = 23에서 2를 백의 자리로 올림, 백의 자리 6 × 8 + 2 = 50이에요.","4800 + 160 + 72 = 5032예요 — 십의 자리 숫자가 0이에요."],"asset":{"type":"expr_grid","rows":[["올림","","2","7",""],["","","6","2","9"],["×","","","","8"],["","5","0","3","2"]]},"variant_rule":{"alt":[{"stem":"「확인 문제」 — 632 × 9는 얼마인가요? 숫자로 쓰세요.","answer":["5688"],"explanation":["632를 600, 30, 2로 갈라 9를 곱해요: 600 × 9 = 5400, 30 × 9 = 270, 2 × 9 = 18.","일의 자리 2 × 9 = 18에서 1을 십의 자리로 올림, 십의 자리 3 × 9 + 1 = 28에서 2를 백의 자리로 올림, 백의 자리 6 × 9 + 2 = 56이에요.","5400 + 270 + 18 = 5688이에요."],"asset":{"type":"expr_grid","rows":[["올림","","2","1",""],["","","6","3","2"],["×","","","","9"],["","5","6","8","8"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#4','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'error','auto','426 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X04','M3-2-u1-X15']::text[],true,'{"seq":4,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"426 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「426 × 3 = 12618」","correct":true,"mis_target":"M3-2-u1-X04"},{"t":"채원 — 「1200 + 60 + 18 = 1278」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「400 × 3 = 1200보다 조금 커서 1278」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 6 × 3 = 18에서 1을 십의 자리로 올림, 백의 자리 4 × 3 = 12예요.","426 × 3 = 1278이에요.","건우는 12618로 잘못 구했어요 — 10이 넘으면 윗자리로 올려요."],"variant_rule":{"alt":[{"stem":"274 × 7을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「274 × 7 = 144928」","correct":true,"mis_target":"M3-2-u1-X04"},{"t":"서준 — 「1400 + 490 + 28 = 1918」","mis":"M3-2-u1-X15"},{"t":"건우 — 「일, 십, 백의 자리를 차례로 곱해 1918」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 4 × 7 = 28에서 2를 십의 자리로 올림, 십의 자리 7 × 7 + 2 = 51에서 5를 백의 자리로 올림, 백의 자리 2 × 7 + 5 = 19예요.","274 × 7 = 1918이에요.","지유는 144928로 잘못 구했어요 — 10이 넘으면 윗자리로 올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#5','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'mc','auto','고른 반찬 3접시의 열량을 구해요. 3접시의 열량이 가장 많은 반찬은 무엇인가요? (1접시 — 잡채 256, 소불고기 266, 고등어구이 552, 어묵볶음 393킬로칼로리)',ARRAY['M3-2-u1-X12']::text[],true,'{"seq":5,"concept":"M3-2-u1-C4","difficulty":3,"kind":"mc","stem":"고른 반찬 3접시의 열량을 구해요. 3접시의 열량이 가장 많은 반찬은 무엇인가요? (1접시 — 잡채 256, 소불고기 266, 고등어구이 552, 어묵볶음 393킬로칼로리)","options":[{"t":"고등어구이","correct":true},{"t":"어묵볶음","mis":"M3-2-u1-X12"},{"t":"소불고기","mis":"M3-2-u1-X12"}],"explanation":["잡채 768, 소불고기 798킬로칼로리예요.","고등어구이 552 × 3 = 1656, 어묵볶음 393 × 3 = 1179킬로칼로리예요.","1접시의 열량이 가장 큰 고등어구이가 3접시도 가장 많아요."],"variant_rule":{"alt":[{"stem":"3접시의 열량이 가장 적은 반찬은 무엇인가요? (1접시 — 잡채 256, 소불고기 266, 고등어구이 552, 어묵볶음 393킬로칼로리)","options":[{"t":"잡채","correct":true},{"t":"소불고기","mis":"M3-2-u1-X12"},{"t":"어묵볶음","mis":"M3-2-u1-X12"}],"explanation":["잡채 256 × 3 = 768이에요.","소불고기 266 × 3 = 798, 어묵볶음 393 × 3 = 1179예요.","768이 가장 적어요 — 잡채예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#6','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C3',3,'mc','auto','계산 결과가 1000보다 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":6,"concept":"M3-2-u1-C3","difficulty":3,"kind":"mc","stem":"계산 결과가 1000보다 큰 것은 어느 것인가요?","options":[{"t":"274 × 6","correct":true},{"t":"129 × 6","mis":"M3-2-u1-X12"},{"t":"136 × 4","mis":"M3-2-u1-X12"}],"explanation":["274 × 6은 274를 300으로 보면 약 1800 — 계산하면 1644예요.","129 × 6 = 774, 136 × 4 = 544예요.","1000보다 큰 것은 274 × 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#7','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',3,'sa','auto','「익힘」 — 534 × 3을 수 카드로 계산했어요. 1500 + 90 + 12는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u1-C4","difficulty":3,"kind":"sa","stem":"「익힘」 — 534 × 3을 수 카드로 계산했어요. 1500 + 90 + 12는 얼마인가요? 숫자로 쓰세요.","answer":["1602"],"explanation":["500 × 3 = 1500, 30 × 3 = 90, 4 × 3 = 12예요.","1500 + 90 + 12 = 1602예요.","534 × 3 = 1602 — 백·십·일 카드 수를 각각 세어 구해요."],"asset":{"type":"expr_grid","rows":[["500 × 3","=","1500"],["30 × 3","=","90"],["4 × 3","=","12"],["1500 + 90 + 12","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#8','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C3',4,'essay','teacher','방울토마토 426개씩 3상자 — 426 × 3의 계산 결과를 어림하고, 어림한 값과 계산 결과를 비교해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C3","difficulty":4,"kind":"essay","stem":"방울토마토 426개씩 3상자 — 426 × 3의 계산 결과를 어림하고, 어림한 값과 계산 결과를 비교해 보세요.","answer_guide":{"answer":"예: 426을 400과 26으로 나누어 어림한다. 400 × 3 = 1200이고 26은 30에 가까우므로 약 90이다. 그래서 약 1290이다. 계산 결과는 1278로 어림한 값과 거의 비슷하다.","scoring_points":["400 × 3 = 1200(또는 약 1290)으로 어림했는가","426 × 3 = 1278을 구했는가","어림한 값과 비슷하다고 비교했는가"]},"explanation":["400 × 3 = 1200, 26 × 3은 약 90 → 약 1290.","426 × 3 = 1278.","어림한 값과 거의 비슷 — 계산 결과가 적절해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#9','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',4,'sa','auto','고등어구이 3접시의 열량은 잡채 3접시의 열량보다 몇 킬로칼로리 더 많은가요? (1접시 — 고등어구이 552, 잡채 256킬로칼로리) 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"고등어구이 3접시의 열량은 잡채 3접시의 열량보다 몇 킬로칼로리 더 많은가요? (1접시 — 고등어구이 552, 잡채 256킬로칼로리) 숫자로 쓰세요.","answer":["888"],"explanation":["고등어구이 552 × 3 = 1656(킬로칼로리)이에요.","잡채 256 × 3 = 768(킬로칼로리)이에요.","1656 − 768 = 888 — 888킬로칼로리 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L04_challenge#10','math',3,2,'u1','L04','tb_g3_2_math_u1_L04_challenge','lesson_challenge','M3-2-u1-C4',4,'essay','teacher','274 × 7을 세로셈으로 계산하는 방법을 쓰고, 올림한 수를 어떻게 처리했는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u1-C4","difficulty":4,"kind":"essay","stem":"274 × 7을 세로셈으로 계산하는 방법을 쓰고, 올림한 수를 어떻게 처리했는지 설명해 보세요.","answer_guide":{"answer":"예: 4 × 7 = 28에서 8을 쓰고 2를 올린다. 7 × 7 = 49에 2를 더해 51, 1을 쓰고 5를 올린다. 2 × 7 = 14에 5를 더해 19를 쓴다. 274 × 7 = 1918이다.","scoring_points":["일, 십, 백의 자리 순서로 곱했는가","올림한 2, 5를 곱한 다음 더했는가","1918을 구했는가"]},"explanation":["4 × 7 = 28 → 2 올림.","7 × 7 + 2 = 51 → 5 올림.","2 × 7 + 5 = 19 → 1918."],"asset":{"type":"expr_grid","rows":[["올림","","5","2",""],["","","2","7","4"],["×","","","","7"],["","1","9","1","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#1','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'mc','auto','미니 양배추가 한 상자에 30개씩 들어 있어요. 「오늘은 30상자를 수확했네!」 미니 양배추의 수를 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X06']::text[],true,'{"seq":1,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"미니 양배추가 한 상자에 30개씩 들어 있어요. 「오늘은 30상자를 수확했네!」 미니 양배추의 수를 구하는 식은 어느 것인가요?","options":[{"t":"30 × 30","correct":true},{"t":"30 + 30","mis":"M3-2-u1-X13"},{"t":"30 × 3","mis":"M3-2-u1-X06"}],"explanation":["한 상자에 30개씩, 30상자예요.","30개씩 30묶음은 30 × 30이에요.","30 × 3은 3상자일 때의 식이에요."],"variant_rule":{"alt":[{"stem":"파프리카가 한 봉지에 14개씩 들어 있어요. 20봉지에 들어 있는 파프리카의 수를 구하는 식은 어느 것인가요?","options":[{"t":"14 × 20","correct":true},{"t":"14 + 20","mis":"M3-2-u1-X13"},{"t":"14 × 2","mis":"M3-2-u1-X06"}],"explanation":["한 봉지에 14개씩, 20봉지예요.","14개씩 20묶음은 14 × 20이에요.","14 × 2는 2봉지일 때의 식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#2','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'sa','auto','30 × 3 = 90이에요. 30 × 30은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"30 × 3 = 90이에요. 30 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["30 × 30은 30 × 3에서 곱하는 수가 10배가 된 것이에요.","그래서 곱도 10배가 되어야 해요.","90의 10배 = 900 — 미니 양배추는 900개예요."],"asset":{"type":"expr_grid","rows":[["30 × 3","=","90"],["30 × 30","=",null]]},"variant_rule":{"alt":[{"stem":"「교과서 한 번 더」 — 13 × 3 = 39예요. 13 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["390"],"explanation":["13 × 30은 13 × 3에서 곱하는 수가 10배가 된 것이에요.","그래서 곱도 10배가 되어야 해요.","39의 10배 = 390 — 미니 양배추는 390개예요."],"asset":{"type":"expr_grid","rows":[["13 × 3","=","39"],["13 × 30","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#3','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'sa','auto','40 × 20은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"40 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["800"],"explanation":["40 × 2 = 80이에요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","40 × 20은 80의 10배인 800이에요."],"variant_rule":{"alt":[{"stem":"32 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["960"],"explanation":["곱하는 수 30의 0을 잠시 떼고 32 × 3 = 96이에요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","32 × 30은 96의 10배인 960이에요."]},{"stem":"80 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["2400"],"explanation":["80 × 3 = 240이에요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","80 × 30은 240의 10배인 2400이에요."]},{"stem":"23 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["920"],"explanation":["곱하는 수 40의 0을 잠시 떼고 23 × 4 = 92예요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","23 × 40은 92의 10배인 920이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#4','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',1,'mc','auto','14 × 20을 「방법 1」로 계산해요. 14 × 2 = 28이면 14 × 20은 얼마인가요?',ARRAY['M3-2-u1-X06']::text[],true,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"14 × 20을 「방법 1」로 계산해요. 14 × 2 = 28이면 14 × 20은 얼마인가요?","options":[{"t":"280","correct":true},{"t":"28","mis":"M3-2-u1-X06"},{"t":"2800","mis":"M3-2-u1-X06"}],"explanation":["14개씩 2묶음은 14 × 2 = 28이에요.","2묶음이 10번 있으니 28의 10배예요.","14 × 20 = 14 × 2 × 10 = 280이에요."],"variant_rule":{"alt":[{"stem":"26 × 20을 「방법 1」로 계산해요. 26 × 2 = 52이면 26 × 20은 얼마인가요?","options":[{"t":"520","correct":true},{"t":"52","mis":"M3-2-u1-X06"},{"t":"5200","mis":"M3-2-u1-X06"}],"explanation":["26 × 2 = 52예요.","20은 2의 10배라 곱도 10배예요.","26 × 20 = 26 × 2 × 10 = 520이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#5','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'blank','auto','「방법 2」 — 14 × 20 = 14 × 10 × (     ) = 140 × (     ) = 280',ARRAY['M3-2-u1-X06']::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":2,"kind":"blank","stem":"「방법 2」 — 14 × 20 = 14 × 10 × (     ) = 140 × (     ) = 280","options":[{"t":"2","correct":true},{"t":"20","mis":"M3-2-u1-X06"},{"t":"10","mis":"M3-2-u1-X06"}],"explanation":["14개씩 10묶음은 14 × 10 = 140이에요.","10묶음이 2번 있으니 140의 2배예요.","14 × 20 = 14 × 10 × 2 = 140 × 2 = 280이에요."],"variant_rule":{"alt":[{"stem":"「방법 2」 — 13 × 30 = 13 × 10 × (     ) = 130 × (     ) = 390","options":[{"t":"3","correct":true},{"t":"30","mis":"M3-2-u1-X06"},{"t":"10","mis":"M3-2-u1-X06"}],"explanation":["13 × 10 = 130이에요.","10묶음이 3번 있으니 130의 3배예요.","13 × 30 = 130 × 3 = 390이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#6','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'sa','auto','73 × 40은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"73 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["2920"],"explanation":["곱하는 수 40의 0을 잠시 떼고 73 × 4 = 292예요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","73 × 40은 292의 10배인 2920이에요."],"variant_rule":{"alt":[{"stem":"47 × 60은 얼마인가요? 숫자로 쓰세요.","answer":["2820"],"explanation":["곱하는 수 60의 0을 잠시 떼고 47 × 6 = 282예요.","곱하는 수가 6에서 60으로 10배가 되면 곱도 10배예요.","47 × 60은 282의 10배인 2820이에요."]},{"stem":"29 × 90은 얼마인가요? 숫자로 쓰세요.","answer":["2610"],"explanation":["곱하는 수 90의 0을 잠시 떼고 29 × 9 = 261이에요.","곱하는 수가 9에서 90으로 10배가 되면 곱도 10배예요.","29 × 90은 261의 10배인 2610이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#7','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'mc','auto','상추 모종을 한 줄에 32개씩 심으려고 합니다. 40줄을 심으려면 상추 모종은 모두 몇 개 필요한가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X06']::text[],true,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":2,"kind":"mc","stem":"상추 모종을 한 줄에 32개씩 심으려고 합니다. 40줄을 심으려면 상추 모종은 모두 몇 개 필요한가요?","options":[{"t":"1280개","correct":true},{"t":"72개","mis":"M3-2-u1-X13"},{"t":"128개","mis":"M3-2-u1-X06"}],"explanation":["32개씩 40번 — 곱셈식 32 × 40으로 세워요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","32 × 40 = 1280 — 1280개예요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 공책은 한 묶음에 22권입니다. 공책 80묶음은 모두 몇 권인가요?","options":[{"t":"1760권","correct":true},{"t":"102권","mis":"M3-2-u1-X13"},{"t":"176권","mis":"M3-2-u1-X06"}],"explanation":["22권씩 80번 — 곱셈식 22 × 80으로 세워요.","곱하는 수가 8에서 80으로 10배가 되면 곱도 10배예요.","22 × 80 = 1760 — 1760권이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#8','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u1-C5","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"50 × 40","r":"2000"},{"l":"38 × 20","r":"760"},{"l":"60 × 30","r":"1800"}],"mis":"M3-2-u1-X06","explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","50 × 40 = 2000, 38 × 20 = 760, 60 × 30 = 1800.","곱이 비슷해 보여도 끝자리까지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"80 × 30","r":"2400"},{"l":"23 × 40","r":"920"},{"l":"47 × 60","r":"2820"}],"explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","80 × 30 = 2400, 23 × 40 = 920, 47 × 60 = 2820.","곱이 비슷해 보여도 끝자리까지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#9','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',2,'ox','auto','40 × 20은 4 × 2 = 8에 0을 두 개 붙인 800이에요.',ARRAY['M3-2-u1-X06']::text[],true,'{"seq":9,"concept":"M3-2-u1-C5","difficulty":2,"kind":"ox","stem":"40 × 20은 4 × 2 = 8에 0을 두 개 붙인 800이에요.","answer":"O","reason_options":[{"t":"40 × 2 = 80의 10배라 800이니까","correct":true},{"t":"0을 하나만 붙여 80이니까","mis":"M3-2-u1-X06"}],"mis":"M3-2-u1-X06","explanation":["40 × 2 = 80이에요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","80의 10배 = 800 — 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"30 × 30 = 90이에요.","answer":"X","reason_options":[{"t":"30 × 3 = 90의 10배라 900이니까","correct":true},{"t":"3 × 3 = 9에 0을 하나 붙이면 되니까","mis":"M3-2-u1-X06"}],"explanation":["30 × 3 = 90이에요.","30 × 30은 곱하는 수가 10배라 곱도 10배예요.","그래서 30 × 30 = 900 — 90이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_basic#10','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_basic','lesson_basic','M3-2-u1-C5',3,'error','auto','14 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C5","difficulty":3,"kind":"error","stem":"14 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「14 × 20 = 28」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"채원 — 「14 × 2 = 28의 10배라 280」","mis":"M3-2-u1-X15"},{"t":"지유 — 「14 × 10 = 140의 2배라 280」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","14 × 20 = 280이에요.","도윤은 28로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배를 해요."],"variant_rule":{"alt":[{"stem":"26 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「26 × 20 = 52」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"건우 — 「26 × 2 = 52의 10배라 520」","mis":"M3-2-u1-X15"},{"t":"채원 — 「26 × 10 = 260의 2배라 520」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","26 × 20 = 520이에요.","서준은 52로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배를 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#1','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',2,'mc','auto','계산 결과가 다른 하나는 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],false,'{"seq":1,"concept":"M3-2-u1-C5","difficulty":2,"kind":"mc","stem":"계산 결과가 다른 하나는 어느 것인가요?","options":[{"t":"24 × 50","correct":true},{"t":"52 × 20","mis":"M3-2-u1-X11"},{"t":"26 × 40","mis":"M3-2-u1-X11"}],"explanation":["52 × 20 = 1040, 26 × 40 = 1040이에요.","24 × 50 = 1200이에요.","그래서 계산 결과가 다른 하나는 24 × 50이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#2','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',2,'mc','auto','「곱하기 10 놀이」 — 한 친구가 「14」라고 말하고, 다음 친구가 「곱하기 10은」이라고 말했어요. 지목된 친구가 말할 계산 결과는 무엇인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X13']::text[],false,'{"seq":2,"concept":"M3-2-u1-C5","difficulty":2,"kind":"mc","stem":"「곱하기 10 놀이」 — 한 친구가 「14」라고 말하고, 다음 친구가 「곱하기 10은」이라고 말했어요. 지목된 친구가 말할 계산 결과는 무엇인가요?","options":[{"t":"140","correct":true},{"t":"1400","mis":"M3-2-u1-X06"},{"t":"24","mis":"M3-2-u1-X13"}],"explanation":["14 × 10은 14개씩 10묶음이에요.","어떤 수에 10을 곱하면 그 수의 10배가 돼요.","14 × 10 = 140 — 이것의 2배가 14 × 20 = 280이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#3','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'sa','auto','어떤 수에 30을 곱해야 할 것을 잘못하여 더했더니 100이 되었어요. 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u1-C5","difficulty":3,"kind":"sa","stem":"어떤 수에 30을 곱해야 할 것을 잘못하여 더했더니 100이 되었어요. 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.","answer":["2100"],"explanation":["어떤 수 + 30 = 100이니 어떤 수는 100 − 30 = 70이에요.","바르게 계산하면 70 × 30이에요.","70 × 3 = 210의 10배 — 2100이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#4','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'mc','auto','한 상자에 12개씩 들어 있는 도넛이 40상자 있어요. 500명의 사람에게 도넛을 한 개씩 나누어 준다면 받지 못하는 사람이 있나요?',ARRAY['M3-2-u1-X06','M3-2-u1-X13']::text[],false,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":3,"kind":"mc","stem":"한 상자에 12개씩 들어 있는 도넛이 40상자 있어요. 500명의 사람에게 도넛을 한 개씩 나누어 준다면 받지 못하는 사람이 있나요?","options":[{"t":"있어요 — 도넛은 480개라 500개보다 적어요","correct":true},{"t":"없어요 — 12 × 40 = 4800개라 충분해요","mis":"M3-2-u1-X06"},{"t":"없어요 — 12 + 40 = 52상자라 충분해요","mis":"M3-2-u1-X13"}],"explanation":["도넛은 12 × 40개예요.","12 × 4 = 48의 10배 — 480개예요.","480 < 500이라 받지 못하는 사람이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#5','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'sa','auto','60 × □ = 1200에서 □ 안에 알맞은 수는 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C5","difficulty":3,"kind":"sa","stem":"60 × □ = 1200에서 □ 안에 알맞은 수는 얼마인가요?","answer":["20"],"explanation":["60 × 2 = 120이에요.","1200은 120의 10배라 곱하는 수도 2의 10배예요.","60 × 20 = 1200 — □는 20이에요."],"variant_rule":{"alt":[{"stem":"13 × □ = 390에서 □ 안에 알맞은 수는 얼마인가요?","answer":["30"],"explanation":["13 × 3 = 39예요.","390은 39의 10배라 곱하는 수도 3의 10배예요.","13 × 30 = 390 — □는 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#6','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'mc','auto','14 × 20을 계산하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M3-2-u1-X15']::text[],false,'{"seq":6,"concept":"M3-2-u1-C5","difficulty":3,"kind":"mc","stem":"14 × 20을 계산하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"14 × 2 = 28에 20을 더해요","correct":true},{"t":"14 × 2 = 28의 10배를 해요","mis":"M3-2-u1-X15"},{"t":"14 × 10 = 140의 2배를 해요","mis":"M3-2-u1-X15"}],"explanation":["「방법 1」 14 × 2 = 28의 10배 — 280이에요.","「방법 2」 14 × 10 = 140의 2배 — 280이에요.","28에 20을 더하면 48 — 곱셈이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#7','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',3,'mc','auto','미니 양배추 30개씩 든 상자 30개를 3개씩 한 묶음으로 보았어요. 한 묶음의 미니 양배추는 30 × 3 = 90개예요. 이런 묶음은 몇 개인가요?',ARRAY['M3-2-u1-X06']::text[],false,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":3,"kind":"mc","stem":"미니 양배추 30개씩 든 상자 30개를 3개씩 한 묶음으로 보았어요. 한 묶음의 미니 양배추는 30 × 3 = 90개예요. 이런 묶음은 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"3개","mis":"M3-2-u1-X06"},{"t":"30개","mis":"M3-2-u1-X06"}],"explanation":["30상자를 3상자씩 묶으면 10묶음이에요.","한 묶음은 90개, 10묶음은 90의 10배예요.","그래서 30 × 30 = 900 — 30 × 3의 10배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#8','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',4,'essay','teacher','파프리카가 한 봉지에 14개씩 20봉지 있어요. 14 × 20을 두 가지 방법으로 계산하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C5","difficulty":4,"kind":"essay","stem":"파프리카가 한 봉지에 14개씩 20봉지 있어요. 14 × 20을 두 가지 방법으로 계산하고 설명해 보세요.","answer_guide":{"answer":"예: 방법 1 — 14개씩 2묶음은 14 × 2 = 28이고, 2묶음이 10번 있으므로 28의 10배인 280이다. 방법 2 — 14개씩 10묶음은 14 × 10 = 140이고, 10묶음이 2번 있으므로 140의 2배인 280이다.","scoring_points":["14 × 2 = 28의 10배로 구했는가","14 × 10 = 140의 2배로 구했는가","280으로 두 방법이 같음을 썼는가"]},"explanation":["14 × 2 × 10 = 28 × 10 = 280.","14 × 10 × 2 = 140 × 2 = 280.","두 방법 모두 280이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#9','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',4,'mc','auto','계산 결과가 1200인 곱셈을 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],false,'{"seq":9,"concept":"M3-2-u1-C5","difficulty":4,"kind":"mc","stem":"계산 결과가 1200인 곱셈을 모두 고른 것은 어느 것인가요?","options":[{"t":"60 × 20, 24 × 50","correct":true},{"t":"60 × 20, 52 × 20","mis":"M3-2-u1-X11"},{"t":"24 × 50, 26 × 40","mis":"M3-2-u1-X11"}],"explanation":["60 × 20 = 1200, 24 × 50 = 1200이에요.","52 × 20 = 1040, 26 × 40 = 1040이에요.","1200인 것은 60 × 20과 24 × 50이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L05_challenge#10','math',3,2,'u1','L05','tb_g3_2_math_u1_L05_challenge','lesson_challenge','M3-2-u1-C5',4,'essay','teacher','도넛이 한 상자에 12개씩 40상자 있어요. 500명에게 한 개씩 나누어 줄 때 받지 못하는 사람이 있는지 판단하고, 그 까닭을 계산과 함께 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u1-C5","difficulty":4,"kind":"essay","stem":"도넛이 한 상자에 12개씩 40상자 있어요. 500명에게 한 개씩 나누어 줄 때 받지 못하는 사람이 있는지 판단하고, 그 까닭을 계산과 함께 써 보세요.","answer_guide":{"answer":"예: 받지 못하는 사람이 있다. 도넛은 모두 12 × 40 = 480(개)이므로 500명에게 나누어 주기에는 도넛의 개수가 부족하기 때문이다.","scoring_points":["받지 못하는 사람이 있다고 판단했는가","12 × 40 = 480을 구했는가","480 < 500을 까닭으로 썼는가"]},"explanation":["12 × 4 = 48 → 10배 480.","도넛 480개, 사람 500명.","480 < 500 — 받지 못하는 사람이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#1','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',1,'mc','auto','농산물을 직접 거래하면 신선한 상태로 빠르게 받을 수 있어요. 당근이 한 봉지에 7개씩 들어 있다면 16봉지에 들어 있는 당근의 수를 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X08']::text[],true,'{"seq":1,"concept":"M3-2-u1-C6","difficulty":1,"kind":"mc","stem":"농산물을 직접 거래하면 신선한 상태로 빠르게 받을 수 있어요. 당근이 한 봉지에 7개씩 들어 있다면 16봉지에 들어 있는 당근의 수를 구하는 식은 어느 것인가요?","options":[{"t":"7 × 16","correct":true},{"t":"7 + 16","mis":"M3-2-u1-X13"},{"t":"7 × 6","mis":"M3-2-u1-X08"}],"explanation":["한 봉지에 7개씩, 16봉지예요.","7개씩 16묶음은 7 × 16이에요.","7 × 6은 6봉지만 센 식이에요."],"variant_rule":{"alt":[{"stem":"사과가 한 봉지에 5개씩 들어 있습니다. 23봉지에 들어 있는 사과의 수를 구하는 식은 어느 것인가요?","options":[{"t":"5 × 23","correct":true},{"t":"5 + 23","mis":"M3-2-u1-X13"},{"t":"5 × 3","mis":"M3-2-u1-X08"}],"explanation":["한 봉지에 5개씩, 23봉지예요.","5개씩 23묶음은 5 × 23이에요.","5 × 3은 3봉지만 센 식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#2','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','당근 7개씩 16봉지 — 16을 20으로 생각하여 어림하면 당근은 약 몇 개인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],false,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"당근 7개씩 16봉지 — 16을 20으로 생각하여 어림하면 당근은 약 몇 개인가요?","options":[{"t":"약 140개","correct":true},{"t":"약 70개","mis":"M3-2-u1-X12"},{"t":"약 1400개","mis":"M3-2-u1-X06"}],"explanation":["16은 20에 가까워요.","7 × 20 = 140이에요.","그래서 약 140개 — 계산 결과 112와 견주어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#3','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',1,'sa','auto','7 × 16을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"7 × 16을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["70"],"explanation":["곱하는 수 16을 6과 10으로 갈라요.","□는 7 × 10 = 70이에요.","42 + 70 = 112 — 7 × 16의 곱이에요."],"asset":{"type":"expr_grid","rows":[["7 × 6","=","42"],["7 × 10","=",null],["42 + □","=","112"]]},"variant_rule":{"alt":[{"stem":"8 × 14를 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["80"],"explanation":["곱하는 수 14를 4와 10으로 갈라요.","□는 8 × 10 = 80이에요.","32 + 80 = 112 — 8 × 14의 곱이에요."],"asset":{"type":"expr_grid","rows":[["8 × 4","=","32"],["8 × 10","=",null],["32 + □","=","112"]]}},{"stem":"이번에는 다른 보기예요. 7 × 16을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["42"],"explanation":["곱하는 수 16을 6과 10으로 갈라요.","□는 7 × 6 = 42예요.","42 + 70 = 112 — 7 × 16의 곱이에요."],"asset":{"type":"expr_grid","rows":[["7 × 6","=",null],["7 × 10","=","70"],["□ + 70","=","112"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#4','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',1,'sa','auto','3 × 48은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"3 × 48은 얼마인가요? 숫자로 쓰세요.","answer":["144"],"explanation":["곱하는 수 48을 8과 40으로 갈라요.","3 × 8 = 24, 3 × 40 = 120이에요 — 둘째 줄은 한 자리 밀어 써요.","24 + 120 = 144예요."],"variant_rule":{"alt":[{"stem":"8 × 42는 얼마인가요? 숫자로 쓰세요.","answer":["336"],"explanation":["곱하는 수 42를 2와 40으로 갈라요.","8 × 2 = 16, 8 × 40 = 320이에요 — 둘째 줄은 한 자리 밀어 써요.","16 + 320 = 336이에요."]},{"stem":"5 × 64는 얼마인가요? 숫자로 쓰세요.","answer":["320"],"explanation":["곱하는 수 64를 4와 60으로 갈라요.","5 × 4 = 20, 5 × 60 = 300이에요 — 둘째 줄은 한 자리 밀어 써요.","20 + 300 = 320이에요."]},{"stem":"4 × 39는 얼마인가요? 숫자로 쓰세요.","answer":["156"],"explanation":["곱하는 수 39를 9와 30으로 갈라요.","4 × 9 = 36, 4 × 30 = 120이에요 — 둘째 줄은 한 자리 밀어 써요.","36 + 120 = 156이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#5','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'sa','auto','7 × 16을 세로셈으로 계산했어요. 곱은 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"7 × 16을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["112"],"explanation":["곱하는 수 16을 6과 10으로 갈라요.","7 × 6 = 42, 7 × 10 = 70이에요 — 둘째 줄은 한 자리 밀어 써요.","42 + 70 = 112예요."],"asset":{"type":"expr_grid","rows":[["","","","","7"],["×","","","1","6"],["","","","4","2"],["","","","7",""],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"6 × 51을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["306"],"explanation":["곱하는 수 51을 1과 50으로 갈라요.","6 × 1 = 6, 6 × 50 = 300이에요 — 둘째 줄은 한 자리 밀어 써요.","6 + 300 = 306이에요."],"asset":{"type":"expr_grid","rows":[["","","","","6"],["×","","","5","1"],["","","","","6"],["","","3","0",""],["","",null,null,null]]}},{"stem":"5 × 84를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["420"],"explanation":["곱하는 수 84를 4와 80으로 갈라요.","5 × 4 = 20, 5 × 80 = 400이에요 — 둘째 줄은 한 자리 밀어 써요.","20 + 400 = 420이에요."],"asset":{"type":"expr_grid","rows":[["","","","","5"],["×","","","8","4"],["","","","2","0"],["","","4","0",""],["","",null,null,null]]}},{"stem":"9 × 15를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["135"],"explanation":["곱하는 수 15를 5와 10으로 갈라요.","9 × 5 = 45, 9 × 10 = 90이에요 — 둘째 줄은 한 자리 밀어 써요.","45 + 90 = 135예요."],"asset":{"type":"expr_grid","rows":[["","","","","9"],["×","","","1","5"],["","","","4","5"],["","","","9",""],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#6','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'ox','auto','16 × 7과 7 × 16의 계산 결과는 같아요.',ARRAY['M3-2-u1-X16']::text[],false,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":2,"kind":"ox","stem":"16 × 7과 7 × 16의 계산 결과는 같아요.","answer":"O","reason_options":[{"t":"16 × 7 = 112, 7 × 16 = 112로 곱이 같으니까","correct":true},{"t":"곱하는 순서가 바뀌면 곱도 달라지니까","mis":"M3-2-u1-X16"}],"mis":"M3-2-u1-X16","explanation":["16 × 7 = 112예요.","7 × 16 = 42 + 70 = 112예요.","곱셈은 곱해지는 수와 곱하는 수의 순서를 바꾸어도 계산 결과가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#7','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'mc','auto','사과가 한 봉지에 5개씩 들어 있습니다. 23봉지에 들어 있는 사과는 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],true,'{"seq":7,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"사과가 한 봉지에 5개씩 들어 있습니다. 23봉지에 들어 있는 사과는 모두 몇 개인가요?","options":[{"t":"115개","correct":true},{"t":"28개","mis":"M3-2-u1-X13"},{"t":"25개","mis":"M3-2-u1-X07"}],"explanation":["5개씩 23번 — 곱셈식 5 × 23으로 세워요.","5 × 3 = 15, 5 × 20 = 100이에요 — 둘째 줄은 한 자리 밀어 써요.","5 × 23 = 115 — 115개예요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 한 의자에 4명씩 탈 수 있는 놀이기구가 있습니다. 의자가 27개이면 놀이기구에 탈 수 있는 사람은 모두 몇 명인가요?","options":[{"t":"108명","correct":true},{"t":"31명","mis":"M3-2-u1-X13"},{"t":"36명","mis":"M3-2-u1-X07"}],"explanation":["4명씩 27번 — 곱셈식 4 × 27로 세워요.","4 × 7 = 28, 4 × 20 = 80이에요 — 둘째 줄은 한 자리 밀어 써요.","4 × 27 = 108 — 108명이에요."]},{"stem":"「교과서 한 번 더」 — 신선한 당근이 한 봉지에 7개씩 25봉지가 있어요. 당근은 모두 몇 개인가요?","options":[{"t":"175개","correct":true},{"t":"32개","mis":"M3-2-u1-X13"},{"t":"49개","mis":"M3-2-u1-X07"}],"explanation":["7개씩 25번 — 곱셈식 7 × 25로 세워요.","7 × 5 = 35, 7 × 20 = 140이에요 — 둘째 줄은 한 자리 밀어 써요.","7 × 25 = 175 — 175개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#8','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":8,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"3 × 36","correct":true},{"t":"6 × 15","mis":"M3-2-u1-X12"},{"t":"4 × 24","mis":"M3-2-u1-X12"}],"explanation":["4 × 24 = 96, 6 × 15 = 90이에요.","3 × 36 = 108이에요.","곱해지는 수가 작아도 곱하는 수가 크면 곱이 클 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#9','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',2,'match','auto','「수학에 퐁당」 암호 — 곱셈의 계산 결과에 알맞은 글자를 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C6","difficulty":2,"kind":"match","stem":"「수학에 퐁당」 암호 — 곱셈의 계산 결과에 알맞은 글자를 이으세요.","pairs":[{"l":"7 × 35","r":"245 — 학"},{"l":"9 × 27","r":"243 — 은"},{"l":"8 × 34","r":"272 — 내"}],"mis":"M3-2-u1-X11","explanation":["7 × 35 = 245, 9 × 27 = 243이에요.","8 × 34 = 272예요.","245와 243처럼 비슷한 수는 끝자리까지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「수학에 퐁당」 암호 — 곱셈의 계산 결과에 알맞은 글자를 이으세요.","pairs":[{"l":"4 × 98","r":"392 — 친"},{"l":"3 × 54","r":"162 — 구"},{"l":"5 × 14","r":"70 — 수"}],"explanation":["4 × 98 = 392, 3 × 54 = 162예요.","5 × 14 = 70이에요.","암호는 「수학은 내 친구」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_basic#10','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_basic','lesson_basic','M3-2-u1-C6',3,'error','auto','7 × 16을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C6","difficulty":3,"kind":"error","stem":"7 × 16을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「7 × 16 = 49」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"도윤 — 「7 × 6 = 42, 7 × 10 = 70이라 112」","mis":"M3-2-u1-X15"},{"t":"채원 — 「16 × 7 = 112와 같아」","mis":"M3-2-u1-X15"}],"explanation":["7 × 6 = 42, 7 × 10 = 70이에요 — 둘째 줄은 한 자리 밀어 써요.","7 × 16 = 112예요.","건우는 49로 잘못 구했어요 — 십의 자리 곱은 한 자리 밀어 써요."],"variant_rule":{"alt":[{"stem":"5 × 23을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「5 × 23 = 25」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"서준 — 「5 × 3 = 15, 5 × 20 = 100이라 115」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「23 × 5 = 115와 같아」","mis":"M3-2-u1-X15"}],"explanation":["5 × 3 = 15, 5 × 20 = 100이에요 — 둘째 줄은 한 자리 밀어 써요.","5 × 23 = 115예요.","지유는 25로 잘못 구했어요 — 십의 자리 곱은 한 자리 밀어 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#1','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',2,'mc','auto','6 × 15에 알맞은 생활 속 문제는 어느 것인가요?',ARRAY['M3-2-u1-X13']::text[],false,'{"seq":1,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"6 × 15에 알맞은 생활 속 문제는 어느 것인가요?","options":[{"t":"쿠키가 한 상자에 6개씩 있습니다. 15상자에 있는 쿠키는 모두 몇 개인가요?","correct":true},{"t":"쿠키가 6개 있고 15개를 더 샀습니다. 쿠키는 모두 몇 개인가요?","mis":"M3-2-u1-X13"},{"t":"쿠키 15개를 6명이 똑같이 나누면 몇 개씩인가요?","mis":"M3-2-u1-X13"}],"explanation":["6 × 15는 6개씩 15묶음이에요.","한 상자에 6개씩 15상자가 알맞아요.","쿠키는 모두 6 × 15 = 90(개)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#2','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',2,'mc','auto','연필 한 묶음이 12자루씩 6묶음인 상황과 6자루씩 12묶음인 상황을 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u1-X21','M3-2-u1-X16']::text[],false,'{"seq":2,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"연필 한 묶음이 12자루씩 6묶음인 상황과 6자루씩 12묶음인 상황을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱은 72로 같지만 두 상황은 달라요","correct":true},{"t":"곱이 같으니 두 상황도 똑같아요","mis":"M3-2-u1-X21"},{"t":"곱하는 순서가 바뀌면 곱도 달라요","mis":"M3-2-u1-X16"}],"explanation":["12 × 6 = 72, 6 × 12 = 72예요.","12 × 6은 「한 묶음에 12자루인 연필이 6묶음」이에요.","6 × 12는 「한 묶음에 6자루인 연필이 12묶음」 — 곱은 같아도 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#3','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'sa','auto','1부터 9까지의 수 중에서 □ × 43 < 200의 □ 안에 들어갈 수 있는 가장 큰 수는 얼마인가요?','{}'::text[],false,'{"seq":3,"concept":"M3-2-u1-C6","difficulty":3,"kind":"sa","stem":"1부터 9까지의 수 중에서 □ × 43 < 200의 □ 안에 들어갈 수 있는 가장 큰 수는 얼마인가요?","answer":["4"],"explanation":["4 × 43 = 172예요.","5 × 43 = 215 — 200보다 커요.","그래서 □ 안에 들어갈 수 있는 가장 큰 수는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#4','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'mc','auto','암호 「수학은 내 친구」에서 「학」은 계산 결과 245에 알맞은 글자예요. 「학」에 해당하는 곱셈은 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],false,'{"seq":4,"concept":"M3-2-u1-C6","difficulty":3,"kind":"mc","stem":"암호 「수학은 내 친구」에서 「학」은 계산 결과 245에 알맞은 글자예요. 「학」에 해당하는 곱셈은 어느 것인가요?","options":[{"t":"7 × 35","correct":true},{"t":"9 × 27","mis":"M3-2-u1-X11"},{"t":"8 × 34","mis":"M3-2-u1-X11"}],"explanation":["7 × 35 = 35 + 210 = 245예요.","9 × 27 = 243(은), 8 × 34 = 272(내)예요.","245와 243은 비슷하니 끝자리까지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#5','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'error','auto','8 × 37을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X04','M3-2-u1-X15']::text[],true,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":3,"kind":"error","stem":"8 × 37을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「8 × 37 = 2456」","correct":true,"mis_target":"M3-2-u1-X04"},{"t":"건우 — 「8 × 7 = 56, 8 × 30 = 240이라 296」","mis":"M3-2-u1-X15"},{"t":"지유 — 「37 × 8 = 296과 같아」","mis":"M3-2-u1-X15"}],"explanation":["8 × 7 = 56, 8 × 30 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","8 × 37 = 296이에요.","채원은 2456으로 잘못 구했어요 — 10이 넘으면 윗자리로 올려요."],"variant_rule":{"alt":[{"stem":"9 × 15를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「9 × 15 = 945」","correct":true,"mis_target":"M3-2-u1-X04"},{"t":"도윤 — 「9 × 5 = 45, 9 × 10 = 90이라 135」","mis":"M3-2-u1-X15"},{"t":"채원 — 「15 × 9 = 135와 같아」","mis":"M3-2-u1-X15"}],"explanation":["9 × 5 = 45, 9 × 10 = 90이에요 — 둘째 줄은 한 자리 밀어 써요.","9 × 15 = 135예요.","서준은 945로 잘못 구했어요 — 10이 넘으면 윗자리로 올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#6','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'sa','auto','9 × 82는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C6","difficulty":3,"kind":"sa","stem":"9 × 82는 얼마인가요? 숫자로 쓰세요.","answer":["738"],"explanation":["곱하는 수 82를 2와 80으로 갈라요.","9 × 2 = 18, 9 × 80 = 720이에요 — 둘째 줄은 한 자리 밀어 써요.","18 + 720 = 738이에요."],"variant_rule":{"alt":[{"stem":"8 × 74는 얼마인가요? 숫자로 쓰세요.","answer":["592"],"explanation":["곱하는 수 74를 4와 70으로 갈라요.","8 × 4 = 32, 8 × 70 = 560이에요 — 둘째 줄은 한 자리 밀어 써요.","32 + 560 = 592예요."]},{"stem":"5 × 63은 얼마인가요? 숫자로 쓰세요.","answer":["315"],"explanation":["곱하는 수 63을 3과 60으로 갈라요.","5 × 3 = 15, 5 × 60 = 300이에요 — 둘째 줄은 한 자리 밀어 써요.","15 + 300 = 315예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#7','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',3,'mc','auto','7 × 16을 세로셈으로 계산할 때 둘째 줄의 7은 7 × 1을 쓴 것이에요. 이때 16의 1은 얼마를 나타내나요?',ARRAY['M3-2-u1-X07','M3-2-u1-X17']::text[],true,'{"seq":7,"concept":"M3-2-u1-C6","difficulty":3,"kind":"mc","stem":"7 × 16을 세로셈으로 계산할 때 둘째 줄의 7은 7 × 1을 쓴 것이에요. 이때 16의 1은 얼마를 나타내나요?","options":[{"t":"10","correct":true},{"t":"1","mis":"M3-2-u1-X07"},{"t":"100","mis":"M3-2-u1-X17"}],"explanation":["16은 10과 6이에요 — 1은 십의 자리 숫자예요.","그래서 둘째 줄은 7 × 10 = 70 — 한 자리 밀어 써요.","42 + 70 = 112 — 7 + 42 = 49가 아니에요."],"asset":{"type":"expr_grid","rows":[["","","","","7"],["×","","","1","6"],["","","","4","2"],["","","","7",""],["","","1","1","2"]]},"variant_rule":{"alt":[{"stem":"3 × 48을 세로셈으로 계산할 때 둘째 줄의 12는 3 × 4를 쓴 것이에요. 이때 48의 4는 얼마를 나타내나요?","options":[{"t":"40","correct":true},{"t":"4","mis":"M3-2-u1-X07"},{"t":"400","mis":"M3-2-u1-X17"}],"explanation":["48은 40과 8이에요 — 4는 십의 자리 숫자예요.","그래서 둘째 줄은 3 × 40 = 120 — 한 자리 밀어 써요.","24 + 120 = 144예요."],"asset":{"type":"expr_grid","rows":[["","","","","3"],["×","","","4","8"],["","","","2","4"],["","","1","2",""],["","","1","4","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#8','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',4,'essay','teacher','당근이 한 봉지에 7개씩 16봉지 있어요. 7 × 16을 계산하고 계산하는 방법을 설명한 뒤, 어림한 값과 비교해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C6","difficulty":4,"kind":"essay","stem":"당근이 한 봉지에 7개씩 16봉지 있어요. 7 × 16을 계산하고 계산하는 방법을 설명한 뒤, 어림한 값과 비교해 보세요.","answer_guide":{"answer":"예: 16을 6과 10으로 나누어 7 × 6 = 42, 7 × 10 = 70을 구하고 더하면 112이다. 16을 20으로 생각하면 약 140이므로 계산 결과 112가 적절하다.","scoring_points":["16을 6과 10으로 나누어 곱했는가","42 + 70 = 112를 구했는가","어림한 값(약 140)과 비교했는가"]},"explanation":["7 × 6 = 42.","7 × 10 = 70.","42 + 70 = 112 — 어림 약 140과 견주어 적절해요."],"asset":{"type":"expr_grid","rows":[["7 × 6","=","42"],["7 × 10","=","70"],["42 + 70","=","112"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#9','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',4,'essay','teacher','6 × 15에 알맞은 생활 속 문제를 만들고 해결해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C6","difficulty":4,"kind":"essay","stem":"6 × 15에 알맞은 생활 속 문제를 만들고 해결해 보세요.","answer_guide":{"answer":"예: 쿠키가 한 상자에 6개씩 있습니다. 15상자에 있는 쿠키는 모두 몇 개인가요? → 6 × 15 = 90이므로 90개이다.","scoring_points":["6개씩 15묶음인 상황으로 문제를 만들었는가","6 × 15 = 90을 바르게 계산했는가","단위를 붙여 답했는가"]},"explanation":["6 × 15는 6개씩 15묶음이에요.","6 × 5 = 30, 6 × 10 = 60이에요.","30 + 60 = 90 — 90개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L06_challenge#10','math',3,2,'u1','L06','tb_g3_2_math_u1_L06_challenge','lesson_challenge','M3-2-u1-C6',4,'sa','auto','5 × 84는 6 × 51보다 얼마나 더 큰가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u1-C6","difficulty":4,"kind":"sa","stem":"5 × 84는 6 × 51보다 얼마나 더 큰가요? 숫자로 쓰세요.","answer":["114"],"explanation":["5 × 84 = 20 + 400 = 420이에요.","6 × 51 = 6 + 300 = 306이에요.","420 − 306 = 114 — 114만큼 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#1','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',1,'mc','auto','식품 안전 체험관에서 체험 프로그램 한 개에 참여할 수 있는 사람은 24명이에요. 13개의 체험 프로그램이 동시에 시작된다면 참여할 수 있는 사람의 수를 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X08']::text[],true,'{"seq":1,"concept":"M3-2-u1-C7","difficulty":1,"kind":"mc","stem":"식품 안전 체험관에서 체험 프로그램 한 개에 참여할 수 있는 사람은 24명이에요. 13개의 체험 프로그램이 동시에 시작된다면 참여할 수 있는 사람의 수를 구하는 식은 어느 것인가요?","options":[{"t":"24 × 13","correct":true},{"t":"24 + 13","mis":"M3-2-u1-X13"},{"t":"24 × 3","mis":"M3-2-u1-X08"}],"explanation":["프로그램 한 개에 24명씩, 13개예요.","24명씩 13묶음은 24 × 13이에요.","24 × 3은 3개의 프로그램만 센 식이에요."],"variant_rule":{"alt":[{"stem":"식품 안전 체험관에서 12명씩 참여할 수 있는 프로그램 26개가 동시에 시작해요. 참여할 수 있는 사람의 수를 구하는 식은 어느 것인가요?","options":[{"t":"12 × 26","correct":true},{"t":"12 + 26","mis":"M3-2-u1-X13"},{"t":"12 × 6","mis":"M3-2-u1-X08"}],"explanation":["프로그램 한 개에 12명씩, 26개예요.","12명씩 26묶음은 12 × 26이에요.","12 × 6은 6개만 센 식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#2','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','24 × 13 — 24를 30으로, 13을 10으로 생각하여 어림하면 참여할 수 있는 사람은 약 몇 명인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],false,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"24 × 13 — 24를 30으로, 13을 10으로 생각하여 어림하면 참여할 수 있는 사람은 약 몇 명인가요?","options":[{"t":"약 300명","correct":true},{"t":"약 30명","mis":"M3-2-u1-X12"},{"t":"약 3000명","mis":"M3-2-u1-X06"}],"explanation":["24를 30으로, 13을 10으로 생각해요.","30 × 10 = 300이에요.","그래서 약 300명 — 계산 결과 312와 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#3','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',1,'sa','auto','24 × 13을 「방법 1」처럼 모눈종이를 4개의 부분으로 나누어 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"24 × 13을 「방법 1」처럼 모눈종이를 4개의 부분으로 나누어 계산했어요. □에 알맞은 수를 쓰세요.","answer":["200"],"explanation":["24를 20과 4로, 13을 10과 3으로 나누어요.","□는 20 × 10 = 200이에요.","12 + 60 + 40 + 200 = 312 — 24 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["×","20","4"],["10",null,"40"],["3","60","12"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 24 × 13을 「방법 1」처럼 모눈종이를 4개의 부분으로 나누어 계산했어요. □에 알맞은 수를 쓰세요.","answer":["60"],"explanation":["24를 20과 4로, 13을 10과 3으로 나누어요.","□는 20 × 3 = 60이에요.","12 + 60 + 40 + 200 = 312 — 24 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["×","20","4"],["10","200","40"],["3",null,"12"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#4','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',1,'sa','auto','12 × 16은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C7","difficulty":1,"kind":"sa","stem":"12 × 16은 얼마인가요? 숫자로 쓰세요.","answer":["192"],"explanation":["곱하는 수 16을 6과 10으로 갈라요.","12 × 6 = 72, 12 × 10 = 120이에요 — 둘째 줄은 한 자리 밀어 써요.","72 + 120 = 192예요."],"variant_rule":{"alt":[{"stem":"15 × 21은 얼마인가요? 숫자로 쓰세요.","answer":["315"],"explanation":["곱하는 수 21을 1과 20으로 갈라요.","15 × 1 = 15, 15 × 20 = 300이에요 — 둘째 줄은 한 자리 밀어 써요.","15 + 300 = 315예요."]},{"stem":"23 × 14는 얼마인가요? 숫자로 쓰세요.","answer":["322"],"explanation":["곱하는 수 14를 4와 10으로 갈라요.","23 × 4 = 92, 23 × 10 = 230이에요 — 둘째 줄은 한 자리 밀어 써요.","92 + 230 = 322예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#5','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'sa','auto','24 × 13을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"24 × 13을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["240"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","□는 24 × 10 = 240이에요.","72 + 240 = 312 — 24 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["24 × 3","=","72"],["24 × 10","=",null],["72 + □","=","312"]]},"variant_rule":{"alt":[{"stem":"28 × 13을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["280"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","□는 28 × 10 = 280이에요.","84 + 280 = 364 — 28 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["28 × 3","=","84"],["28 × 10","=",null],["84 + □","=","364"]]}},{"stem":"이번에는 다른 보기예요. 24 × 13을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["72"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","□는 24 × 3 = 72예요.","72 + 240 = 312 — 24 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["24 × 3","=",null],["24 × 10","=","240"],["□ + 240","=","312"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#6','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'sa','auto','24 × 13을 세로셈으로 계산했어요. 곱은 얼마인가요?','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"24 × 13을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["312"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","24 × 3 = 72, 24 × 10 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","72 + 240 = 312예요."],"asset":{"type":"expr_grid","rows":[["","","","2","4"],["×","","","1","3"],["","","","7","2"],["","","2","4",""],["","",null,null,null]]},"variant_rule":{"alt":[{"stem":"32 × 24를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["768"],"explanation":["곱하는 수 24를 4와 20으로 갈라요.","32 × 4 = 128, 32 × 20 = 640이에요 — 둘째 줄은 한 자리 밀어 써요.","128 + 640 = 768이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","2"],["×","","","2","4"],["","","1","2","8"],["","","6","4",""],["","",null,null,null]]}},{"stem":"13 × 42를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["546"],"explanation":["곱하는 수 42를 2와 40으로 갈라요.","13 × 2 = 26, 13 × 40 = 520이에요 — 둘째 줄은 한 자리 밀어 써요.","26 + 520 = 546이에요."],"asset":{"type":"expr_grid","rows":[["","","","1","3"],["×","","","4","2"],["","","","2","6"],["","","5","2",""],["","",null,null,null]]}},{"stem":"36 × 21을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["756"],"explanation":["곱하는 수 21을 1과 20으로 갈라요.","36 × 1 = 36, 36 × 20 = 720이에요 — 둘째 줄은 한 자리 밀어 써요.","36 + 720 = 756이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","6"],["×","","","2","1"],["","","","3","6"],["","","7","2",""],["","",null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#7','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'mc','auto','꽈배기가 쟁반 한 개에 14개씩 있습니다. 쟁반 16개에 있는 꽈배기는 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],true,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":2,"kind":"mc","stem":"꽈배기가 쟁반 한 개에 14개씩 있습니다. 쟁반 16개에 있는 꽈배기는 모두 몇 개인가요?","options":[{"t":"224개","correct":true},{"t":"30개","mis":"M3-2-u1-X13"},{"t":"98개","mis":"M3-2-u1-X07"}],"explanation":["14개씩 16번 — 곱셈식 14 × 16으로 세워요.","14 × 6 = 84, 14 × 10 = 140이에요 — 둘째 줄은 한 자리 밀어 써요.","14 × 16 = 224 — 224개예요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 채원이네 학교는 한 학급에 학생이 18명씩 있습니다. 전체 학급 수가 19학급이라면 학생은 모두 몇 명인가요?","options":[{"t":"342명","correct":true},{"t":"37명","mis":"M3-2-u1-X13"},{"t":"180명","mis":"M3-2-u1-X07"}],"explanation":["18명씩 19번 — 곱셈식 18 × 19로 세워요.","18 × 9 = 162, 18 × 10 = 180이에요 — 둘째 줄은 한 자리 밀어 써요.","18 × 19 = 342 — 342명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#8','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u1-C7","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"41 × 24","r":"984"},{"l":"52 × 13","r":"676"},{"l":"27 × 31","r":"837"}],"mis":"M3-2-u1-X09","explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","41 × 24 = 984, 52 × 13 = 676, 27 × 31 = 837.","곱이 비슷해 보여도 끝자리까지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"16 × 13","r":"208"},{"l":"31 × 17","r":"527"},{"l":"23 × 34","r":"782"}],"explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","16 × 13 = 208, 31 × 17 = 527, 23 × 34 = 782.","곱이 비슷해 보여도 끝자리까지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#9','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',2,'mc','auto','계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  61 × 14 ○ 42 × 23',ARRAY['M3-2-u1-X11','M3-2-u1-X12']::text[],false,'{"seq":9,"concept":"M3-2-u1-C7","difficulty":2,"kind":"mc","stem":"계산 결과를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  61 × 14 ○ 42 × 23","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u1-X11"},{"t":"=","mis":"M3-2-u1-X12"}],"explanation":["61 × 14 = 854예요.","42 × 23 = 966이에요.","854 < 966이므로 61 × 14 < 42 × 23이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_basic#10','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_basic','lesson_basic','M3-2-u1-C7',3,'error','auto','24 × 13을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X15']::text[],true,'{"seq":10,"concept":"M3-2-u1-C7","difficulty":3,"kind":"error","stem":"24 × 13을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「24 × 13 = 96」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"건우 — 「72 + 240 = 312」","mis":"M3-2-u1-X15"},{"t":"채원 — 「12 + 60 + 40 + 200 = 312」","mis":"M3-2-u1-X15"}],"explanation":["24 × 3 = 72, 24 × 10 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","24 × 13 = 312예요.","서준은 96으로 잘못 구했어요 — 십의 자리 곱은 한 자리 밀어 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 24 × 13을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「24 × 13 = 212」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"지유 — 「24 × 3 = 72, 24 × 10 = 240이라 312」","mis":"M3-2-u1-X15"},{"t":"서준 — 「4 × 3, 20 × 3, 4 × 10, 20 × 10을 모두 더해 312」","mis":"M3-2-u1-X15"}],"explanation":["24 × 3 = 72, 24 × 10 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","24 × 13 = 312예요.","도윤은 212로 잘못 구했어요 — 네 덩이를 모두 곱해 더해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#1','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',2,'mc','auto','24 × 13을 모눈종이로 계산한 「방법 1」과 「방법 2」를 바르게 비교한 것은 어느 것인가요?',ARRAY['M3-2-u1-X16','M3-2-u1-X08']::text[],false,'{"seq":1,"concept":"M3-2-u1-C7","difficulty":2,"kind":"mc","stem":"24 × 13을 모눈종이로 계산한 「방법 1」과 「방법 2」를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"방법 1은 4개의 부분, 방법 2는 2개의 부분으로 나누어 계산하고 결과는 같아요","correct":true},{"t":"방법 1과 방법 2는 계산 결과가 달라요","mis":"M3-2-u1-X16"},{"t":"방법 2는 24 × 3만 구하면 돼요","mis":"M3-2-u1-X08"}],"explanation":["방법 1: 4 × 3 = 12, 20 × 3 = 60, 4 × 10 = 40, 20 × 10 = 200이에요.","방법 2: 24 × 3 = 72, 24 × 10 = 240이에요.","두 방법 모두 312 — 나누는 방법이 달라도 결과는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#2','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',2,'mc','auto','「서술형」 — 태국 돈 1밧은 우리나라 돈 36원과 같다고 합니다. 12밧은 우리나라 돈으로 얼마인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":2,"concept":"M3-2-u1-C7","difficulty":2,"kind":"mc","stem":"「서술형」 — 태국 돈 1밧은 우리나라 돈 36원과 같다고 합니다. 12밧은 우리나라 돈으로 얼마인가요?","options":[{"t":"432원","correct":true},{"t":"48원","mis":"M3-2-u1-X13"},{"t":"108원","mis":"M3-2-u1-X07"}],"explanation":["36원씩 12번 — 곱셈식 36 × 12로 세워요.","36 × 2 = 72, 36 × 10 = 360이에요 — 둘째 줄은 한 자리 밀어 써요.","36 × 12 = 432 — 432원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#3','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C3',3,'mc','auto','채원이는 친구들과 29 × 13을 어림했어요. 채원 「29를 30으로 생각하면 약 390」, 건우 「13을 10으로 생각하면 약 290」, 도윤 「29를 30, 13을 10으로 생각하면 약 300」. 계산하면 377이에요. 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u1-X20']::text[],false,'{"seq":3,"concept":"M3-2-u1-C3","difficulty":3,"kind":"mc","stem":"채원이는 친구들과 29 × 13을 어림했어요. 채원 「29를 30으로 생각하면 약 390」, 건우 「13을 10으로 생각하면 약 290」, 도윤 「29를 30, 13을 10으로 생각하면 약 300」. 계산하면 377이에요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"세 친구 모두 알맞게 어림했어요","correct":true},{"t":"계산 결과와 가장 가까운 채원이만 알맞게 어림했어요","mis":"M3-2-u1-X20"},{"t":"두 수를 모두 바꾼 도윤이만 알맞게 어림했어요","mis":"M3-2-u1-X20"}],"explanation":["어림하는 방법은 여러 가지예요.","390, 290, 300 모두 계산 결과 377과 비슷한 크기예요.","어림은 옳다·그르다보다 어떻게 하면 더 정확할지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#4','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'sa','auto','「고대 이집트 곱셈법」 — 2배 하기로 24 × 8을 구했어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u1-C7","difficulty":3,"kind":"sa","stem":"「고대 이집트 곱셈법」 — 2배 하기로 24 × 8을 구했어요. □에 알맞은 수를 쓰세요.","answer":["192"],"explanation":["24 × 2 = 48은 24의 2배, 24 × 4 = 96은 48의 2배예요.","24 × 8은 96의 2배라 192예요.","24 × 13 = 24 × 1 + 24 × 4 + 24 × 8 = 24 + 96 + 192 = 312예요."],"asset":{"type":"expr_grid","rows":[["24 × 1","=","24"],["24 × 2","=","48"],["24 × 4","=","96"],["24 × 8","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#5','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'error','auto','28 × 13을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X15']::text[],true,'{"seq":5,"concept":"M3-2-u1-C7","difficulty":3,"kind":"error","stem":"28 × 13을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「28 × 13 = 112」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"채원 — 「28 × 3 = 84, 28 × 10 = 280이라 364」","mis":"M3-2-u1-X15"},{"t":"건우 — 「84 + 280 = 364」","mis":"M3-2-u1-X15"}],"explanation":["28 × 3 = 84, 28 × 10 = 280이에요 — 둘째 줄은 한 자리 밀어 써요.","28 × 13 = 364예요.","지유는 112로 잘못 구했어요 — 십의 자리 곱은 한 자리 밀어 써요."],"variant_rule":{"alt":[{"stem":"41 × 24를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「41 × 24 = 804」","correct":true,"mis_target":"M3-2-u1-X09"},{"t":"서준 — 「41 × 4 = 164, 41 × 20 = 820이라 984」","mis":"M3-2-u1-X15"},{"t":"도윤 — 「164 + 820 = 984」","mis":"M3-2-u1-X15"}],"explanation":["41 × 4 = 164, 41 × 20 = 820이에요 — 둘째 줄은 한 자리 밀어 써요.","41 × 24 = 984예요.","건우는 804로 잘못 구했어요 — 네 덩이를 모두 곱해 더해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#6','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'mc','auto','12 × 16을 세로셈으로 계산할 때 둘째 줄에 12를 한 자리 밀어 써요. 이 12는 어떤 곱셈의 값을 나타내나요?',ARRAY['M3-2-u1-X07','M3-2-u1-X08']::text[],true,'{"seq":6,"concept":"M3-2-u1-C7","difficulty":3,"kind":"mc","stem":"12 × 16을 세로셈으로 계산할 때 둘째 줄에 12를 한 자리 밀어 써요. 이 12는 어떤 곱셈의 값을 나타내나요?","options":[{"t":"12 × 10 = 120","correct":true},{"t":"12 × 1 = 12","mis":"M3-2-u1-X07"},{"t":"12 × 16 = 192","mis":"M3-2-u1-X08"}],"explanation":["16의 1은 10을 나타내요.","그래서 둘째 줄은 12 × 10 = 120 — 12를 한 자리 밀어 써요.","72 + 120 = 192예요."],"asset":{"type":"expr_grid","rows":[["","","","1","2"],["×","","","1","6"],["","","","7","2"],["","","1","2",""],["","","1","9","2"]]},"variant_rule":{"alt":[{"stem":"15 × 21을 세로셈으로 계산할 때 둘째 줄에 30을 한 자리 밀어 써요. 이 30은 어떤 곱셈의 값을 나타내나요?","options":[{"t":"15 × 20 = 300","correct":true},{"t":"15 × 2 = 30","mis":"M3-2-u1-X07"},{"t":"15 × 21 = 315","mis":"M3-2-u1-X08"}],"explanation":["21의 2는 20을 나타내요.","그래서 둘째 줄은 15 × 20 = 300 — 30을 한 자리 밀어 써요.","15 + 300 = 315예요."],"asset":{"type":"expr_grid","rows":[["","","","1","5"],["×","","","2","1"],["","","","1","5"],["","","3","0",""],["","","3","1","5"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#7','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',3,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":7,"concept":"M3-2-u1-C7","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"42 × 23","correct":true},{"t":"23 × 34","mis":"M3-2-u1-X12"},{"t":"31 × 17","mis":"M3-2-u1-X12"}],"explanation":["16 × 13 = 208, 42 × 23 = 966이에요.","31 × 17 = 527, 23 × 34 = 782예요.","가장 큰 것은 42 × 23이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#8','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',4,'essay','teacher','24 × 13을 모눈종이를 4개의 부분으로 나누는 방법과 2개의 부분으로 나누는 방법으로 각각 계산하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C7","difficulty":4,"kind":"essay","stem":"24 × 13을 모눈종이를 4개의 부분으로 나누는 방법과 2개의 부분으로 나누는 방법으로 각각 계산하고 설명해 보세요.","answer_guide":{"answer":"예: 4개의 부분 — 4 × 3 = 12, 20 × 3 = 60, 4 × 10 = 40, 20 × 10 = 200을 모두 더하면 312이다. 2개의 부분 — 24 × 3 = 72, 24 × 10 = 240을 더하면 312이다.","scoring_points":["네 부분 곱 12, 60, 40, 200을 구했는가","두 부분 곱 72, 240을 구했는가","두 방법 모두 312임을 썼는가"]},"explanation":["12 + 60 + 40 + 200 = 312.","72 + 240 = 312.","나누는 방법이 달라도 결과는 같아요."],"asset":{"type":"expr_grid","rows":[["×","20","4"],["10","200","40"],["3","60","12"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#9','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',4,'essay','teacher','「서술형」 태국 돈 1밧은 우리나라 돈 36원과 같다고 합니다. 12밧은 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C7","difficulty":4,"kind":"essay","stem":"「서술형」 태국 돈 1밧은 우리나라 돈 36원과 같다고 합니다. 12밧은 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 1밧은 36원과 같으므로 12밧은 36 × 12를 계산한다. 36 × 2 = 72, 36 × 10 = 360이므로 72 + 360 = 432(원)이다.","scoring_points":["식 36 × 12를 세웠는가","72와 360을 구해 더했는가","432원이라고 답했는가"]},"explanation":["1밧 = 36원 → 12밧은 36 × 12.","36 × 2 = 72, 36 × 10 = 360.","72 + 360 = 432 — 432원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L07_challenge#10','math',3,2,'u1','L07','tb_g3_2_math_u1_L07_challenge','lesson_challenge','M3-2-u1-C7',4,'sa','auto','채원이처럼 29를 30으로 생각해 29 × 13을 어림한 값은 30 × 13 = 390이에요. 어림한 값은 계산 결과보다 얼마나 더 큰가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u1-C7","difficulty":4,"kind":"sa","stem":"채원이처럼 29를 30으로 생각해 29 × 13을 어림한 값은 30 × 13 = 390이에요. 어림한 값은 계산 결과보다 얼마나 더 큰가요? 숫자로 쓰세요.","answer":["13"],"explanation":["29 × 13 = 87 + 290 = 377이에요.","30 × 13 = 390이에요.","390 − 377 = 13 — 29 대신 30을 곱해 13이 한 번 더 들어갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#1','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',1,'mc','auto','건강한 간식 만들기 체험에서 견과류 과자를 한 판에 39개씩 26판을 만들었어요. 견과류 과자의 수를 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X08']::text[],true,'{"seq":1,"concept":"M3-2-u1-C8","difficulty":1,"kind":"mc","stem":"건강한 간식 만들기 체험에서 견과류 과자를 한 판에 39개씩 26판을 만들었어요. 견과류 과자의 수를 구하는 식은 어느 것인가요?","options":[{"t":"39 × 26","correct":true},{"t":"39 + 26","mis":"M3-2-u1-X13"},{"t":"39 × 6","mis":"M3-2-u1-X08"}],"explanation":["한 판에 39개씩, 26판이에요.","39개씩 26묶음은 39 × 26이에요.","39 × 6은 6판만 센 식이에요."],"variant_rule":{"alt":[{"stem":"「교과서 한 번 더」 — 견과류 과자를 한 판에 28개씩 46판을 만들었어요. 견과류 과자의 수를 구하는 식은 어느 것인가요?","options":[{"t":"28 × 46","correct":true},{"t":"28 + 46","mis":"M3-2-u1-X13"},{"t":"28 × 6","mis":"M3-2-u1-X08"}],"explanation":["한 판에 28개씩, 46판이에요.","28개씩 46묶음은 28 × 46이에요.","28 × 6은 6판만 센 식이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#2','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C3',1,'mc','auto','39 × 26 — 39를 40으로, 26을 30으로 생각하면 1200, 26을 20으로 생각하면 800이에요. 견과류 과자의 수를 바르게 어림한 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":2,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"39 × 26 — 39를 40으로, 26을 30으로 생각하면 1200, 26을 20으로 생각하면 800이에요. 견과류 과자의 수를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"800개보다 많고 1200개보다 적어요","correct":true},{"t":"800개보다 적어요","mis":"M3-2-u1-X12"},{"t":"1200개보다 많아요","mis":"M3-2-u1-X12"}],"explanation":["40 × 30 = 1200 — 39 × 26은 이보다 작아요.","40 × 20 = 800 — 39 × 26은 이보다 커요.","그래서 800개보다 많고 1200개보다 적어요 — 약 1000개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#3','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',1,'sa','auto','39 × 26을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"39 × 26을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["780"],"explanation":["곱하는 수 26을 6과 20으로 갈라요.","□는 39 × 20 = 780이에요.","234 + 780 = 1014 — 39 × 26의 곱이에요."],"asset":{"type":"expr_grid","rows":[["39 × 6","=","234"],["39 × 20","=",null],["234 + □","=","1014"]]},"variant_rule":{"alt":[{"stem":"46 × 34를 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["1380"],"explanation":["곱하는 수 34를 4와 30으로 갈라요.","□는 46 × 30 = 1380이에요.","184 + 1380 = 1564 — 46 × 34의 곱이에요."],"asset":{"type":"expr_grid","rows":[["46 × 4","=","184"],["46 × 30","=",null],["184 + □","=","1564"]]}},{"stem":"28 × 46을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["168"],"explanation":["곱하는 수 46을 6과 40으로 갈라요.","□는 28 × 6 = 168이에요.","168 + 1120 = 1288 — 28 × 46의 곱이에요."],"asset":{"type":"expr_grid","rows":[["28 × 6","=",null],["28 × 40","=","1120"],["□ + 1120","=","1288"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#4','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',1,'sa','auto','29 × 63은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"29 × 63은 얼마인가요? 숫자로 쓰세요.","answer":["1827"],"explanation":["곱하는 수 63을 3과 60으로 갈라요.","29 × 3 = 87, 29 × 60 = 1740이에요 — 둘째 줄은 한 자리 밀어 써요.","87 + 1740 = 1827이에요."],"variant_rule":{"alt":[{"stem":"73 × 24는 얼마인가요? 숫자로 쓰세요.","answer":["1752"],"explanation":["곱하는 수 24를 4와 20으로 갈라요.","73 × 4 = 292, 73 × 20 = 1460이에요 — 둘째 줄은 한 자리 밀어 써요.","292 + 1460 = 1752예요."]},{"stem":"85 × 37은 얼마인가요? 숫자로 쓰세요.","answer":["3145"],"explanation":["곱하는 수 37을 7과 30으로 갈라요.","85 × 7 = 595, 85 × 30 = 2550이에요 — 둘째 줄은 한 자리 밀어 써요.","595 + 2550 = 3145예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#5','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'sa','auto','39 × 26을 세로셈으로 계산했어요. 곱은 얼마인가요?','{}'::text[],true,'{"seq":5,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"39 × 26을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["1014"],"explanation":["곱하는 수 26을 6과 20으로 갈라요.","39 × 6 = 234, 39 × 20 = 780이에요 — 둘째 줄은 한 자리 밀어 써요.","234 + 780 = 1014예요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","7","8",""],["",null,null,null,null]]},"variant_rule":{"alt":[{"stem":"74 × 62를 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["4588"],"explanation":["곱하는 수 62를 2와 60으로 갈라요.","74 × 2 = 148, 74 × 60 = 4440이에요 — 둘째 줄은 한 자리 밀어 써요.","148 + 4440 = 4588이에요."],"asset":{"type":"expr_grid","rows":[["","","","7","4"],["×","","","6","2"],["","","1","4","8"],["","4","4","4",""],["",null,null,null,null]]}},{"stem":"23 × 58을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["1334"],"explanation":["곱하는 수 58을 8과 50으로 갈라요.","23 × 8 = 184, 23 × 50 = 1150이에요 — 둘째 줄은 한 자리 밀어 써요.","184 + 1150 = 1334예요."],"asset":{"type":"expr_grid","rows":[["","","","2","3"],["×","","","5","8"],["","","1","8","4"],["","1","1","5",""],["",null,null,null,null]]}},{"stem":"28 × 46을 세로셈으로 계산했어요. 곱은 얼마인가요?","answer":["1288"],"explanation":["곱하는 수 46을 6과 40으로 갈라요.","28 × 6 = 168, 28 × 40 = 1120이에요 — 둘째 줄은 한 자리 밀어 써요.","168 + 1120 = 1288이에요."],"asset":{"type":"expr_grid","rows":[["","","","2","8"],["×","","","4","6"],["","","1","6","8"],["","1","1","2",""],["",null,null,null,null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#6','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'mc','auto','45명씩 탈 수 있는 버스가 15대 있습니다. 버스에 탈 수 있는 사람은 모두 몇 명인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],true,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":2,"kind":"mc","stem":"45명씩 탈 수 있는 버스가 15대 있습니다. 버스에 탈 수 있는 사람은 모두 몇 명인가요?","options":[{"t":"675명","correct":true},{"t":"60명","mis":"M3-2-u1-X13"},{"t":"270명","mis":"M3-2-u1-X07"}],"explanation":["45명씩 15번 — 곱셈식 45 × 15로 세워요.","45 × 5 = 225, 45 × 10 = 450이에요 — 둘째 줄은 한 자리 밀어 써요.","45 × 15 = 675 — 675명이에요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 — 귤이 한 상자에 35개씩 들어 있습니다. 49상자에 들어 있는 귤은 모두 몇 개인가요?","options":[{"t":"1715개","correct":true},{"t":"84개","mis":"M3-2-u1-X13"},{"t":"455개","mis":"M3-2-u1-X07"}],"explanation":["35개씩 49번 — 곱셈식 35 × 49로 세워요.","35 × 9 = 315, 35 × 40 = 1400이에요 — 둘째 줄은 한 자리 밀어 써요.","35 × 49 = 1715 — 1715개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#7','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'mc','auto','계산 결과가 더 작은 것은 어느 것인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X11']::text[],false,'{"seq":7,"concept":"M3-2-u1-C8","difficulty":2,"kind":"mc","stem":"계산 결과가 더 작은 것은 어느 것인가요?","options":[{"t":"53 × 25","correct":true},{"t":"34 × 41","mis":"M3-2-u1-X12"},{"t":"두 곱이 같아요","mis":"M3-2-u1-X11"}],"explanation":["53 × 25 = 265 + 1060 = 1325예요.","34 × 41 = 34 + 1360 = 1394예요.","1325 < 1394 — 53 × 25가 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#8','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'match','auto','곱셈식과 곱을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u1-C8","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"28 × 29","r":"812"},{"l":"53 × 64","r":"3392"},{"l":"43 × 36","r":"1548"}],"mis":"M3-2-u1-X10","explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","28 × 29 = 812, 53 × 64 = 3392, 43 × 36 = 1548.","곱이 비슷해 보여도 끝자리까지 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 알맞게 이으세요.","pairs":[{"l":"72 × 27","r":"1944"},{"l":"29 × 63","r":"1827"},{"l":"73 × 24","r":"1752"}],"explanation":["자리마다(또는 곱하는 수를 갈라) 곱한 뒤 더해요.","72 × 27 = 1944, 29 × 63 = 1827, 73 × 24 = 1752.","곱이 비슷해 보여도 끝자리까지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#9','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',2,'ox','auto','39 × 26의 세로셈 둘째 줄에는 39 × 20 = 780을 나타내도록 78을 한 자리 밀어 써요.',ARRAY['M3-2-u1-X07']::text[],false,'{"seq":9,"concept":"M3-2-u1-C8","difficulty":2,"kind":"ox","stem":"39 × 26의 세로셈 둘째 줄에는 39 × 20 = 780을 나타내도록 78을 한 자리 밀어 써요.","answer":"O","reason_options":[{"t":"26의 2는 20을 나타내 39 × 20 = 780이니까","correct":true},{"t":"둘째 줄도 일의 자리부터 맞춰 써야 하니까","mis":"M3-2-u1-X07"}],"mis":"M3-2-u1-X07","explanation":["26을 6과 20으로 나누어요.","39 × 6 = 234, 39 × 20 = 780이에요.","234 + 780 = 1014 — 둘째 줄은 한 자리 밀어 써요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","7","8",""],["","1","0","1","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_basic#10','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_basic','lesson_basic','M3-2-u1-C8',3,'mc','auto','「선택해서 활동해요」 — 친구가 44 × 26을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X09']::text[],true,'{"seq":10,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"「선택해서 활동해요」 — 친구가 44 × 26을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"44 × 20 = 880인데 첫째 줄에서 올림한 2를 더해 1080으로 썼어요","correct":true},{"t":"둘째 줄을 한 자리 밀어 쓰지 않았어요","mis":"M3-2-u1-X07"},{"t":"일의 자리끼리, 십의 자리끼리만 곱했어요","mis":"M3-2-u1-X09"}],"explanation":["44 × 6 = 264예요.","44 × 20 = 880 — 첫째 줄의 올림 2를 더하면 안 돼요.","264 + 880 = 1144예요."],"asset":{"type":"expr_grid","rows":[["","","","4","4"],["×","","","2","6"],["","","2","6","4"],["","1","0","8",""],["","1","3","4","4"]]},"variant_rule":{"alt":[{"stem":"「선택해서 활동해요」 — 친구가 37 × 48을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"37 × 40 = 1480인데 148을 한 자리 밀어 쓰지 않았어요","correct":true},{"t":"앞 줄에서 올림한 수를 다음 줄에 더했어요","mis":"M3-2-u1-X10"},{"t":"올림한 수를 더하지 않았어요","mis":"M3-2-u1-X02"}],"explanation":["37 × 8 = 296이에요.","37 × 40 = 1480 — 148을 한 자리 밀어 써요.","296 + 1480 = 1776이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","7"],["×","","","4","8"],["","","2","9","6"],["","","1","4","8"],["","","4","4","4"]]}},{"stem":"「선택해서 활동해요」 — 친구가 63 × 45를 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"63 × 40 = 2520인데 올림한 1을 더하지 않아 2420으로 썼어요","correct":true},{"t":"둘째 줄을 한 자리 밀어 쓰지 않았어요","mis":"M3-2-u1-X07"},{"t":"앞 줄에서 올림한 수를 다음 줄에 더했어요","mis":"M3-2-u1-X10"}],"explanation":["63 × 5 = 315예요.","63 × 4: 3 × 4 = 12에서 1을 올리고 6 × 4 + 1 = 25 — 2520이에요.","315 + 2520 = 2835예요."],"asset":{"type":"expr_grid","rows":[["","","","6","3"],["×","","","4","5"],["","","3","1","5"],["","2","4","2",""],["","2","7","3","5"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#1','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',2,'ox','auto','29 × 63 = 1827이에요.',ARRAY['M3-2-u1-X07']::text[],true,'{"seq":1,"concept":"M3-2-u1-C8","difficulty":2,"kind":"ox","stem":"29 × 63 = 1827이에요.","answer":"O","reason_options":[{"t":"29 × 3 = 87, 29 × 60 = 1740을 더하면 1827이니까","correct":true},{"t":"29 × 6 = 174를 밀지 않고 더해 261이니까","mis":"M3-2-u1-X07"}],"mis":"M3-2-u1-X07","explanation":["29 × 3 = 87이에요.","29 × 60 = 1740이에요.","87 + 1740 = 1827 — 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"74 × 62 = 4588이에요.","answer":"O","reason_options":[{"t":"74 × 2 = 148, 74 × 60 = 4440을 더하면 4588이니까","correct":true},{"t":"74 × 6 = 444를 밀지 않고 더해 592니까","mis":"M3-2-u1-X07"}],"explanation":["74 × 2 = 148이에요.","74 × 60 = 4440이에요.","148 + 4440 = 4588 — 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#2','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',2,'mc','auto','「수학에 퐁당」 26 × 43을 선을 그어 구했어요. 선끼리 만나 생긴 점이 백의 자리 8개, 십의 자리 30개, 일의 자리 18개예요. 26 × 43은 얼마인가요?',ARRAY['M3-2-u1-X17','M3-2-u1-X04']::text[],false,'{"seq":2,"concept":"M3-2-u1-C8","difficulty":2,"kind":"mc","stem":"「수학에 퐁당」 26 × 43을 선을 그어 구했어요. 선끼리 만나 생긴 점이 백의 자리 8개, 십의 자리 30개, 일의 자리 18개예요. 26 × 43은 얼마인가요?","options":[{"t":"1118","correct":true},{"t":"56","mis":"M3-2-u1-X17"},{"t":"83018","mis":"M3-2-u1-X04"}],"explanation":["백의 자리 점 8개는 800, 십의 자리 점 30개는 300이에요.","일의 자리 점 18개는 18이에요.","800 + 300 + 18 = 1118 — 26 × 43 = 1118이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#3','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'sa','auto','수 카드 2, 4, 5, 6, 8을 한 번씩만 사용하여 만들 수 있는 두 자리 수 중에서 가장 큰 수와 가장 작은 수의 곱을 구해 보세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u1-C8","difficulty":3,"kind":"sa","stem":"수 카드 2, 4, 5, 6, 8을 한 번씩만 사용하여 만들 수 있는 두 자리 수 중에서 가장 큰 수와 가장 작은 수의 곱을 구해 보세요. 숫자로 쓰세요.","answer":["2064"],"explanation":["가장 큰 두 자리 수는 86, 가장 작은 두 자리 수는 24예요.","86 × 4 = 344, 86 × 20 = 1720이에요.","344 + 1720 = 2064예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#4','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'mc','auto','친구가 76 × 32를 1814라고 했어요. 친구가 잘못 계산한 방법은 어느 것인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X02']::text[],false,'{"seq":4,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 76 × 32를 1814라고 했어요. 친구가 잘못 계산한 방법은 어느 것인가요?","options":[{"t":"6 × 3 = 18, 7 × 2 = 14처럼 엇갈려 곱해 이어 썼어요","correct":true},{"t":"둘째 줄을 한 자리 밀어 쓰지 않았어요","mis":"M3-2-u1-X07"},{"t":"올림한 수를 더하지 않았어요","mis":"M3-2-u1-X02"}],"explanation":["76 × 2 = 152, 76 × 30 = 2280이에요.","152 + 2280 = 2432예요.","두 수를 엇갈려 곱해 이어 쓰면 안 돼요 — 한 줄씩 곱해 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#5','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'mc','auto','계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":5,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"74 × 62","correct":true},{"t":"53 × 64","mis":"M3-2-u1-X12"},{"t":"85 × 37","mis":"M3-2-u1-X12"}],"explanation":["74 × 62 = 4588, 85 × 37 = 3145예요.","53 × 64 = 3392, 29 × 63 = 1827이에요.","가장 큰 것은 74 × 62예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#6','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',3,'sa','auto','39 × 26을 세로셈으로 계산할 때 둘째 줄에 78을 한 자리 밀어 써요. 이 78이 나타내는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":3,"kind":"sa","stem":"39 × 26을 세로셈으로 계산할 때 둘째 줄에 78을 한 자리 밀어 써요. 이 78이 나타내는 수는 얼마인가요? 숫자로 쓰세요.","answer":["780"],"explanation":["26의 2는 20을 나타내요.","39 × 20 = 780이에요.","그래서 78을 한 자리 밀어 써 780을 나타내요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","7","8",""],["","1","0","1","4"]]},"variant_rule":{"alt":[{"stem":"46 × 34를 세로셈으로 계산할 때 둘째 줄에 138을 한 자리 밀어 써요. 이 138이 나타내는 수는 얼마인가요? 숫자로 쓰세요.","answer":["1380"],"explanation":["34의 3은 30을 나타내요.","46 × 30 = 1380이에요.","그래서 138을 한 자리 밀어 써 1380을 나타내요."],"asset":{"type":"expr_grid","rows":[["","","","4","6"],["×","","","3","4"],["","","1","8","4"],["","1","3","8",""],["","1","5","6","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#7','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C3',3,'mc','auto','65 × 35를 어림하려고 해요. 65를 70으로, 35를 40으로 생각하면 약 얼마인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X12']::text[],false,'{"seq":7,"concept":"M3-2-u1-C3","difficulty":3,"kind":"mc","stem":"65 × 35를 어림하려고 해요. 65를 70으로, 35를 40으로 생각하면 약 얼마인가요?","options":[{"t":"약 2800","correct":true},{"t":"약 280","mis":"M3-2-u1-X06"},{"t":"약 1800","mis":"M3-2-u1-X12"}],"explanation":["65를 70으로, 35를 40으로 생각해요.","70 × 40 = 2800이에요.","그래서 65 × 35는 약 2800이에요(두 수를 올려 어림해 실제보다 커요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#8','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',4,'essay','teacher','견과류 과자를 한 판에 39개씩 26판 만들었어요. 39 × 26을 계산하는 방법을 설명하고, 어림한 값과 비교해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C8","difficulty":4,"kind":"essay","stem":"견과류 과자를 한 판에 39개씩 26판 만들었어요. 39 × 26을 계산하는 방법을 설명하고, 어림한 값과 비교해 보세요.","answer_guide":{"answer":"예: 26을 20과 6으로 나누어 계산하면 39 × 6 = 234, 39 × 20 = 780이므로 234 + 780 = 1014이다. 800보다 크고 1200보다 작은 약 1000으로 어림했으므로 계산 결과가 적절하다.","scoring_points":["26을 6과 20으로 나누어 곱했는가","234 + 780 = 1014를 구했는가","어림한 값(약 1000 또는 800~1200)과 비교했는가"]},"explanation":["39 × 6 = 234.","39 × 20 = 780.","234 + 780 = 1014 — 어림 약 1000과 비슷해요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","7","8",""],["","1","0","1","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#9','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',4,'essay','teacher','친구가 44 × 26을 오른쪽처럼 계산했어요. 잘못 계산한 곳을 찾아 이유를 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C8","difficulty":4,"kind":"essay","stem":"친구가 44 × 26을 오른쪽처럼 계산했어요. 잘못 계산한 곳을 찾아 이유를 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 44 × 20 = 880인데 1080으로 잘못 계산했다. 첫째 줄에서 올림한 2를 둘째 줄 계산에 더했기 때문이다. 바르게 계산하면 264 + 880 = 1144이다.","scoring_points":["둘째 줄(1080)이 잘못되었다고 찾았는가","앞 줄의 올림을 더했다고 이유를 썼는가","1144를 구했는가"]},"explanation":["44 × 6 = 264.","44 × 20 = 880 — 앞 줄 올림은 따로예요.","264 + 880 = 1144."],"asset":{"type":"expr_grid","rows":[["","","","4","4"],["×","","","2","6"],["","","2","6","4"],["","1","0","8",""],["","1","3","4","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L08_challenge#10','math',3,2,'u1','L08','tb_g3_2_math_u1_L08_challenge','lesson_challenge','M3-2-u1-C8',4,'sa','auto','친구가 37 × 48을 296 + 148 = 444라고 계산했어요. 37 × 48을 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"친구가 37 × 48을 296 + 148 = 444라고 계산했어요. 37 × 48을 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.","answer":["1776"],"explanation":["37 × 8 = 296이에요.","37 × 40 = 1480 — 148을 한 자리 밀어 써요.","296 + 1480 = 1776이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","7"],["×","","","4","8"],["","","2","9","6"],["","","1","4","8"],["","","4","4","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#1','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'mc','auto','「걸리버의 신발을 만들려면 내 신발을 만드는 데 필요한 가죽의 20배가 필요해.」 마을 사람의 신발에 가죽이 31장 필요하다면, 걸리버에게 필요한 가죽의 양을 구하는 식은 어느 것인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X06']::text[],false,'{"seq":1,"concept":"M3-2-u1-C9","difficulty":1,"kind":"mc","stem":"「걸리버의 신발을 만들려면 내 신발을 만드는 데 필요한 가죽의 20배가 필요해.」 마을 사람의 신발에 가죽이 31장 필요하다면, 걸리버에게 필요한 가죽의 양을 구하는 식은 어느 것인가요?","options":[{"t":"31 × 20","correct":true},{"t":"31 + 20","mis":"M3-2-u1-X13"},{"t":"31 × 2","mis":"M3-2-u1-X06"}],"explanation":["가죽 31장의 20배예요.","「몇 배」는 곱셈 — 31 × 20이에요.","31 × 2는 2배일 때의 식이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#2','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'sa','auto','걸리버에게 가죽이 31장의 20배 필요해요. 가죽은 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u1-C9","difficulty":1,"kind":"sa","stem":"걸리버에게 가죽이 31장의 20배 필요해요. 가죽은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["620"],"explanation":["곱하는 수 20의 0을 잠시 떼고 31 × 2 = 62예요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","31 × 20은 62의 10배인 620이에요 — 가죽 620장이 필요해요."],"variant_rule":{"alt":[{"stem":"걸리버에게 천이 109장의 8배 필요해요. 천은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["872"],"explanation":["109를 100, 0, 9로 갈라 8을 곱해요: 100 × 8 = 800, 0 × 8 = 0, 9 × 8 = 72.","일의 자리 9 × 8 = 72에서 7을 십의 자리로 올림해요.","800 + 0 + 72 = 872예요 — 천 872장이 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#3','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'mc','auto','「걸리버의 옷을 만들려면 내 옷을 만드는 데 필요한 천의 6배를 준비해야 해.」 마을 사람의 옷에 천이 138장 필요해요. 걸리버에게 필요한 천은 몇 장인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02']::text[],false,'{"seq":3,"concept":"M3-2-u1-C9","difficulty":1,"kind":"mc","stem":"「걸리버의 옷을 만들려면 내 옷을 만드는 데 필요한 천의 6배를 준비해야 해.」 마을 사람의 옷에 천이 138장 필요해요. 걸리버에게 필요한 천은 몇 장인가요?","options":[{"t":"828장","correct":true},{"t":"144장","mis":"M3-2-u1-X13"},{"t":"688장","mis":"M3-2-u1-X02"}],"explanation":["138을 100, 30, 8로 갈라 6을 곱해요: 100 × 6 = 600, 30 × 6 = 180, 8 × 6 = 48.","일의 자리 8 × 6 = 48에서 4를 십의 자리로 올림, 십의 자리 3 × 6 + 4 = 22에서 2를 백의 자리로 올림해요.","600 + 180 + 48 = 828이에요 — 천 828장이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#4','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',1,'sa','auto','「걸리버는 내가 마시는 물의 27배를 마셔.」 마을 사람이 물을 17잔 마신다면 걸리버는 물을 몇 잔 마시나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u1-C9","difficulty":1,"kind":"sa","stem":"「걸리버는 내가 마시는 물의 27배를 마셔.」 마을 사람이 물을 17잔 마신다면 걸리버는 물을 몇 잔 마시나요? 숫자로 쓰세요.","answer":["459"],"explanation":["곱하는 수 27을 7과 20으로 갈라요.","17 × 7 = 119, 17 × 20 = 340이에요 — 둘째 줄은 한 자리 밀어 써요.","119 + 340 = 459예요 — 물 459잔이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#5','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'mc','auto','「걸리버가 먹을 생선구이를 준비하려면 내가 먹는 생선구이를 만들 때 드는 물고기의 49배가 필요해.」 마을 사람에게 물고기가 5마리 든다면 걸리버에게는 몇 마리가 필요한가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":5,"concept":"M3-2-u1-C9","difficulty":2,"kind":"mc","stem":"「걸리버가 먹을 생선구이를 준비하려면 내가 먹는 생선구이를 만들 때 드는 물고기의 49배가 필요해.」 마을 사람에게 물고기가 5마리 든다면 걸리버에게는 몇 마리가 필요한가요?","options":[{"t":"245마리","correct":true},{"t":"54마리","mis":"M3-2-u1-X13"},{"t":"65마리","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 49를 9와 40으로 갈라요.","5 × 9 = 45, 5 × 40 = 200이에요 — 둘째 줄은 한 자리 밀어 써요.","45 + 200 = 245예요 — 물고기 245마리가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#6','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'ox','auto','걸리버에게 가죽이 31장의 20배 필요하니까, 천도 31장의 6배를 준비하면 돼요.',ARRAY['M3-2-u1-X13']::text[],false,'{"seq":6,"concept":"M3-2-u1-C9","difficulty":2,"kind":"ox","stem":"걸리버에게 가죽이 31장의 20배 필요하니까, 천도 31장의 6배를 준비하면 돼요.","answer":"X","reason_options":[{"t":"재료마다 마을 사람 한 명에게 필요한 양이 달라 천은 138장의 6배니까","correct":true},{"t":"앞에서 쓴 31장을 모든 재료에 쓰면 되니까","mis":"M3-2-u1-X13"}],"mis":"M3-2-u1-X13","explanation":["가죽은 31장의 20배, 천은 138장의 6배예요.","재료마다 한 사람에게 필요한 양이 달라요.","천은 138 × 6 = 828(장) — 31 × 6 = 186이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#7','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'mc','auto','물이 17잔의 27배 필요해요. 친구는 419잔이라고 했어요. 걸리버에게 필요한 물은 몇 잔인가요?',ARRAY['M3-2-u1-X11','M3-2-u1-X13']::text[],false,'{"seq":7,"concept":"M3-2-u1-C9","difficulty":2,"kind":"mc","stem":"물이 17잔의 27배 필요해요. 친구는 419잔이라고 했어요. 걸리버에게 필요한 물은 몇 잔인가요?","options":[{"t":"459잔","correct":true},{"t":"419잔","mis":"M3-2-u1-X11"},{"t":"44잔","mis":"M3-2-u1-X13"}],"explanation":["곱하는 수 27을 7과 20으로 갈라요.","17 × 7 = 119, 17 × 20 = 340이에요 — 둘째 줄은 한 자리 밀어 써요.","119 + 340 = 459예요 — 419잔은 계산 실수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#8','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'sa','auto','「침대를 만들기 위해서는 재료로 나무가 필요해. 우리 물건을 만드는 데 92만큼 필요하고, 걸리버의 물건을 만드는 데에는 41배가 더 필요해.」 걸리버의 침대에 필요한 나무는 얼마만큼인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"「침대를 만들기 위해서는 재료로 나무가 필요해. 우리 물건을 만드는 데 92만큼 필요하고, 걸리버의 물건을 만드는 데에는 41배가 더 필요해.」 걸리버의 침대에 필요한 나무는 얼마만큼인가요? 숫자로 쓰세요.","answer":["3772"],"explanation":["곱하는 수 41을 1과 40으로 갈라요.","92 × 1 = 92, 92 × 40 = 3680이에요 — 둘째 줄은 한 자리 밀어 써요.","92 + 3680 = 3772예요 — 나무가 3772만큼 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#9','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',2,'match','auto','걸리버에게 필요한 것과 필요한 양을 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u1-C9","difficulty":2,"kind":"match","stem":"걸리버에게 필요한 것과 필요한 양을 이으세요.","pairs":[{"l":"가죽: 31장의 20배","r":"620장"},{"l":"천: 138장의 6배","r":"828장"},{"l":"물: 17잔의 27배","r":"459잔"}],"mis":"M3-2-u1-X13","explanation":["31 × 20 = 620, 138 × 6 = 828이에요.","17 × 27 = 459예요.","걸리버에게 어떤 것이 얼마나 필요한지 확인하고 곱셈으로 구해요."],"variant_rule":{"alt":[{"stem":"「익힘」 걸리버에게 필요한 것과 필요한 양을 이으세요.","pairs":[{"l":"천: 109장의 8배","r":"872장"},{"l":"사과: 8개의 35배","r":"280개"},{"l":"가죽: 51장의 19배","r":"969장"}],"explanation":["109 × 8 = 872, 8 × 35 = 280이에요.","51 × 19 = 969예요.","「몇의 몇 배」는 곱셈으로 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_basic#10','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_basic','lesson_basic','M3-2-u1-C9',3,'mc','auto','「가방이 필요할 것 같아. 그걸 만들기 위해서는 재료로 가죽이 필요해. 우리 물건을 만드는 데 12만큼 필요하고, 걸리버의 물건을 만드는 데에는 25배가 더 필요해.」 걸리버의 가방에 필요한 가죽은 얼마만큼인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":10,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"「가방이 필요할 것 같아. 그걸 만들기 위해서는 재료로 가죽이 필요해. 우리 물건을 만드는 데 12만큼 필요하고, 걸리버의 물건을 만드는 데에는 25배가 더 필요해.」 걸리버의 가방에 필요한 가죽은 얼마만큼인가요?","options":[{"t":"300만큼","correct":true},{"t":"37만큼","mis":"M3-2-u1-X13"},{"t":"84만큼","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 25를 5와 20으로 갈라요.","12 × 5 = 60, 12 × 20 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","60 + 240 = 300이에요 — 가죽이 300만큼 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#1','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',2,'mc','auto','마을 사람들의 대화를 완성해요. 「우리 물건을 만드는 데 92만큼 필요하고, 걸리버의 물건을 만드는 데에는 41배가 더 필요해.」 「그럼 (     )만큼 필요하겠네.」',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":1,"concept":"M3-2-u1-C9","difficulty":2,"kind":"mc","stem":"마을 사람들의 대화를 완성해요. 「우리 물건을 만드는 데 92만큼 필요하고, 걸리버의 물건을 만드는 데에는 41배가 더 필요해.」 「그럼 (     )만큼 필요하겠네.」","options":[{"t":"3772","correct":true},{"t":"133","mis":"M3-2-u1-X13"},{"t":"460","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 41을 1과 40으로 갈라요.","92 × 1 = 92, 92 × 40 = 3680이에요 — 둘째 줄은 한 자리 밀어 써요.","92 + 3680 = 3772예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#2','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',2,'mc','auto','「익힘」 「걸리버를 위한 사과는 내가 먹는 양의 35배를 준비해야 돼.」 마을 사람이 사과를 8개 먹는다면 걸리버에게 필요한 사과는 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":2,"concept":"M3-2-u1-C9","difficulty":2,"kind":"mc","stem":"「익힘」 「걸리버를 위한 사과는 내가 먹는 양의 35배를 준비해야 돼.」 마을 사람이 사과를 8개 먹는다면 걸리버에게 필요한 사과는 몇 개인가요?","options":[{"t":"280개","correct":true},{"t":"43개","mis":"M3-2-u1-X13"},{"t":"64개","mis":"M3-2-u1-X07"}],"explanation":["곱하는 수 35를 5와 30으로 갈라요.","8 × 5 = 40, 8 × 30 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","40 + 240 = 280이에요 — 사과 280개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#3','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'mc','auto','「익힘」 「걸리버의 신발을 만들려면 내 신발을 만드는 데 필요한 가죽의 19배가 필요해.」 마을 사람 한 명에게 가죽이 51장 필요하다고 정했어요. 걸리버에게 필요한 가죽은 몇 장인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X09']::text[],true,'{"seq":3,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"「익힘」 「걸리버의 신발을 만들려면 내 신발을 만드는 데 필요한 가죽의 19배가 필요해.」 마을 사람 한 명에게 가죽이 51장 필요하다고 정했어요. 걸리버에게 필요한 가죽은 몇 장인가요?","options":[{"t":"969장","correct":true},{"t":"510장","mis":"M3-2-u1-X07"},{"t":"509장","mis":"M3-2-u1-X09"}],"explanation":["곱하는 수 19를 9와 10으로 갈라요.","51 × 9 = 459, 51 × 10 = 510이에요 — 둘째 줄은 한 자리 밀어 써요.","459 + 510 = 969예요 — 가죽 969장이 필요해요."],"variant_rule":{"alt":[{"stem":"「익힘」 마을 사람 한 명에게 가죽이 40장 필요하다고 정했어요. 걸리버에게 가죽이 19배 필요하다면 몇 장인가요?","options":[{"t":"760장","correct":true},{"t":"400장","mis":"M3-2-u1-X07"},{"t":"360장","mis":"M3-2-u1-X08"}],"explanation":["곱하는 수 19를 9와 10으로 갈라요.","40 × 9 = 360, 40 × 10 = 400이에요 — 둘째 줄은 한 자리 밀어 써요.","360 + 400 = 760이에요 — 가죽 760장이 필요해요."]},{"stem":"「익힘」 마을 사람 한 명에게 가죽이 26장 필요하다고 정했어요. 걸리버에게 가죽이 19배 필요하다면 몇 장인가요?","options":[{"t":"494장","correct":true},{"t":"260장","mis":"M3-2-u1-X07"},{"t":"254장","mis":"M3-2-u1-X09"}],"explanation":["곱하는 수 19를 9와 10으로 갈라요.","26 × 9 = 234, 26 × 10 = 260이에요 — 둘째 줄은 한 자리 밀어 써요.","234 + 260 = 494예요 — 가죽 494장이 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#4','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'sa','auto','「익힘」 「걸리버는 내가 먹는 닭고기의 48배를 먹더라고.」 마을 사람이 닭고기를 17조각 먹는다면 걸리버는 몇 조각을 먹나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"「익힘」 「걸리버는 내가 먹는 닭고기의 48배를 먹더라고.」 마을 사람이 닭고기를 17조각 먹는다면 걸리버는 몇 조각을 먹나요? 숫자로 쓰세요.","answer":["816"],"explanation":["곱하는 수 48을 8과 40으로 갈라요.","17 × 8 = 136, 17 × 40 = 680이에요 — 둘째 줄은 한 자리 밀어 써요.","136 + 680 = 816이에요 — 닭고기 816조각이에요."],"variant_rule":{"alt":[{"stem":"「익힘」 마을 사람이 닭고기를 14조각 먹는다고 정했어요. 걸리버가 그 48배를 먹는다면 몇 조각인가요? 숫자로 쓰세요.","answer":["672"],"explanation":["곱하는 수 48을 8과 40으로 갈라요.","14 × 8 = 112, 14 × 40 = 560이에요 — 둘째 줄은 한 자리 밀어 써요.","112 + 560 = 672예요 — 닭고기 672조각이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#5','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'error','auto','걸리버에게 필요한 양을 구했어요. 잘못 구한 친구는 누구인가요? (가죽 31장의 20배, 물 17잔의 27배, 물고기 5마리의 49배)',ARRAY['M3-2-u1-X13','M3-2-u1-X15']::text[],false,'{"seq":5,"concept":"M3-2-u1-C9","difficulty":3,"kind":"error","stem":"걸리버에게 필요한 양을 구했어요. 잘못 구한 친구는 누구인가요? (가죽 31장의 20배, 물 17잔의 27배, 물고기 5마리의 49배)","options":[{"t":"건우 — 「물고기는 31 × 49 = 1519마리」","correct":true,"mis_target":"M3-2-u1-X13"},{"t":"채원 — 「가죽은 31 × 20 = 620장」","mis":"M3-2-u1-X15"},{"t":"지유 — 「물은 17 × 27 = 459잔」","mis":"M3-2-u1-X15"}],"explanation":["재료마다 마을 사람 한 명에게 필요한 양이 달라요.","물고기는 5마리의 49배 — 5 × 49 = 245(마리)예요.","건우는 가죽의 31을 물고기에도 써서 식을 잘못 세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#6','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'sa','auto','「익힘」 마을 사람이 닭고기를 48조각 먹는다고 정했어요. 걸리버가 그 48배를 먹는다면 몇 조각인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"「익힘」 마을 사람이 닭고기를 48조각 먹는다고 정했어요. 걸리버가 그 48배를 먹는다면 몇 조각인가요? 숫자로 쓰세요.","answer":["2304"],"explanation":["곱하는 수 48을 8과 40으로 갈라요.","48 × 8 = 384, 48 × 40 = 1920이에요 — 둘째 줄은 한 자리 밀어 써요.","384 + 1920 = 2304예요 — 닭고기 2304조각이에요."],"variant_rule":{"alt":[{"stem":"「익힘」 마을 사람이 닭고기를 71조각 먹는다고 정했어요. 걸리버가 그 48배를 먹는다면 몇 조각인가요? 숫자로 쓰세요.","answer":["3408"],"explanation":["곱하는 수 48을 8과 40으로 갈라요.","71 × 8 = 568, 71 × 40 = 2840이에요 — 둘째 줄은 한 자리 밀어 써요.","568 + 2840 = 3408이에요 — 닭고기 3408조각이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#7','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',3,'mc','auto','「익힘」 걸리버에게 천이 109장의 8배 필요해요. 식과 값을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X05']::text[],false,'{"seq":7,"concept":"M3-2-u1-C9","difficulty":3,"kind":"mc","stem":"「익힘」 걸리버에게 천이 109장의 8배 필요해요. 식과 값을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"109 × 8 = 872","correct":true},{"t":"109 + 8 = 117","mis":"M3-2-u1-X13"},{"t":"109 × 8 = 952","mis":"M3-2-u1-X05"}],"explanation":["109를 100, 0, 9로 갈라 8을 곱해요: 100 × 8 = 800, 0 × 8 = 0, 9 × 8 = 72.","일의 자리 9 × 8 = 72에서 7을 십의 자리로 올림해요.","800 + 0 + 72 = 872예요 — 952는 0 × 8을 8로 셈한 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#8','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',4,'essay','teacher','걸리버를 위해 더 필요한 물건을 정하고, 마을 사람들의 대화를 완성해 보세요. (단, 마을 사람 물건에 필요한 양과 몇 배는 두 자리 수만 넣어요.)','{}'::text[],false,'{"seq":8,"concept":"M3-2-u1-C9","difficulty":4,"kind":"essay","stem":"걸리버를 위해 더 필요한 물건을 정하고, 마을 사람들의 대화를 완성해 보세요. (단, 마을 사람 물건에 필요한 양과 몇 배는 두 자리 수만 넣어요.)","answer_guide":{"answer":"예: 마을 사람 1 「걸리버를 위해 어떤 물건이 더 필요할까?」 마을 사람 2 「침대가 필요할 것 같아.」 마을 사람 3 「그걸 만들기 위해서는 재료로 나무가 필요해.」 마을 사람 4 「우리 물건을 만드는 데 92만큼 필요하고, 걸리버의 물건을 만드는 데에는 41배가 더 필요해.」 마을 사람 1 「그럼 92 × 41 = 3772만큼 필요하겠네.」","scoring_points":["물건과 재료를 정했는가","두 자리 수로 필요한 양과 몇 배를 정했는가","곱셈으로 필요한 재료의 양을 바르게 구했는가"]},"explanation":["필요한 물건과 재료를 정해요.","한 사람에게 필요한 양 × 몇 배로 식을 세워요.","예: 92 × 41 = 3772, 12 × 25 = 300."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#9','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',4,'essay','teacher','걸리버에게 가죽은 31장의 20배, 천은 138장의 6배, 물은 17잔의 27배, 물고기는 5마리의 49배가 필요해요. 필요한 양을 구하는 과정을 설명하고 각각 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u1-C9","difficulty":4,"kind":"essay","stem":"걸리버에게 가죽은 31장의 20배, 천은 138장의 6배, 물은 17잔의 27배, 물고기는 5마리의 49배가 필요해요. 필요한 양을 구하는 과정을 설명하고 각각 구해 보세요.","answer_guide":{"answer":"예: 걸리버에게 어떤 것이 얼마나 필요한지 확인하고 곱셈으로 구한다. 가죽 31 × 20 = 620(장), 천 138 × 6 = 828(장), 물 17 × 27 = 459(잔), 물고기 5 × 49 = 245(마리)이다.","scoring_points":["「몇의 몇 배」를 곱셈으로 세운다고 설명했는가","네 가지 양을 바르게 구했는가","단위를 붙였는가"]},"explanation":["「몇의 몇 배」 → 곱셈.","620장, 828장, 459잔, 245마리.","재료마다 한 사람에게 필요한 양이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_L09_challenge#10','math',3,2,'u1','L09','tb_g3_2_math_u1_L09_challenge','lesson_challenge','M3-2-u1-C9',4,'mc','auto','친구가 걸리버에게 필요한 양을 「가죽 31 × 20 = 620(장), 천 138 × 6 = 688(장), 물 17 × 27 = 419(잔), 물고기 5 × 49 = 245(마리)」라고 구했어요. 바르게 구하지 못한 것을 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u1-X15','M3-2-u1-X11']::text[],false,'{"seq":10,"concept":"M3-2-u1-C9","difficulty":4,"kind":"mc","stem":"친구가 걸리버에게 필요한 양을 「가죽 31 × 20 = 620(장), 천 138 × 6 = 688(장), 물 17 × 27 = 419(잔), 물고기 5 × 49 = 245(마리)」라고 구했어요. 바르게 구하지 못한 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"천과 물","correct":true},{"t":"가죽과 물고기","mis":"M3-2-u1-X15"},{"t":"천만","mis":"M3-2-u1-X11"}],"explanation":["138 × 6 = 828이라 천은 688이 아니에요 — 올림을 빠뜨렸어요.","17 × 27 = 459라 물은 419가 아니에요.","가죽 620장과 물고기 245마리는 바르게 구했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#1','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C1',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 212 × 4의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 212 × 4의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","212 × 4 = 848이에요.","?에 알맞은 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","2","1","2"],["×","","","","4"],["","","8",null,"8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#2','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 12 × 20의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 12 × 20의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["12 × 2 = 24예요.","12 × 20은 24의 10배라 240이에요.","?에 알맞은 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","1","2"],["×","","2","0"],["","2",null,"0"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#3','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C1',1,'sa','auto','423 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u1-C1","difficulty":1,"kind":"sa","stem":"423 × 2는 얼마인가요? 숫자로 쓰세요.","answer":["846"],"explanation":["423을 400, 20, 3으로 갈라 2를 곱해요: 400 × 2 = 800, 20 × 2 = 40, 3 × 2 = 6.","어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요.","800 + 40 + 6 = 846이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#4','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',1,'sa','auto','80 × 70은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"80 × 70은 얼마인가요? 숫자로 쓰세요.","answer":["5600"],"explanation":["80 × 7 = 560이에요.","곱하는 수가 7에서 70으로 10배가 되면 곱도 10배예요.","80 × 70은 560의 10배인 5600이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#5','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C6',1,'sa','auto','5 × 38은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"5 × 38은 얼마인가요? 숫자로 쓰세요.","answer":["190"],"explanation":["곱하는 수 38을 8과 30으로 갈라요.","5 × 8 = 40, 5 × 30 = 150이에요 — 둘째 줄은 한 자리 밀어 써요.","40 + 150 = 190이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#6','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C8',1,'sa','auto','12 × 37은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"12 × 37은 얼마인가요? 숫자로 쓰세요.","answer":["444"],"explanation":["곱하는 수 37을 7과 30으로 갈라요.","12 × 7 = 84, 12 × 30 = 360이에요 — 둘째 줄은 한 자리 밀어 써요.","84 + 360 = 444예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#7','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',1,'mc','auto','「스스로 마무리하기」 45 × 30을 「방법 1」로 계산해요. 45 × 30 = 45 × 3 × 10 = □ × 10 = 1350에서 □는 얼마인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X13']::text[],false,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 45 × 30을 「방법 1」로 계산해요. 45 × 30 = 45 × 3 × 10 = □ × 10 = 1350에서 □는 얼마인가요?","options":[{"t":"135","correct":true},{"t":"1350","mis":"M3-2-u1-X06"},{"t":"48","mis":"M3-2-u1-X13"}],"explanation":["45 × 3 = 135예요.","135 × 10 = 1350이에요.","「방법 2」 45 × 10 × 3 = 450 × 3 = 1350으로도 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#8','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C3',1,'mc','auto','「스스로 마무리하기」 계산 결과가 1000보다 큰 것을 모두 고른 것은 어느 것인가요?  23 × 43 · 175 × 6 · 42 × 28 · 322 × 3',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":8,"concept":"M3-2-u1-C3","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 계산 결과가 1000보다 큰 것을 모두 고른 것은 어느 것인가요?  23 × 43 · 175 × 6 · 42 × 28 · 322 × 3","options":[{"t":"175 × 6, 42 × 28","correct":true},{"t":"23 × 43, 322 × 3","mis":"M3-2-u1-X12"},{"t":"175 × 6, 322 × 3","mis":"M3-2-u1-X12"}],"explanation":["23 × 43 = 989, 175 × 6 = 1050이에요.","42 × 28 = 1176, 322 × 3 = 966이에요.","1000보다 큰 것은 175 × 6과 42 × 28 — 계산 전에 어림해 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#9','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C4',2,'mc','auto','「스스로 마무리하기」 건우네 학교 학생들은 1년에 191일씩 학교에 갑니다. 6년 동안 학교에 가는 날은 모두 며칠인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02']::text[],false,'{"seq":9,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 건우네 학교 학생들은 1년에 191일씩 학교에 갑니다. 6년 동안 학교에 가는 날은 모두 며칠인가요?","options":[{"t":"1146일","correct":true},{"t":"197일","mis":"M3-2-u1-X13"},{"t":"646일","mis":"M3-2-u1-X02"}],"explanation":["191일씩 6번 — 곱셈식 191 × 6으로 세워요.","십의 자리 9 × 6 = 54에서 5를 백의 자리로 올림, 백의 자리 1 × 6 + 5 = 11이에요.","191 × 6 = 1146 — 1146일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#10','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C7',2,'mc','auto','「스스로 마무리하기」 페트병 16개를 활용하여 재활용 가방을 한 개 만들 수 있습니다. 똑같은 재활용 가방을 21개 만든다면 페트병은 모두 몇 개 필요한가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":10,"concept":"M3-2-u1-C7","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 페트병 16개를 활용하여 재활용 가방을 한 개 만들 수 있습니다. 똑같은 재활용 가방을 21개 만든다면 페트병은 모두 몇 개 필요한가요?","options":[{"t":"336개","correct":true},{"t":"37개","mis":"M3-2-u1-X13"},{"t":"48개","mis":"M3-2-u1-X07"}],"explanation":["16개씩 21번 — 곱셈식 16 × 21로 세워요.","16 × 1 = 16, 16 × 20 = 320이에요 — 둘째 줄은 한 자리 밀어 써요.","16 × 21 = 336 — 336개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#11','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C6',2,'mc','auto','「이 단원 학습을 마치고」 고구마를 더 많이 캔 반에게 도장을 찍어 준대요. 한 반은 한 봉지에 6개씩 38봉지, 다른 반은 한 상자에 12개씩 19상자를 캤어요. 어느 반이 더 많이 캤나요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":11,"concept":"M3-2-u1-C6","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 고구마를 더 많이 캔 반에게 도장을 찍어 준대요. 한 반은 한 봉지에 6개씩 38봉지, 다른 반은 한 상자에 12개씩 19상자를 캤어요. 어느 반이 더 많이 캤나요?","options":[{"t":"두 반이 같아요","correct":true},{"t":"12개씩 담은 반 — 한 상자에 담은 수가 더 많아서","mis":"M3-2-u1-X12"},{"t":"6개씩 담은 반 — 봉지 수가 더 많아서","mis":"M3-2-u1-X12"}],"explanation":["6 × 38 = 48 + 180 = 228(개)이에요.","12 × 19 = 108 + 120 = 228(개)이에요.","두 반 모두 228개 — 똑같아요. 둘 다 도장을 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#12','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',2,'sa','auto','파프리카가 한 봉지에 14개씩 들어 있습니다. 20봉지에 들어 있는 파프리카는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"파프리카가 한 봉지에 14개씩 들어 있습니다. 20봉지에 들어 있는 파프리카는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["280"],"explanation":["14개씩 20번 — 곱셈식 14 × 20으로 세워요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","14 × 20 = 280 — 280개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#13','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C6',2,'sa','auto','7 × 16을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"7 × 16을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["70"],"explanation":["곱하는 수 16을 6과 10으로 갈라요.","□는 7 × 10 = 70이에요.","42 + 70 = 112 — 7 × 16의 곱이에요."],"asset":{"type":"expr_grid","rows":[["7 × 6","=","42"],["7 × 10","=",null],["42 + □","=","112"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#14','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C7',2,'sa','auto','24 × 13을 모눈종이를 4개의 부분으로 나누어 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"24 × 13을 모눈종이를 4개의 부분으로 나누어 계산했어요. □에 알맞은 수를 쓰세요.","answer":["40"],"explanation":["24를 20과 4로, 13을 10과 3으로 나누어요.","□는 4 × 10 = 40이에요.","12 + 60 + 40 + 200 = 312예요."],"asset":{"type":"expr_grid","rows":[["×","20","4"],["10","200",null],["3","60","12"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#15','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C3',2,'mc','auto','39 × 26을 어림했어요. 견과류 과자 39개씩 26판의 수를 바르게 어림한 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"39 × 26을 어림했어요. 견과류 과자 39개씩 26판의 수를 바르게 어림한 것은 어느 것인가요?","options":[{"t":"800개보다 많고 1200개보다 적어요","correct":true},{"t":"800개보다 적어요","mis":"M3-2-u1-X12"},{"t":"1200개보다 많아요","mis":"M3-2-u1-X12"}],"explanation":["40 × 20 = 800 — 39 × 26은 이보다 커요.","40 × 30 = 1200 — 39 × 26은 이보다 작아요.","계산하면 1014 — 어림한 사이에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#16','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C9',2,'sa','auto','걸리버에게 가죽이 31장의 20배 필요해요. 가죽은 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"걸리버에게 가죽이 31장의 20배 필요해요. 가죽은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["620"],"explanation":["곱하는 수 20의 0을 잠시 떼고 31 × 2 = 62예요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","31 × 20은 62의 10배인 620이에요 — 620장 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#17','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C2',3,'error','auto','307 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],false,'{"seq":17,"concept":"M3-2-u1-C2","difficulty":3,"kind":"error","stem":"307 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「307 × 3 = 931」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"채원 — 「900 + 0 + 21 = 921」","mis":"M3-2-u1-X15"},{"t":"서준 — 「7 × 3 = 21의 2를 올려 0 × 3 + 2 = 2라서 921」","mis":"M3-2-u1-X15"}],"explanation":["일의 자리 7 × 3 = 21에서 2를 십의 자리로 올림해요.","307 × 3 = 921이에요.","도윤은 931로 잘못 구했어요 — 0에 어떤 수를 곱해도 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#18','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C2',3,'ox','auto','217 × 2 = 424예요.',ARRAY['M3-2-u1-X02']::text[],false,'{"seq":18,"concept":"M3-2-u1-C2","difficulty":3,"kind":"ox","stem":"217 × 2 = 424예요.","answer":"X","reason_options":[{"t":"7 × 2 = 14에서 올림한 1을 십의 자리에 더하면 434니까","correct":true},{"t":"올림한 수는 더하지 않아도 되니까","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["7 × 2 = 14 — 4를 쓰고 1을 올려요.","십의 자리 1 × 2 + 1 = 3이에요.","217 × 2 = 434 — 424가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#19','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C8',3,'mc','auto','친구가 44 × 26을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X09']::text[],false,'{"seq":19,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 44 × 26을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"44 × 20 = 880인데 첫째 줄에서 올림한 2를 더해 1080으로 썼어요","correct":true},{"t":"둘째 줄을 한 자리 밀어 쓰지 않았어요","mis":"M3-2-u1-X07"},{"t":"일의 자리끼리, 십의 자리끼리만 곱했어요","mis":"M3-2-u1-X09"}],"explanation":["44 × 6 = 264예요.","44 × 20 = 880이에요.","264 + 880 = 1144예요."],"asset":{"type":"expr_grid","rows":[["","","","4","4"],["×","","","2","6"],["","","2","6","4"],["","1","0","8",""],["","1","3","4","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#20','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C5',3,'error','auto','14 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X15']::text[],false,'{"seq":20,"concept":"M3-2-u1-C5","difficulty":3,"kind":"error","stem":"14 × 20을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「14 × 20 = 28」","correct":true,"mis_target":"M3-2-u1-X06"},{"t":"채원 — 「14 × 2 = 28의 10배라 280」","mis":"M3-2-u1-X15"},{"t":"지유 — 「14 × 10 = 140의 2배라 280」","mis":"M3-2-u1-X15"}],"explanation":["곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","14 × 20 = 280이에요.","도윤은 28로 잘못 구했어요 — 0을 떼고 곱한 뒤 10배를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#21','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C6',3,'sa','auto','「익힘」 1부터 9까지의 수 중에서 □ × 43 < 200의 □ 안에 들어갈 수 있는 가장 큰 수는 얼마인가요?','{}'::text[],false,'{"seq":21,"concept":"M3-2-u1-C6","difficulty":3,"kind":"sa","stem":"「익힘」 1부터 9까지의 수 중에서 □ × 43 < 200의 □ 안에 들어갈 수 있는 가장 큰 수는 얼마인가요?","answer":["4"],"explanation":["4 × 43 = 172예요.","5 × 43 = 215 — 200보다 커요.","그래서 가장 큰 수는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#22','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C9',3,'sa','auto','「침대를 만들기 위해 나무가 필요해. 우리 물건을 만드는 데 92만큼 필요하고, 걸리버의 물건을 만드는 데에는 41배가 더 필요해.」 걸리버의 침대에 필요한 나무는 얼마만큼인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"「침대를 만들기 위해 나무가 필요해. 우리 물건을 만드는 데 92만큼 필요하고, 걸리버의 물건을 만드는 데에는 41배가 더 필요해.」 걸리버의 침대에 필요한 나무는 얼마만큼인가요? 숫자로 쓰세요.","answer":["3772"],"explanation":["곱하는 수 41을 1과 40으로 갈라요.","92 × 1 = 92, 92 × 40 = 3680이에요 — 둘째 줄은 한 자리 밀어 써요.","92 + 3680 = 3772예요 — 3772만큼 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#23','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C8',4,'sa','auto','「스스로 마무리하기」 수 카드 2, 9, 7, 5 중에서 2장을 뽑아 한 번씩만 사용하여 두 자리 수를 만들려고 해요. 만들 수 있는 가장 큰 수와 가장 작은 수의 곱을 구해 보세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"「스스로 마무리하기」 수 카드 2, 9, 7, 5 중에서 2장을 뽑아 한 번씩만 사용하여 두 자리 수를 만들려고 해요. 만들 수 있는 가장 큰 수와 가장 작은 수의 곱을 구해 보세요. 숫자로 쓰세요.","answer":["2425"],"explanation":["가장 큰 두 자리 수는 97, 가장 작은 두 자리 수는 25예요.","97 × 5 = 485, 97 × 20 = 1940이에요.","97 × 25 = 2425예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#24','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C8',4,'sa','auto','「수학에 퐁당」 26 × 43을 선을 그어 구했어요. 선끼리 만나 생긴 점이 백의 자리 8개, 십의 자리 30개, 일의 자리 18개예요. 26 × 43은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"「수학에 퐁당」 26 × 43을 선을 그어 구했어요. 선끼리 만나 생긴 점이 백의 자리 8개, 십의 자리 30개, 일의 자리 18개예요. 26 × 43은 얼마인가요? 숫자로 쓰세요.","answer":["1118"],"explanation":["백의 자리 점 8개는 800, 십의 자리 점 30개는 300이에요.","일의 자리 점 18개는 18이에요.","800 + 300 + 18 = 1118이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_a#25','math',3,2,'u1','','tb_g3_2_math_u1_review_a','unit_review','M3-2-u1-C4',4,'essay','teacher','「서술형」 캐나다 돈 1달러는 우리나라 돈 972원과 같다고 합니다. 5달러인 인형을 고르면 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C4","difficulty":4,"kind":"essay","stem":"「서술형」 캐나다 돈 1달러는 우리나라 돈 972원과 같다고 합니다. 5달러인 인형을 고르면 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 1달러가 972원이므로 5달러는 972 × 5를 계산한다. 2 × 5 = 10에서 1을 올리고, 7 × 5 + 1 = 36에서 3을 올리고, 9 × 5 + 3 = 48이므로 972 × 5 = 4860(원)이다.","scoring_points":["식 972 × 5를 세웠는가","올림을 바르게 하여 4860을 구했는가","4860원이라고 답했는가"]},"explanation":["1달러 = 972원 → 5달러는 972 × 5.","일의 자리 2 × 5 = 10에서 1을 십의 자리로 올림, 십의 자리 7 × 5 + 1 = 36에서 3을 백의 자리로 올림, 백의 자리 9 × 5 + 3 = 48이에요.","972 × 5 = 4860 — 4860원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#1','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C2',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 307 × 3의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 307 × 3의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["일의 자리 7 × 3 = 21에서 2를 십의 자리로 올림해요.","307 × 3 = 921이에요.","?에 알맞은 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["올림","","","2",""],["","","3","0","7"],["×","","","","3"],["","","9",null,"1"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#2','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C6',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 7 × 26의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 7 × 26의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["곱하는 수 26을 6과 20으로 갈라요.","7 × 6 = 42, 7 × 20 = 140이에요 — 둘째 줄은 한 자리 밀어 써요.","?에 알맞은 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["","","","","7"],["×","","","2","6"],["","","","4","2"],["","","1","4",""],["","","1",null,"2"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#3','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C2',1,'sa','auto','216 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u1-C2","difficulty":1,"kind":"sa","stem":"216 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["864"],"explanation":["216을 200, 10, 6으로 갈라 4를 곱해요: 200 × 4 = 800, 10 × 4 = 40, 6 × 4 = 24.","일의 자리 6 × 4 = 24에서 2를 십의 자리로 올림해요.","800 + 40 + 24 = 864예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#4','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C5',1,'sa','auto','50 × 40은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"50 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["2000"],"explanation":["50 × 4 = 200이에요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","50 × 40은 200의 10배인 2000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#5','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C6',1,'sa','auto','3 × 42는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"3 × 42는 얼마인가요? 숫자로 쓰세요.","answer":["126"],"explanation":["곱하는 수 42를 2와 40으로 갈라요.","3 × 2 = 6, 3 × 40 = 120이에요 — 둘째 줄은 한 자리 밀어 써요.","6 + 120 = 126이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#6','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',1,'sa','auto','16 × 13은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"16 × 13은 얼마인가요? 숫자로 쓰세요.","answer":["208"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","16 × 3 = 48, 16 × 10 = 160이에요 — 둘째 줄은 한 자리 밀어 써요.","48 + 160 = 208이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#7','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C5',1,'mc','auto','「익힘」 26 × 20을 「방법 2」로 계산해요. 26 × 20 = 26 × 10 × 2 = □ × 2 = 520에서 □는 얼마인가요?',ARRAY['M3-2-u1-X06']::text[],false,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"「익힘」 26 × 20을 「방법 2」로 계산해요. 26 × 20 = 26 × 10 × 2 = □ × 2 = 520에서 □는 얼마인가요?","options":[{"t":"260","correct":true},{"t":"26","mis":"M3-2-u1-X06"},{"t":"2600","mis":"M3-2-u1-X06"}],"explanation":["26 × 10 = 260이에요.","260 × 2 = 520이에요.","「방법 1」 26 × 2 × 10 = 52 × 10 = 520으로도 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#8','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C5',1,'mc','auto','「익힘」 계산 결과가 다른 하나는 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],false,'{"seq":8,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"「익힘」 계산 결과가 다른 하나는 어느 것인가요?","options":[{"t":"24 × 50","correct":true},{"t":"52 × 20","mis":"M3-2-u1-X11"},{"t":"26 × 40","mis":"M3-2-u1-X11"}],"explanation":["52 × 20 = 1040, 26 × 40 = 1040이에요.","24 × 50 = 1200이에요.","다른 하나는 24 × 50이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#9','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C4',2,'mc','auto','「확인 문제」 종이봉투가 한 묶음에 326장씩 묶여 있습니다. 4묶음의 종이봉투는 모두 몇 장인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02']::text[],false,'{"seq":9,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"「확인 문제」 종이봉투가 한 묶음에 326장씩 묶여 있습니다. 4묶음의 종이봉투는 모두 몇 장인가요?","options":[{"t":"1304장","correct":true},{"t":"330장","mis":"M3-2-u1-X13"},{"t":"1284장","mis":"M3-2-u1-X02"}],"explanation":["326장씩 4번 — 곱셈식 326 × 4로 세워요.","일의 자리 6 × 4 = 24에서 2를 십의 자리로 올림, 십의 자리 2 × 4 + 2 = 10에서 1을 백의 자리로 올림, 백의 자리 3 × 4 + 1 = 13이에요.","326 × 4 = 1304 — 1304장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#10','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',2,'mc','auto','「확인 문제」 한 학급에 학생이 18명씩 있습니다. 전체 학급 수가 19학급이라면 학생은 모두 몇 명인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":10,"concept":"M3-2-u1-C8","difficulty":2,"kind":"mc","stem":"「확인 문제」 한 학급에 학생이 18명씩 있습니다. 전체 학급 수가 19학급이라면 학생은 모두 몇 명인가요?","options":[{"t":"342명","correct":true},{"t":"37명","mis":"M3-2-u1-X13"},{"t":"180명","mis":"M3-2-u1-X07"}],"explanation":["18명씩 19번 — 곱셈식 18 × 19로 세워요.","18 × 9 = 162, 18 × 10 = 180이에요 — 둘째 줄은 한 자리 밀어 써요.","18 × 19 = 342 — 342명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#11','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C3',2,'mc','auto','「이 단원 학습을 마치고」 12 × 19를 12 × 20으로 어림하면 약 몇 개인가요?',ARRAY['M3-2-u1-X06']::text[],false,'{"seq":11,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 12 × 19를 12 × 20으로 어림하면 약 몇 개인가요?","options":[{"t":"약 240개","correct":true},{"t":"약 120개","mis":"M3-2-u1-X06"},{"t":"약 2400개","mis":"M3-2-u1-X06"}],"explanation":["19는 20에 가까워요.","12 × 20 = 240이에요.","그래서 약 240개 — 계산하면 228개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#12','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C5',2,'sa','auto','미니 양배추가 한 상자에 30개씩 들어 있습니다. 30상자에 들어 있는 미니 양배추는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"미니 양배추가 한 상자에 30개씩 들어 있습니다. 30상자에 들어 있는 미니 양배추는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["30개씩 30번 — 곱셈식 30 × 30으로 세워요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","30 × 30 = 900 — 900개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#13','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C6',2,'sa','auto','8 × 14를 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"8 × 14를 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["곱하는 수 14를 4와 10으로 갈라요.","□는 8 × 4 = 32예요.","32 + 80 = 112 — 8 × 14의 곱이에요."],"asset":{"type":"expr_grid","rows":[["8 × 4","=",null],["8 × 10","=","80"],["□ + 80","=","112"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#14','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C7',2,'sa','auto','28 × 13을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u1-C7","difficulty":2,"kind":"sa","stem":"28 × 13을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["84"],"explanation":["곱하는 수 13을 3과 10으로 갈라요.","□는 28 × 3 = 84예요.","84 + 280 = 364 — 28 × 13의 곱이에요."],"asset":{"type":"expr_grid","rows":[["28 × 3","=",null],["28 × 10","=","280"],["□ + 280","=","364"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#15','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C3',2,'mc','auto','「익힘」 채원이는 29 × 13에서 29를 30으로 생각해서 어림했어요. 어림한 값은 약 얼마인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X06']::text[],false,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"「익힘」 채원이는 29 × 13에서 29를 30으로 생각해서 어림했어요. 어림한 값은 약 얼마인가요?","options":[{"t":"약 390","correct":true},{"t":"약 290","mis":"M3-2-u1-X12"},{"t":"약 39","mis":"M3-2-u1-X06"}],"explanation":["29를 30으로 생각해요.","30 × 13 = 390이에요.","그래서 약 390 — 계산하면 377이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#16','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C9',2,'sa','auto','걸리버에게 천이 138장의 6배 필요해요. 천은 몇 장 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"걸리버에게 천이 138장의 6배 필요해요. 천은 몇 장 필요한가요? 숫자로 쓰세요.","answer":["828"],"explanation":["138을 100, 30, 8로 갈라 6을 곱해요: 100 × 6 = 600, 30 × 6 = 180, 8 × 6 = 48.","일의 자리 8 × 6 = 48에서 4를 십의 자리로 올림, 십의 자리 3 × 6 + 4 = 22에서 2를 백의 자리로 올림해요.","600 + 180 + 48 = 828이에요 — 828장 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#17','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C1',3,'error','auto','320 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],false,'{"seq":17,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"320 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「320 × 3 = 963」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"건우 — 「900 + 60 + 0 = 960」","mis":"M3-2-u1-X15"},{"t":"채원 — 「0 × 3 = 0이라 일의 자리는 0」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","320 × 3 = 960이에요.","지유는 963으로 잘못 구했어요 — 0에 어떤 수를 곱해도 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#18','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C2',3,'ox','auto','142 × 4 = 424예요.',ARRAY['M3-2-u1-X17']::text[],false,'{"seq":18,"concept":"M3-2-u1-C2","difficulty":3,"kind":"ox","stem":"142 × 4 = 424예요.","answer":"X","reason_options":[{"t":"40 × 4 = 160이라 8 + 160 + 400 = 568이니까","correct":true},{"t":"40 × 4를 16으로 써서 8 + 16 + 400을 하면 되니까","mis":"M3-2-u1-X17"}],"mis":"M3-2-u1-X17","explanation":["2 × 4 = 8, 40 × 4 = 160이에요.","100 × 4 = 400이에요.","8 + 160 + 400 = 568 — 424가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#19','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',3,'mc','auto','친구가 37 × 48을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M3-2-u1-X10','M3-2-u1-X02']::text[],false,'{"seq":19,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 37 × 48을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"37 × 40 = 1480인데 148을 한 자리 밀어 쓰지 않았어요","correct":true},{"t":"앞 줄에서 올림한 수를 다음 줄에 더했어요","mis":"M3-2-u1-X10"},{"t":"올림한 수를 더하지 않았어요","mis":"M3-2-u1-X02"}],"explanation":["37 × 8 = 296이에요.","37 × 40 = 1480이에요.","296 + 1480 = 1776이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","7"],["×","","","4","8"],["","","2","9","6"],["","","1","4","8"],["","","4","4","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#20','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C5',3,'sa','auto','「익힘」 어떤 수에 30을 곱해야 할 것을 잘못하여 더했더니 100이 되었어요. 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u1-C5","difficulty":3,"kind":"sa","stem":"「익힘」 어떤 수에 30을 곱해야 할 것을 잘못하여 더했더니 100이 되었어요. 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.","answer":["2100"],"explanation":["어떤 수는 100 − 30 = 70이에요.","바르게 계산하면 70 × 30이에요.","70 × 3 = 210의 10배 — 2100이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#21','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C6',3,'mc','auto','「익힘」 암호 「수학은 내 친구」에서 「학」은 계산 결과 245에 알맞은 글자예요. 「학」에 해당하는 곱셈은 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],false,'{"seq":21,"concept":"M3-2-u1-C6","difficulty":3,"kind":"mc","stem":"「익힘」 암호 「수학은 내 친구」에서 「학」은 계산 결과 245에 알맞은 글자예요. 「학」에 해당하는 곱셈은 어느 것인가요?","options":[{"t":"7 × 35","correct":true},{"t":"9 × 27","mis":"M3-2-u1-X11"},{"t":"8 × 34","mis":"M3-2-u1-X11"}],"explanation":["7 × 35 = 245예요.","9 × 27 = 243, 8 × 34 = 272예요.","245와 243은 끝자리까지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#22','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C9',3,'sa','auto','「가방을 만들기 위해 가죽이 필요해. 우리 물건을 만드는 데 12만큼 필요하고, 걸리버의 물건을 만드는 데에는 25배가 더 필요해.」 걸리버의 가방에 필요한 가죽은 얼마만큼인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"「가방을 만들기 위해 가죽이 필요해. 우리 물건을 만드는 데 12만큼 필요하고, 걸리버의 물건을 만드는 데에는 25배가 더 필요해.」 걸리버의 가방에 필요한 가죽은 얼마만큼인가요? 숫자로 쓰세요.","answer":["300"],"explanation":["곱하는 수 25를 5와 20으로 갈라요.","12 × 5 = 60, 12 × 20 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","60 + 240 = 300이에요 — 300만큼 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#23','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C8',4,'sa','auto','「익힘」 수 카드 2, 4, 5, 6, 8 중에서 2장을 뽑아 한 번씩만 사용하여 두 자리 수를 만들려고 해요. 만들 수 있는 가장 큰 수와 가장 작은 수의 곱을 구해 보세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u1-C8","difficulty":4,"kind":"sa","stem":"「익힘」 수 카드 2, 4, 5, 6, 8 중에서 2장을 뽑아 한 번씩만 사용하여 두 자리 수를 만들려고 해요. 만들 수 있는 가장 큰 수와 가장 작은 수의 곱을 구해 보세요. 숫자로 쓰세요.","answer":["2064"],"explanation":["가장 큰 두 자리 수는 86, 가장 작은 두 자리 수는 24예요.","86 × 4 = 344, 86 × 20 = 1720이에요.","86 × 24 = 2064예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#24','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C7',4,'mc','auto','「고대 이집트 곱셈법」 24 × 1 = 24, 24 × 2 = 48, 24 × 4 = 96, 24 × 8 = 192를 구했어요. 24 × 13을 구하려면 어느 곱들을 더해야 하나요?',ARRAY['M3-2-u1-X11']::text[],false,'{"seq":24,"concept":"M3-2-u1-C7","difficulty":4,"kind":"mc","stem":"「고대 이집트 곱셈법」 24 × 1 = 24, 24 × 2 = 48, 24 × 4 = 96, 24 × 8 = 192를 구했어요. 24 × 13을 구하려면 어느 곱들을 더해야 하나요?","options":[{"t":"24 × 1, 24 × 4, 24 × 8","correct":true},{"t":"24 × 1, 24 × 2, 24 × 8","mis":"M3-2-u1-X11"},{"t":"24 × 2, 24 × 4, 24 × 8","mis":"M3-2-u1-X11"}],"explanation":["13 = 1 + 4 + 8이에요.","24 × 1 + 24 × 4 + 24 × 8 = 24 + 96 + 192예요.","24 + 96 + 192 = 312 — 24 × 13 = 312예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_b#25','math',3,2,'u1','','tb_g3_2_math_u1_review_b','unit_review','M3-2-u1-C4',4,'essay','teacher','「서술형」 캐나다 돈 1달러는 우리나라 돈 972원과 같다고 합니다. 2달러인 열쇠고리를 고르면 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C4","difficulty":4,"kind":"essay","stem":"「서술형」 캐나다 돈 1달러는 우리나라 돈 972원과 같다고 합니다. 2달러인 열쇠고리를 고르면 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 1달러가 972원이므로 2달러는 972 × 2를 계산한다. 2 × 2 = 4, 7 × 2 = 14에서 1을 올리고, 9 × 2 + 1 = 19이므로 972 × 2 = 1944(원)이다.","scoring_points":["식 972 × 2를 세웠는가","올림을 바르게 하여 1944를 구했는가","1944원이라고 답했는가"]},"explanation":["1달러 = 972원 → 2달러는 972 × 2.","십의 자리 7 × 2 = 14에서 1을 백의 자리로 올림, 백의 자리 9 × 2 + 1 = 19예요.","972 × 2 = 1944 — 1944원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#1','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 564 × 2의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 564 × 2의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["십의 자리 6 × 2 = 12에서 1을 백의 자리로 올림, 백의 자리 5 × 2 + 1 = 11이에요.","564 × 2 = 1128이에요.","?에 알맞은 숫자는 1이에요."],"asset":{"type":"expr_grid","rows":[["올림","","1","",""],["","","5","6","4"],["×","","","","2"],["","1",null,"2","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#2','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 48 × 36의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 48 × 36의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["곱하는 수 36을 6과 30으로 갈라요.","48 × 6 = 288, 48 × 30 = 1440이에요 — 둘째 줄은 한 자리 밀어 써요.","?에 알맞은 숫자는 4예요."],"asset":{"type":"expr_grid","rows":[["","","","4","8"],["×","","","3","6"],["","","2","8","8"],["","1",null,"4",""],["","1","7","2","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#3','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',1,'sa','auto','492 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"492 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["1476"],"explanation":["492를 400, 90, 2로 갈라 3을 곱해요: 400 × 3 = 1200, 90 × 3 = 270, 2 × 3 = 6.","십의 자리 9 × 3 = 27에서 2를 백의 자리로 올림, 백의 자리 4 × 3 + 2 = 14예요.","1200 + 270 + 6 = 1476이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#4','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C5',1,'sa','auto','60 × 30은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"60 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["1800"],"explanation":["60 × 3 = 180이에요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","60 × 30은 180의 10배인 1800이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#5','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C6',1,'sa','auto','9 × 82는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"9 × 82는 얼마인가요? 숫자로 쓰세요.","answer":["738"],"explanation":["곱하는 수 82를 2와 80으로 갈라요.","9 × 2 = 18, 9 × 80 = 720이에요 — 둘째 줄은 한 자리 밀어 써요.","18 + 720 = 738이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#6','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',1,'sa','auto','28 × 29는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"28 × 29는 얼마인가요? 숫자로 쓰세요.","answer":["812"],"explanation":["곱하는 수 29를 9와 20으로 갈라요.","28 × 9 = 252, 28 × 20 = 560이에요 — 둘째 줄은 한 자리 밀어 써요.","252 + 560 = 812예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#7','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C5',1,'mc','auto','「교과서 한 번 더」 13 × 30을 「방법 1」로 계산해요. 13 × 30 = 13 × 3 × 10 = □ × 10 = 390에서 □는 얼마인가요?',ARRAY['M3-2-u1-X06','M3-2-u1-X13']::text[],false,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"「교과서 한 번 더」 13 × 30을 「방법 1」로 계산해요. 13 × 30 = 13 × 3 × 10 = □ × 10 = 390에서 □는 얼마인가요?","options":[{"t":"39","correct":true},{"t":"390","mis":"M3-2-u1-X06"},{"t":"16","mis":"M3-2-u1-X13"}],"explanation":["13 × 3 = 39예요.","39 × 10 = 390이에요.","「방법 2」 13 × 10 × 3 = 130 × 3 = 390으로도 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#8','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C6',1,'mc','auto','「익힘」 계산 결과가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":8,"concept":"M3-2-u1-C6","difficulty":1,"kind":"mc","stem":"「익힘」 계산 결과가 가장 큰 것은 어느 것인가요?","options":[{"t":"3 × 36","correct":true},{"t":"6 × 15","mis":"M3-2-u1-X12"},{"t":"4 × 24","mis":"M3-2-u1-X12"}],"explanation":["4 × 24 = 96, 6 × 15 = 90이에요.","3 × 36 = 108이에요.","가장 큰 것은 3 × 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#9','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',2,'mc','auto','좌석이 274개인 영화관에서 영화를 하루에 6번 상영합니다. 영화를 관람할 수 있는 사람은 모두 몇 명인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02']::text[],false,'{"seq":9,"concept":"M3-2-u1-C4","difficulty":2,"kind":"mc","stem":"좌석이 274개인 영화관에서 영화를 하루에 6번 상영합니다. 영화를 관람할 수 있는 사람은 모두 몇 명인가요?","options":[{"t":"1644명","correct":true},{"t":"280명","mis":"M3-2-u1-X13"},{"t":"1624명","mis":"M3-2-u1-X02"}],"explanation":["274명씩 6번 — 곱셈식 274 × 6으로 세워요.","일의 자리 4 × 6 = 24에서 2를 십의 자리로 올림, 십의 자리 7 × 6 + 2 = 44에서 4를 백의 자리로 올림, 백의 자리 2 × 6 + 4 = 16이에요.","274 × 6 = 1644 — 1644명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#10','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',2,'mc','auto','「확인 문제」 귤이 한 상자에 35개씩 들어 있습니다. 49상자에 들어 있는 귤은 모두 몇 개인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":10,"concept":"M3-2-u1-C8","difficulty":2,"kind":"mc","stem":"「확인 문제」 귤이 한 상자에 35개씩 들어 있습니다. 49상자에 들어 있는 귤은 모두 몇 개인가요?","options":[{"t":"1715개","correct":true},{"t":"84개","mis":"M3-2-u1-X13"},{"t":"455개","mis":"M3-2-u1-X07"}],"explanation":["35개씩 49번 — 곱셈식 35 × 49로 세워요.","35 × 9 = 315, 35 × 40 = 1400이에요 — 둘째 줄은 한 자리 밀어 써요.","35 × 49 = 1715 — 1715개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#11','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C6',2,'sa','auto','「이 단원 학습을 마치고」 한 봉지에 6개씩 38봉지에 담은 고구마는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"「이 단원 학습을 마치고」 한 봉지에 6개씩 38봉지에 담은 고구마는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["228"],"explanation":["곱하는 수 38을 8과 30으로 갈라요.","6 × 8 = 48, 6 × 30 = 180이에요 — 둘째 줄은 한 자리 밀어 써요.","48 + 180 = 228이에요."],"asset":{"type":"expr_grid","rows":[["","","","","6"],["×","","","3","8"],["","","","4","8"],["","","1","8",""],["","",null,null,null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#12','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C5',2,'sa','auto','「교과서 한 번 더」 미니 양배추가 한 상자에 13개씩 들어 있습니다. 30상자에 들어 있는 미니 양배추는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"「교과서 한 번 더」 미니 양배추가 한 상자에 13개씩 들어 있습니다. 30상자에 들어 있는 미니 양배추는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["390"],"explanation":["13개씩 30번 — 곱셈식 13 × 30으로 세워요.","곱하는 수가 3에서 30으로 10배가 되면 곱도 10배예요.","13 × 30 = 390 — 390개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#13','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C6',2,'sa','auto','쿠키가 한 상자에 6개씩 있습니다. 15상자에 있는 쿠키는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"쿠키가 한 상자에 6개씩 있습니다. 15상자에 있는 쿠키는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["6개씩 15번 — 곱셈식 6 × 15로 세워요.","6 × 5 = 30, 6 × 10 = 60이에요 — 둘째 줄은 한 자리 밀어 써요.","6 × 15 = 90 — 90개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#14','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',2,'sa','auto','46 × 34를 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"46 × 34를 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["184"],"explanation":["곱하는 수 34를 4와 30으로 갈라요.","□는 46 × 4 = 184예요.","184 + 1380 = 1564 — 46 × 34의 곱이에요."],"asset":{"type":"expr_grid","rows":[["46 × 4","=",null],["46 × 30","=","1380"],["□ + 1380","=","1564"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#15','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C3',2,'mc','auto','24 × 13에서 24를 30으로, 13을 10으로 생각하여 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X06']::text[],false,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"24 × 13에서 24를 30으로, 13을 10으로 생각하여 어림하면 약 얼마인가요?","options":[{"t":"약 300","correct":true},{"t":"약 30","mis":"M3-2-u1-X06"},{"t":"약 3000","mis":"M3-2-u1-X06"}],"explanation":["24를 30, 13을 10으로 생각해요.","30 × 10 = 300이에요.","계산하면 312 — 어림한 값과 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#16','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C9',2,'sa','auto','걸리버는 마을 사람이 마시는 물 17잔의 27배를 마셔요. 물은 몇 잔 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"걸리버는 마을 사람이 마시는 물 17잔의 27배를 마셔요. 물은 몇 잔 필요한가요? 숫자로 쓰세요.","answer":["459"],"explanation":["곱하는 수 27을 7과 20으로 갈라요.","17 × 7 = 119, 17 × 20 = 340이에요 — 둘째 줄은 한 자리 밀어 써요.","119 + 340 = 459예요 — 459잔 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#17','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C1',3,'error','auto','103 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],false,'{"seq":17,"concept":"M3-2-u1-C1","difficulty":3,"kind":"error","stem":"103 × 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「103 × 3 = 339」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"도윤 — 「300 + 0 + 9 = 309」","mis":"M3-2-u1-X15"},{"t":"지유 — 「0 × 3 = 0이라 십의 자리는 0」","mis":"M3-2-u1-X15"}],"explanation":["어느 자리에서도 올림이 없어 자리마다 곱한 값을 그 자리에 바로 써요. 0인 자리의 곱은 0이에요.","103 × 3 = 309예요.","서준은 339로 잘못 구했어요 — 0에 어떤 수를 곱해도 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#18','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',3,'ox','auto','426 × 3 = 1278이에요.',ARRAY['M3-2-u1-X02']::text[],false,'{"seq":18,"concept":"M3-2-u1-C4","difficulty":3,"kind":"ox","stem":"426 × 3 = 1278이에요.","answer":"O","reason_options":[{"t":"6 × 3 = 18의 1을 올리고 2 × 3 + 1 = 7, 4 × 3 = 12라 1278이니까","correct":true},{"t":"올림한 1은 버려 1268이니까","mis":"M3-2-u1-X02"}],"mis":"M3-2-u1-X02","explanation":["6 × 3 = 18 — 8을 쓰고 1을 올려요.","2 × 3 + 1 = 7, 4 × 3 = 12예요.","426 × 3 = 1278 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#19','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C8',3,'mc','auto','친구가 63 × 45를 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X10']::text[],false,'{"seq":19,"concept":"M3-2-u1-C8","difficulty":3,"kind":"mc","stem":"친구가 63 × 45를 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"63 × 40 = 2520인데 올림한 1을 더하지 않아 2420으로 썼어요","correct":true},{"t":"둘째 줄을 한 자리 밀어 쓰지 않았어요","mis":"M3-2-u1-X07"},{"t":"앞 줄에서 올림한 수를 다음 줄에 더했어요","mis":"M3-2-u1-X10"}],"explanation":["63 × 5 = 315예요.","63 × 40 = 2520이에요.","315 + 2520 = 2835예요."],"asset":{"type":"expr_grid","rows":[["","","","6","3"],["×","","","4","5"],["","","3","1","5"],["","2","4","2",""],["","2","7","3","5"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#20','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C5',3,'mc','auto','「익힘」 한 상자에 12개씩 들어 있는 도넛이 40상자 있어요. 500명에게 한 개씩 나누어 준다면 받지 못하는 사람이 있나요?',ARRAY['M3-2-u1-X06','M3-2-u1-X13']::text[],false,'{"seq":20,"concept":"M3-2-u1-C5","difficulty":3,"kind":"mc","stem":"「익힘」 한 상자에 12개씩 들어 있는 도넛이 40상자 있어요. 500명에게 한 개씩 나누어 준다면 받지 못하는 사람이 있나요?","options":[{"t":"있어요 — 도넛은 480개라 500개보다 적어요","correct":true},{"t":"없어요 — 12 × 40 = 4800개라 충분해요","mis":"M3-2-u1-X06"},{"t":"없어요 — 12 + 40 = 52상자라 충분해요","mis":"M3-2-u1-X13"}],"explanation":["도넛은 12 × 40개예요.","12 × 4 = 48의 10배 — 480개예요.","480 < 500 — 받지 못하는 사람이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#21','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C6',3,'error','auto','7 × 16을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X07','M3-2-u1-X15']::text[],false,'{"seq":21,"concept":"M3-2-u1-C6","difficulty":3,"kind":"error","stem":"7 × 16을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「7 × 16 = 49」","correct":true,"mis_target":"M3-2-u1-X07"},{"t":"도윤 — 「7 × 6 = 42, 7 × 10 = 70이라 112」","mis":"M3-2-u1-X15"},{"t":"채원 — 「16 × 7 = 112와 같아」","mis":"M3-2-u1-X15"}],"explanation":["7 × 6 = 42, 7 × 10 = 70이에요 — 둘째 줄은 한 자리 밀어 써요.","7 × 16 = 112예요.","건우는 49로 잘못 구했어요 — 십의 자리 곱은 한 자리 밀어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#22','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C9',3,'sa','auto','「익힘」 걸리버를 위한 사과는 마을 사람이 먹는 양의 35배예요. 마을 사람이 사과를 8개 먹는다면 걸리버에게 필요한 사과는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"「익힘」 걸리버를 위한 사과는 마을 사람이 먹는 양의 35배예요. 마을 사람이 사과를 8개 먹는다면 걸리버에게 필요한 사과는 몇 개인가요? 숫자로 쓰세요.","answer":["280"],"explanation":["곱하는 수 35를 5와 30으로 갈라요.","8 × 5 = 40, 8 × 30 = 240이에요 — 둘째 줄은 한 자리 밀어 써요.","40 + 240 = 280이에요 — 280개 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#23','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',4,'sa','auto','「익힘」 수 카드 0, 1, 2, 3을 한 번씩만 사용하여 계산 결과가 가장 큰 (세 자리 수) × (한 자리 수)를 만들었어요. 그 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"「익힘」 수 카드 0, 1, 2, 3을 한 번씩만 사용하여 계산 결과가 가장 큰 (세 자리 수) × (한 자리 수)를 만들었어요. 그 곱은 얼마인가요? 숫자로 쓰세요.","answer":["630"],"explanation":["가장 큰 수 3을 곱하는 수에 놓아요.","남은 2, 1, 0으로 가장 큰 세 자리 수 210을 만들어요.","210 × 3 = 630이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#24','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',4,'sa','auto','계산기로 99 × 2 = 2 × 100 − 2, 99 × 3 = 3 × 100 − 3인 규칙을 찾았어요. 이 규칙으로 99 × 4를 구하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u1-C4","difficulty":4,"kind":"sa","stem":"계산기로 99 × 2 = 2 × 100 − 2, 99 × 3 = 3 × 100 − 3인 규칙을 찾았어요. 이 규칙으로 99 × 4를 구하면 얼마인가요? 숫자로 쓰세요.","answer":["396"],"explanation":["99에 한 자리 수를 곱하면 (곱하는 수) × 100 − (곱하는 수)예요.","99 × 4 = 4 × 100 − 4예요.","400 − 4 = 396이에요."],"asset":{"type":"expr_grid","rows":[["99 × 2","=","2 × 100 − 2"],["99 × 3","=","3 × 100 − 3"],["99 × 4","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_c#25','math',3,2,'u1','','tb_g3_2_math_u1_review_c','unit_review','M3-2-u1-C4',4,'essay','teacher','「서술형」 캐나다 돈 1달러는 우리나라 돈 972원과 같다고 합니다. 3달러인 자석을 고르면 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C4","difficulty":4,"kind":"essay","stem":"「서술형」 캐나다 돈 1달러는 우리나라 돈 972원과 같다고 합니다. 3달러인 자석을 고르면 우리나라 돈으로 얼마인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 1달러가 972원이므로 3달러는 972 × 3을 계산한다. 2 × 3 = 6, 7 × 3 = 21에서 2를 올리고, 9 × 3 + 2 = 29이므로 972 × 3 = 2916(원)이다.","scoring_points":["식 972 × 3을 세웠는가","올림을 바르게 하여 2916을 구했는가","2916원이라고 답했는가"]},"explanation":["1달러 = 972원 → 3달러는 972 × 3.","십의 자리 7 × 3 = 21에서 2를 백의 자리로 올림, 백의 자리 9 × 3 + 2 = 29예요.","972 × 3 = 2916 — 2916원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#1','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 426 × 3의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 426 × 3의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["일의 자리 6 × 3 = 18에서 1을 십의 자리로 올림, 백의 자리 4 × 3 = 12예요.","426 × 3 = 1278이에요.","?에 알맞은 숫자는 2예요."],"asset":{"type":"expr_grid","rows":[["올림","","","1",""],["","","4","2","6"],["×","","","","3"],["","1",null,"7","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#2','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 39 × 26의 세로셈에서 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 39 × 26의 세로셈에서 ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["곱하는 수 26을 6과 20으로 갈라요.","39 × 6 = 234, 39 × 20 = 780이에요 — 둘째 줄은 한 자리 밀어 써요.","?에 알맞은 숫자는 8이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","9"],["×","","","2","6"],["","","2","3","4"],["","","7",null,""],["","1","0","1","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#3','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',1,'sa','auto','253 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u1-C4","difficulty":1,"kind":"sa","stem":"253 × 7은 얼마인가요? 숫자로 쓰세요.","answer":["1771"],"explanation":["253을 200, 50, 3으로 갈라 7을 곱해요: 200 × 7 = 1400, 50 × 7 = 350, 3 × 7 = 21.","일의 자리 3 × 7 = 21에서 2를 십의 자리로 올림, 십의 자리 5 × 7 + 2 = 37에서 3을 백의 자리로 올림, 백의 자리 2 × 7 + 3 = 17이에요.","1400 + 350 + 21 = 1771이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#4','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',1,'sa','auto','38 × 20은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u1-C5","difficulty":1,"kind":"sa","stem":"38 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["760"],"explanation":["곱하는 수 20의 0을 잠시 떼고 38 × 2 = 76이에요.","곱하는 수가 2에서 20으로 10배가 되면 곱도 10배예요.","38 × 20은 76의 10배인 760이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#5','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C6',1,'sa','auto','8 × 74는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M3-2-u1-C6","difficulty":1,"kind":"sa","stem":"8 × 74는 얼마인가요? 숫자로 쓰세요.","answer":["592"],"explanation":["곱하는 수 74를 4와 70으로 갈라요.","8 × 4 = 32, 8 × 70 = 560이에요 — 둘째 줄은 한 자리 밀어 써요.","32 + 560 = 592예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#6','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',1,'sa','auto','43 × 36은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u1-C8","difficulty":1,"kind":"sa","stem":"43 × 36은 얼마인가요? 숫자로 쓰세요.","answer":["1548"],"explanation":["곱하는 수 36을 6과 30으로 갈라요.","43 × 6 = 258, 43 × 30 = 1290이에요 — 둘째 줄은 한 자리 밀어 써요.","258 + 1290 = 1548이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#7','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',1,'mc','auto','14 × 20을 「방법 2」로 계산해요. 14 × 20 = 14 × 10 × 2 = □ × 2 = 280에서 □는 얼마인가요?',ARRAY['M3-2-u1-X06']::text[],false,'{"seq":7,"concept":"M3-2-u1-C5","difficulty":1,"kind":"mc","stem":"14 × 20을 「방법 2」로 계산해요. 14 × 20 = 14 × 10 × 2 = □ × 2 = 280에서 □는 얼마인가요?","options":[{"t":"140","correct":true},{"t":"14","mis":"M3-2-u1-X06"},{"t":"1400","mis":"M3-2-u1-X06"}],"explanation":["14 × 10 = 140이에요.","140 × 2 = 280이에요.","「방법 1」 14 × 2 × 10 = 28 × 10 = 280으로도 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#8','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',1,'mc','auto','「익힘」 계산 결과가 더 작은 것은 어느 것인가요?',ARRAY['M3-2-u1-X12','M3-2-u1-X11']::text[],false,'{"seq":8,"concept":"M3-2-u1-C8","difficulty":1,"kind":"mc","stem":"「익힘」 계산 결과가 더 작은 것은 어느 것인가요?","options":[{"t":"53 × 25","correct":true},{"t":"34 × 41","mis":"M3-2-u1-X12"},{"t":"두 곱이 같아요","mis":"M3-2-u1-X11"}],"explanation":["53 × 25 = 1325예요.","34 × 41 = 1394예요.","1325 < 1394 — 53 × 25가 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#9','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C2',2,'mc','auto','한 대에 328명씩 탈 수 있는 비행기가 있습니다. 이 비행기 3대에 탈 수 있는 사람은 모두 몇 명인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X02']::text[],false,'{"seq":9,"concept":"M3-2-u1-C2","difficulty":2,"kind":"mc","stem":"한 대에 328명씩 탈 수 있는 비행기가 있습니다. 이 비행기 3대에 탈 수 있는 사람은 모두 몇 명인가요?","options":[{"t":"984명","correct":true},{"t":"331명","mis":"M3-2-u1-X13"},{"t":"964명","mis":"M3-2-u1-X02"}],"explanation":["328명씩 3번 — 곱셈식 328 × 3으로 세워요.","일의 자리 8 × 3 = 24에서 2를 십의 자리로 올림해요.","328 × 3 = 984 — 984명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#10','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',2,'mc','auto','45명씩 탈 수 있는 버스가 15대 있습니다. 버스에 탈 수 있는 사람은 모두 몇 명인가요?',ARRAY['M3-2-u1-X13','M3-2-u1-X07']::text[],false,'{"seq":10,"concept":"M3-2-u1-C8","difficulty":2,"kind":"mc","stem":"45명씩 탈 수 있는 버스가 15대 있습니다. 버스에 탈 수 있는 사람은 모두 몇 명인가요?","options":[{"t":"675명","correct":true},{"t":"60명","mis":"M3-2-u1-X13"},{"t":"270명","mis":"M3-2-u1-X07"}],"explanation":["45명씩 15번 — 곱셈식 45 × 15로 세워요.","45 × 5 = 225, 45 × 10 = 450이에요 — 둘째 줄은 한 자리 밀어 써요.","45 × 15 = 675 — 675명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#11','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',2,'sa','auto','「이 단원 학습을 마치고」 12 × 19를 세로셈으로 계산할 때 첫째 줄(12 × 9)에 쓰는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"「이 단원 학습을 마치고」 12 × 19를 세로셈으로 계산할 때 첫째 줄(12 × 9)에 쓰는 수는 얼마인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["19를 9와 10으로 갈라요.","첫째 줄은 12 × 9 = 108, 둘째 줄은 12 × 10 = 120이에요.","108 + 120 = 228이에요."],"asset":{"type":"expr_grid","rows":[["","","","1","2"],["×","","","1","9"],["","",null,null,null],["","","1","2",""],["","","2","2","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#12','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',2,'sa','auto','상추 모종을 한 줄에 32개씩 심으려고 합니다. 40줄을 심으려면 상추 모종은 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M3-2-u1-C5","difficulty":2,"kind":"sa","stem":"상추 모종을 한 줄에 32개씩 심으려고 합니다. 40줄을 심으려면 상추 모종은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["1280"],"explanation":["32개씩 40번 — 곱셈식 32 × 40으로 세워요.","곱하는 수가 4에서 40으로 10배가 되면 곱도 10배예요.","32 × 40 = 1280 — 1280개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#13','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C6',2,'sa','auto','「교과서 한 번 더」 신선한 당근이 한 봉지에 7개씩 25봉지가 있어요. 당근은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M3-2-u1-C6","difficulty":2,"kind":"sa","stem":"「교과서 한 번 더」 신선한 당근이 한 봉지에 7개씩 25봉지가 있어요. 당근은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["175"],"explanation":["7개씩 25번 — 곱셈식 7 × 25로 세워요.","7 × 5 = 35, 7 × 20 = 140이에요 — 둘째 줄은 한 자리 밀어 써요.","7 × 25 = 175 — 175개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#14','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C8',2,'sa','auto','39 × 26을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u1-C8","difficulty":2,"kind":"sa","stem":"39 × 26을 곱하는 수를 갈라 계산했어요. □에 알맞은 수를 쓰세요.","answer":["234"],"explanation":["곱하는 수 26을 6과 20으로 갈라요.","□는 39 × 6 = 234예요.","234 + 780 = 1014 — 39 × 26의 곱이에요."],"asset":{"type":"expr_grid","rows":[["39 × 6","=",null],["39 × 20","=","780"],["□ + 780","=","1014"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#15','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C3',2,'mc','auto','426 × 3에서 426을 400으로 생각하여 어림하면 약 얼마인가요?',ARRAY['M3-2-u1-X06']::text[],false,'{"seq":15,"concept":"M3-2-u1-C3","difficulty":2,"kind":"mc","stem":"426 × 3에서 426을 400으로 생각하여 어림하면 약 얼마인가요?","options":[{"t":"약 1200","correct":true},{"t":"약 120","mis":"M3-2-u1-X06"},{"t":"약 12000","mis":"M3-2-u1-X06"}],"explanation":["426을 400으로 생각해요.","400 × 3 = 1200이에요.","계산하면 1278 — 어림한 값과 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#16','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C9',2,'sa','auto','걸리버에게 물고기가 5마리의 49배 필요해요. 물고기는 몇 마리 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u1-C9","difficulty":2,"kind":"sa","stem":"걸리버에게 물고기가 5마리의 49배 필요해요. 물고기는 몇 마리 필요한가요? 숫자로 쓰세요.","answer":["245"],"explanation":["곱하는 수 49를 9와 40으로 갈라요.","5 × 9 = 45, 5 × 40 = 200이에요 — 둘째 줄은 한 자리 밀어 써요.","45 + 200 = 245예요 — 245마리 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#17','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',3,'error','auto','390 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u1-X05','M3-2-u1-X15']::text[],false,'{"seq":17,"concept":"M3-2-u1-C4","difficulty":3,"kind":"error","stem":"390 × 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「390 × 5 = 1955」","correct":true,"mis_target":"M3-2-u1-X05"},{"t":"지유 — 「1500 + 450 + 0 = 1950」","mis":"M3-2-u1-X15"},{"t":"건우 — 「0 × 5 = 0이라 일의 자리는 0」","mis":"M3-2-u1-X15"}],"explanation":["십의 자리 9 × 5 = 45에서 4를 백의 자리로 올림, 백의 자리 3 × 5 + 4 = 19예요.","390 × 5 = 1950이에요.","채원은 1955로 잘못 구했어요 — 0에 어떤 수를 곱해도 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#18','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C4',3,'ox','auto','274 × 7 = 1918이에요.',ARRAY['M3-2-u1-X04']::text[],false,'{"seq":18,"concept":"M3-2-u1-C4","difficulty":3,"kind":"ox","stem":"274 × 7 = 1918이에요.","answer":"O","reason_options":[{"t":"28 + 490 + 1400 = 1918이니까","correct":true},{"t":"자리마다 곱한 14, 49, 28을 이어 쓰면 되니까","mis":"M3-2-u1-X04"}],"mis":"M3-2-u1-X04","explanation":["4 × 7 = 28, 70 × 7 = 490이에요.","200 × 7 = 1400이에요.","28 + 490 + 1400 = 1918 — 맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#19','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C7',3,'mc','auto','친구가 24 × 13을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?',ARRAY['M3-2-u1-X10','M3-2-u1-X08']::text[],false,'{"seq":19,"concept":"M3-2-u1-C7","difficulty":3,"kind":"mc","stem":"친구가 24 × 13을 오른쪽처럼 계산했어요. 잘못 계산한 까닭은 무엇인가요?","options":[{"t":"24 × 10 = 240인데 24를 한 자리 밀어 쓰지 않았어요","correct":true},{"t":"앞 줄에서 올림한 수를 다음 줄에 더했어요","mis":"M3-2-u1-X10"},{"t":"곱하는 수를 갈라 곱한 것 가운데 하나만 더했어요","mis":"M3-2-u1-X08"}],"explanation":["24 × 3 = 72예요.","24 × 10 = 240 — 24를 한 자리 밀어 써요.","72 + 240 = 312예요."],"asset":{"type":"expr_grid","rows":[["","","","2","4"],["×","","","1","3"],["","","","7","2"],["","","","2","4"],["","","","9","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#20','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C5',3,'mc','auto','계산 결과가 1200인 곱셈을 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u1-X11']::text[],false,'{"seq":20,"concept":"M3-2-u1-C5","difficulty":3,"kind":"mc","stem":"계산 결과가 1200인 곱셈을 모두 고른 것은 어느 것인가요?","options":[{"t":"60 × 20, 24 × 50","correct":true},{"t":"60 × 20, 52 × 20","mis":"M3-2-u1-X11"},{"t":"24 × 50, 26 × 40","mis":"M3-2-u1-X11"}],"explanation":["60 × 20 = 1200, 24 × 50 = 1200이에요.","52 × 20 = 1040, 26 × 40 = 1040이에요.","1200인 것은 60 × 20과 24 × 50이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#21','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C6',3,'mc','auto','연필 한 묶음이 12자루씩 6묶음인 상황과 6자루씩 12묶음인 상황을 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u1-X21','M3-2-u1-X16']::text[],false,'{"seq":21,"concept":"M3-2-u1-C6","difficulty":3,"kind":"mc","stem":"연필 한 묶음이 12자루씩 6묶음인 상황과 6자루씩 12묶음인 상황을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱은 72로 같지만 두 상황은 달라요","correct":true},{"t":"곱이 같으니 두 상황도 똑같아요","mis":"M3-2-u1-X21"},{"t":"곱하는 순서가 바뀌면 곱도 달라요","mis":"M3-2-u1-X16"}],"explanation":["12 × 6 = 72, 6 × 12 = 72예요.","12 × 6은 12자루씩 6묶음, 6 × 12는 6자루씩 12묶음이에요.","곱은 같아도 나타내는 상황은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#22','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C9',3,'sa','auto','「익힘」 걸리버의 신발에는 마을 사람 신발에 드는 가죽의 19배가 필요해요. 마을 사람에게 가죽이 51장 든다면 걸리버에게 필요한 가죽은 몇 장인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u1-C9","difficulty":3,"kind":"sa","stem":"「익힘」 걸리버의 신발에는 마을 사람 신발에 드는 가죽의 19배가 필요해요. 마을 사람에게 가죽이 51장 든다면 걸리버에게 필요한 가죽은 몇 장인가요? 숫자로 쓰세요.","answer":["969"],"explanation":["곱하는 수 19를 9와 10으로 갈라요.","51 × 9 = 459, 51 × 10 = 510이에요 — 둘째 줄은 한 자리 밀어 써요.","459 + 510 = 969예요 — 969장 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#23','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C1',4,'sa','auto','수 카드 0, 1, 2, 3을 한 번씩만 사용하여 (세 자리 수) × (한 자리 수)를 만들어요. 세 자리 수의 백의 자리와 한 자리 수에는 0을 쓰지 않아요. 계산 결과가 가장 작은 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u1-C1","difficulty":4,"kind":"sa","stem":"수 카드 0, 1, 2, 3을 한 번씩만 사용하여 (세 자리 수) × (한 자리 수)를 만들어요. 세 자리 수의 백의 자리와 한 자리 수에는 0을 쓰지 않아요. 계산 결과가 가장 작은 곱은 얼마인가요? 숫자로 쓰세요.","answer":["203"],"explanation":["곱하는 수를 1로 하면 남은 0, 2, 3으로 가장 작은 세 자리 수 203을 만들어요 — 203 × 1 = 203.","곱하는 수를 2로 하면 103 × 2 = 206, 3으로 하면 102 × 3 = 306이에요.","가장 작은 곱은 203이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#24','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C3',4,'mc','auto','378 × 2를 어림해요. 300 × 2 = 600에 78을 80으로 생각한 80 × 2 = 160을 더하면 약 얼마인가요?',ARRAY['M3-2-u1-X12']::text[],false,'{"seq":24,"concept":"M3-2-u1-C3","difficulty":4,"kind":"mc","stem":"378 × 2를 어림해요. 300 × 2 = 600에 78을 80으로 생각한 80 × 2 = 160을 더하면 약 얼마인가요?","options":[{"t":"약 760","correct":true},{"t":"약 600","mis":"M3-2-u1-X12"},{"t":"약 1600","mis":"M3-2-u1-X12"}],"explanation":["300 × 2 = 600 — 378 × 2는 600보다 커요.","78을 80으로 보면 80 × 2 = 160이에요.","600 + 160 = 760 — 378 × 2는 약 760이에요(계산하면 756)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u1_review_d#25','math',3,2,'u1','','tb_g3_2_math_u1_review_d','unit_review','M3-2-u1-C6',4,'essay','teacher','「이 단원 학습을 마치고」 한 반은 고구마를 한 봉지에 6개씩 38봉지, 다른 반은 한 상자에 12개씩 19상자에 담았어요. 두 반이 캔 고구마의 수를 각각 구하고, 어느 반이 더 많이 캤는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u1-C6","difficulty":4,"kind":"essay","stem":"「이 단원 학습을 마치고」 한 반은 고구마를 한 봉지에 6개씩 38봉지, 다른 반은 한 상자에 12개씩 19상자에 담았어요. 두 반이 캔 고구마의 수를 각각 구하고, 어느 반이 더 많이 캤는지 설명해 보세요.","answer_guide":{"answer":"예: 6 × 38 = 48 + 180 = 228(개), 12 × 19 = 108 + 120 = 228(개)이다. 두 반 모두 228개로 똑같이 캤다. 12 × 20으로 어림하면 약 240이지만 정확히 계산해 보아야 알 수 있다.","scoring_points":["6 × 38 = 228을 구했는가","12 × 19 = 228을 구했는가","두 반이 같다고 설명했는가"]},"explanation":["6 × 38 = 228.","12 × 19 = 228.","두 반이 똑같이 캤어요 — 어림만으로 판단하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
